(window.GIM_TS=window.GIM_TS||{})["Kiddushin.5"]={"from":120,"a":[["\u0003\"חרב תאכלו\"?\u0004 (ישעיה א, כ)? \u0003אמר רבא:\u0004 יש לפרש כאילו היה כתוב \"חרב תאכלו\" — מאכל המזיק לגוף כחרב. והכוונה היא ל\u0003מילחא גללניתא, נהמא דשערי אקושא, ובצלי\u0004 \u0005[מלח בגרגרים גסים, לחם שעורים קשה, ובצלים].\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003פת פורני חריבה\u0004 \u0005[פת מאפיה יבשה]\u0006 שאוכלים \u0003במלח, ובצלים\u0004 — \u0003קשים לגוף כחרבות.\u0004","ושואלים עוד: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' חנינא בן גמליאל היינו דכתיב\u0004 \u0005[זה הוא שנאמר]\u0006 \u0003\"אם לא שכב איש אתך ואם לא שטית טמאה תחת אישך הנקי\"\u0004 (במדבר ה, יט), ולא נתפרש צד השלילה בתנאי זה, \u0003אלא לר' מאיר \"\u0004ואם שכב איש אותך \u0003חנקי\"\u0004 (תיחנקי, תמותי) \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 שלשיטתו היה צריך לפרש גם מה יקרה בצד האחר של התנאי ומה העונש שלו. \u0003אמר ר' תנחום:\u0004 באמת \u0003\"הנקי\" כתיב\u0004 \u0005[כתוב]\u0006 בכתיב חסר, שאפשר לדרוש את הכתוב גם באופן זה.","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לר' מאיר היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"הנקי\"\u0004 חסר, ללמוד גם את צידו השני של התנאי; \u0003אלא לר' חנינא בן גמליאל למה לי\u0004 (לו) לומר דבר זה? ומשיבים: \u0003אצטריך\u0004 \u0005[צריך]\u0006 הדבר לאומרו כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003\"אם לא שכב איש\"\u0004 — \u0003הנקי, \"ואם שכב\"\u0004 — \u0003לא הנקי ולא חנקי, אלא איסורא בעלמא\u0004 \u0005[איסור בלבד]\u0006 אבל אין בכך עונש, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בכתיב החסר שלא.","ועוד, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' מאיר\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 לגבי אפר פרה אדומה \"הנוגע במת... וטמא שבעת ימים \u0003הוא יתחטא בו ביום השלישי וביום השביעי יטהר ואם לא יתחטא\u0004 ביום השלישי וביום השביעי לא יטהר\" (שם יט, יא–יב), \u0003אלא ל\u0004דעת \u0003ר' חנינא בן גמליאל למה לי\u0004 כפילות זו?","ומשיבים: \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 הדבר לאומרו, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003מצות הזאה בשלישי ובשביעי\u0004 לכתחילה, \u0003והיכא דעבד בחד מינייהו\u0004 \u0005[והיכן שעשה באחד מהם\u0006 בלבד\u0005]\u0006 \u0003עבד\u0004 — \u0005[עשה]\u0006 והוא טהור בדיעבד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף בדיעבד אינו טהור.","ושואלים על פסוק נוסף בהמשך: \u0003\"והזה הטהר על הטמא ביום השלישי וביום השביעי\"\u0004 (שם, יט) \u0003למה לי\u0004 לכפול את הציווי? ומשיבים: \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 כי \u0003שלישי\u0004 כוונתו \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003שני\u0004 שאינו יכול להזות לפני היום השלישי, וכן \u0003שביעי למעוטי\u0004 \u0005[למעט]\u0006 \u0003ששי,\u0004 שאינו יכול להזות לפני כן, משום \u0003דקא\u0004 \u0005[שהוא]\u0006 \u0003ממעט בימי טהרה\u0004 לפני ההזאה, \u0003אבל היכא דעבד\u0004 \u0005[מקום שעשה]\u0006 למשל \u0003בשלישי ובשמיני, דקא מפיש\u0004 \u0005[שמוסיף,\u0006 מרבה\u0005]\u0006 \u0003בימי טהרה\u0004 — \u0003אימא שפיר דמי\u0004 \u0005[אמור שטוב הדבר],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שצריך להיות גם מרחק קבוע של ארבעה ימים בין ההזאות.","ושואלים: הכתוב \u0003\"וחטאו ביום השביעי\"\u0004 (שם) \u0003למה לי?\u0004 ומשיבים: \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 הדבר לאומרו, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שצריך להטהר שתי פעמים הם רק \u0003ל\u0004ענין אכילה ונגיעה ב\u0003קדשים, אבל לתרומה\u0004 — \u0003בחד נמי סגיא\u0004 \u0005[ב\u0006הזאה \u0005אחת גם כן מספיק],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא.","\u0003המקדש את האשה ואמר\u0004 לאחר מכן: \u0003כסבור הייתי\u0004 כשקידשתיה \u0003שהיא כהנת\u0004 (בת למשפחת כהנים) \u0003ו\u0004נמצא ש\u0003הרי היא לויה,\u0004 או שחשב שהיא \u0003לויה והרי היא כהנת,\u0004 או שחשב שהיא \u0003עניה והרי היא עשירה,\u0004 או שהיא \u0003עשירה והרי היא עניה\u0004 — \u0003הרי זו מקודשת, מפני ש\u0004היא \u0003לא הטעתו\u0004 ולא היה ביניהם תנאי מפורש בדבר.","\u0003האומר לאשה \"הרי את מקודשת לי לאחר שאתגייר\", או\u0004 שאמר לה \"הרי את מקודשת לי \u0003לאחר שתתגיירי\u0004 את\", או שהיה עבד ואמר \u0003\"\u0004הרי את מקודשת לי \u0003לאחר שאשתחרר\", או\u0004 שהיא היתה שפחה ואמר לה \u0003\"לאחר שתשתחררי\",\u0004 או שאומר לאשת איש \u0003\"לאחר שימות בעליך\", או\u0004 לאחות אשתו \u0003\"לאחר שתמות אחותיך\",\u0004 או לזקוקה לייבום (שלדעת תנא זה אין קידושין תופסים בה) \u0003\"לאחר שיחלוץ ליך\u0004 (לך) \u0003יבמיך\u0004 (זה שאת זקוקה לו לייבום \u0003\"\u0004— בכל אלה \u0003אינה מקודשת,\u0004 שכיון שעתה אין קידושין יכולים לחול בה, נמצא שהוא מקדש באופן שלא בא לעולם עדיין ואינו קיים במציאות.","\u0003וכן האומר לחבירו: \"אם ילדה\u0004 (תלד) \u0003אשתך נקבה הרי זו מקודשת לי\"\u0004 — גם אם נולדה בת \u0003אינה מקודשת.\u0004 אבל \u0003אם\u0004 כשאמר לשון זו \u0003היתה אשת חברו מעוברת ו\u0004כבר \u0003הוכר עוברה\u0004 באותה שעה, שהיה ידוע שהיא מעוברת — \u0003דבריו קיימין, ואם ילדה נקבה\u0004 — \u0003מקודשת.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה: \u0003אין תורמין מן\u0004 הפרי \u0003התלוש\u0004 מן הקרקע \u0003על\u0004 הפרי \u0003המחובר\u0004 לקרקע, שעדיין אין הפרי המחובר חייב בתרומה. \u0003ואם תרם\u0004 — \u0003אין תרומתו תרומה\u0004 גם כשיתלשו.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב אסי מר' יוחנן:\u0004 אם \u0003אמר \"פירות ערוגה זו\u0004 שהם \u0003תלושים, יהיו תרומה על פירות ערוגה זו\u0004 ה\u0003מחוברים\",\u0004 או \u0003\"פירות ערוגה זו\u0004 ה\u0003מחוברים יהיו תרומה על פירות ערוגה זו\u0004 ה\u0003תלושים,\u0004 לא עכשיו אלא \u0003לכשיתלשו\", ונתלשו, מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כל\u0004 דבר \u0003שבידו\u0004 לעשותו \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כמחוסר מעשה דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 וכיון שבידו לתלוש כעת את הפירות המחוברים, חל דין תרומה עליהם.","\u0003איתיביה\u0004 \u0005[הקשה לו]:\u0006 \u0003האומר לאשה \"הרי את מקודשת לי לאחר שאתגייר\",\u0004 או \u0003\"לאחר שתתגיירי\",\u0004 או \u0003\"לאחר שאשתחרר\",\u0004 או \u0003\"לאחר שתשתחררי\",\u0004 או \u0003\"לאחר שימות בעליך\",\u0004 או \u0003\"לאחר שתמות אחותיך\",\u0004 או \u0003\"לאחר שיחלוץ ליך יבמיך\"\u0004 — \u0003אינה מקודשת.\u0004","\u0003בשלמא כולהו\u0004 \u0005[נניח כולם]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בידו\u0004 הם, וכל דבר שאינו כעת במציאות אין דרך לקנותו, \u0003אלא גר\u0004 (כלומר, האומר \"לאחר שאתגייר\") \u0003הוי\u0004 \u0005[הרי]\u0006 \u0003בידו\u0004 הדבר, שאם ירצה יתגייר, ולשיטת ר' יוחנן כיון שיכול לעשות את הדבר כעת הריהו כאילו נעשה! ודוחים: \u0003גר נמי לאו\u0004 \u0005[גם כן לא]\u0006 \u0003בידו\u0004 \u0005[גם כן אינו בידו]\u0006 להתגייר בכל עת שירצה, ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן:\u0004"],["\u0003גר צריך שלשה\u0004 ישראלים שיקבל גרות בפניהם. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003\"משפט\u0004 אחד יהיה לכם כגר כאזרח\u0003\"\u0004 (ויקרא כד, כב) \u0003כתיב ביה\u0004 \u0005[נאמר בו]\u0006 בגר, וצריך לנהוג בגיורו כמו \u0003דין\u0004 (משפט), שצריך שיהיו בו שלושה דיינים, ואם כן \u0003מי יימר דמזדקקו ליה הני תלתא\u0004 \u0005[מי יאמר שיזקקו לו אותם שלושה]\u0006 ונמצא שאין הדבר בידו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אבא בר ממל: אלא מעתה, הנותן פרוטה לשפחתו\u0004 שלו, \u0003ואמר \"הרי את מקודשת לי לאחר שאשתחרריך\u0004 (שאשחררך)\" — \u0003הכי נמי דהוו\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שיהיו]\u0006 \u0003קידושין\u0004 כיון שבידו לשחררה? ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 — \u0003מעיקרא\u0004 היתה נחשבת השפחה ל\u0003בהמה, השתא\u0004 \u0005[עכשיו]\u0006 היא כ\u0003דעת אחרת,\u0004 שלאחר שנשתחררה הריהי כישראל ואינה נחשבת כאותה אישיות כלל.","ומקשים: \u0003ואלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' אושעיא: הנותן פרוטה לאשתו ואמר לה \"הרי את מקודשת לי לאחר שאגרשיך\"\u0004 — \u0003אינה מקודשת, הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003ל\u0004דעת \u0003ר' יוחנן\u0004 תאמר \u0003דהוו\u0004 \u0005[שיהיו]\u0006 \u0003קידושין\u0004 שהרי בידו לגרשה? ומשיבים: \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003בידו לגרשה,\u0004 אבל וכי \u0003בידו לקדשה\u0004 שלא מרצונה? ואם כן אין הדבר ברשותו, שלאחר שתתגרש תעמוד ברשות עצמה ולא יהא הדבר תלוי בו עוד.","ושואלים: אם כן, \u0003תפשוט\u0004 \u0005[תפתור]\u0006 מכאן את השאלה \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רב אושעיא: הנותן שתי פרוטות לאשה, באחת אמר לה \"התקדשי לי היום\", ובאחת אמר לה \"התקדשי לי לאחר שאגרשיך\"\u0004 שהשארנו את השאלה מה דינה של אשה זו לאחר שנתגרשה כשאלה ללא תשובה, \u0003תפשוט מינה\u0004 \u0005[תפתור מכאן]\u0006 \u0003שלא הוו\u0004 \u0005[יהיו]\u0006 \u0003קידושין!\u0004 ומשיבים: ספיקו של רב אושעיא היה \u0003דלמא\u0004 \u0005[שמא]\u0006 במקרה זה \u0003כי היכי דתפסי\u0004 \u0005[כמו שתופסים]\u0006 \u0003קידושין השתא\u0004 \u0005[עכשיו]\u0006 — \u0003תפסי נמי\u0004 \u0005[תופסים גם כן]\u0006 \u0003לאחר\u0004 מ\u0003כן,\u0004 שכיון שעכשיו היא ברשות עצמה ומסכימה להתקדש לו יכול הוא לקדשה מעכשיו גם לזמן אחר.","ומעירים: \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן:\u0004 \u0003אין תורמין מן התלוש על המחובר, ואם תרם\u0004 — \u0003אין תרומתו תרומה. כיצד? אמר \"פירות ערוגה זו\u0004 שהם \u0003תלושין יהיו תרומה על פירות ערוגה זו מחוברת\" או \"פירות ערוגה זו מחוברת יהיו תרומה על פירות ערוגה זו תלושין\" — לא אמר כלום,\u0004 שאין חובת תרומה אלא על התלוש. \u0003אבל אמר\u0004 שיהיו תרומה \u0003\"לכשיתלשו\" ונתלשו\u0004 — \u0003דבריו קיימין,\u0004 שבידו לתולשם.","\u0003יתר על כן אמר ר' אליעזר בן יעקב: אפילו אמר \"פירות ערוגה זו תלושין יהיו תרומה על פירות ערוגה זו מחוברת\",\u0004 או \u0003\"פירות ערוגה זו מחוברת יהיו תרומה על פירות ערוגה זו תלושין לכשיביאו שליש ויתלשו\"\u0004 ובאותה שעה עדיין לא הגיעו לבישול, ואז אין עליהם עוד כל חיובי תרומות ומעשרות כלל, \u0003והביאו שליש, ונתלשו\u0004 — \u0003דבריו קיימין.\u0004","\u0003אמר רבה: לא אמר ר' אליעזר בן יעקב אלא בשחת,\u0004 שאף שעדיין לא בשלו השיבולים היטב, מכל מקום יש כבר שיבולים, למרות שאינן בשלות, \u0003אבל באגם,\u0004 כלומר, שהתבואה היתה עדיין רכה לגמרי — \u0003לא. רב יוסף אמר: אפילו באגם.\u0004 ואגב הדברים שואלים: \u0003מאי משמע דהאי אגם לישנא דבוצלנא הוא\u0004 \u0005[כיצד משתמע שאגם זה לשון צמיחה היא]?\u0006 ומשיבים: \u0003אמר ר' אלעזר:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"הלכף כאגמן ראשו\"\u0004 (ישעיה נח, ה) כלומר, כצמח רך הנראה ככופף ראשו.","ושואלים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת\u0006 ברייתא \u0005זו ששנינו]:\u0006 \u0003האומר לחברו \"אם ילדה\u0004 (תלד) \u0003אשתך נקבה,\u0004 תהא אותה בת \u0003מקודשת לי\"\u0004 — \u0003לא אמר כלום. ואמר ר' חנינא: לא שנו\u0004 שלא אמר כלום \u0003אלא שאין אשתו מעוברת, אבל\u0004 אם \u0003אשתו מעוברת\u0004 — \u0003דבריו קיימין\u0004. \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 ומשיבים: את הברייתא אפשר לפרש כדברי הכל, \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003רבה\u0004 צריך לומר \u0003כשהוכר עוברה\u0004 כבר, כמו שחת, שניכרות בה כבר השיבולים, \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003רב יוסף\u0004 — \u0003אף על פי ש\u0004עדיין \u0003לא הוכר עוברה.\u0004","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 את כל המחלוקת הזו בלשון אחרת: \u0003אמר רבה: לא אמר ר' אליעזר בן יעקב\u0004 את דבריו \u0003אלא בשחת דבי כיבשא\u0004 \u0005[של שדה בעל]\u0006 שאינה צריכה השקיה, \u0003אבל בשחת דבי שקיא\u0004 \u0005[של בית שלחין, שצריך להשקות]\u0006 — \u0003לא,\u0004 כיון שאם לא ישקנה לא תגדל מעצמה, ונחשבת היא כדבר שלא בא לעולם כלל. \u0003רב יוסף אמר: אפילו בשחת דבי שקיא\u0004 \u0005[של בית שלחין]\u0006 שכיון שכבר הגיעה לכדי שחת הריהי דבר שבא לעולם.","ושואלים: לפי לשון זו של המחלוקת, \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת\u0006 ברייתא \u0005זו ששנינו]:\u0006 \u0003האומר לחבירו \"אם ילדה\u0004 (תלד) \u0003אשתך נקבה\u0004 תהא זו \u0003מקודשת לי\"\u0004 — \u0003לא אמר כלום. ואמר ר' חנינא: לא שנו אלא שאין אשתו מעוברת, אבל אשתו מעוברת\u0004 — \u0003דבריו קיימים. כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 — בודאי \u0003כשהוכר עוברה, ו\u0004אז הדברים הם כ\u0003דברי הכל,\u0004 כלומר, גם רבה וגם רב יוסף, שלא נאמרו דבריו של ר' אליעזר בן יעקב אלא בשחת שכבר ניכרות בה השיבולים.","\u0003אמר אביי: ר' אליעזר בן יעקב, ורבי, ור' מאיר כולהו סבירא להו\u0004 \u0005[כולם סבורים]\u0006 סברה אחת שווה — ש\u0003אדם\u0004 \u0003מקנה דבר שלא בא לעולם,\u0004 כלומר, שיכול להיות קנין בדבר שעדיין לא הגיע לעולם. \u0003ר' אליעזר בן יעקב\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 שיכול אדם להרים תרומה אפילו על דבר שלא הגיע עדיין לכלל חיוב במצוה זו. \u0003רבי\u0004 היכן מוצאים שגילה דעה זו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006"],["\u0003\"לא תסגיר עבד אל אדניו\"\u0004 (דברים כג, טז) \u0003רבי אומר: בלוקח\u0004 (קונה) \u0003עבד על מנת לשחררו הכתוב מדבר,\u0004 שאסור לבית דין להסגירו לאותו אדם, משום שאינו עבדו ואסור להשתעבד בו. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אמר רב נחמן בר יצחק: כגון\u0004 ש\u0003כתב ליה\u0004 \u0005[לו]\u0006 לעבד בשטר השחרור \u0003\"לכשאקחך, הרי עצמך קנוי לך מעכשיו\",\u0004 ואף שעדיין לא היה קנוי לו. ומכל מקום נקנה העבד לעצמו מאותה שעה. הרי שלדעתו אדם מקנה דבר שלא בא לעולם, שיכול אדם לעשות מעשה שחרור בעבדו עוד לפני שקנאו.","\u0003ר' מאיר, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר לאשה \"הרי את מקודשת לי לאחר שאתגייר\",\u0004 או \u0003\"לאחר שתתגיירי\",\u0004 או \u0003\"לאחר שאשתחרר\",\u0004 או \u0003\"לאחר שתשתחררי\",\u0004 או \u0003\"לאחר שימות בעליך\",\u0004 או \u0003\"לאחר שתמות אחותיך\",\u0004 או \u0003\"לאחר שיחלוץ לך יבמיך\"\u0004 — \u0003אינה מקודשת. ר' מאיר אומר: מקודשת. ר' יוחנן הסנדלר אומר: אינה מקודשת.\u0004","\u0003ר' יהודה הנשיא אומר: מקודשת. ומה טעם אמרו \"\u0004\u0003אינה מקודשת\"\u0004 — \u0003משום איבה,\u0004 בין האחיות, שקידושיה של אחת תלויים במותה של האחרת, ובין הבעל לאשתו. ומשום כך גזרו שלא תהיה מקודשת, אבל מעיקר הדין מקודשת היא. ומכל מקום, לשיטת ר' מאיר ור' יהודה הנשיא יכול אדם לקדש אשה גם אם עכשיו היא אסורה עליו, והרי זה דבר שלא בא לעולם.","ושואלים: \u0003ונחשוב נמי\u0004 \u0005[ושימנה,\u0006 בין הסבורים שאדם מקנה דבר שלא בא לעולם \u0005גם כן]\u0006 את \u0003ר' יהודה הנשיא!\u0004 ומשיבים: \u0003היינו רבי, היינו ר' יהודה הנשיא,\u0004 כלומר, זהו אותו התנא.","ושואלים: \u0003ונחשוב נמי\u0004 \u0005[ונמנה גם כן]\u0006 את \u0003ר' עקיבא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נדרה אשה לבעלה: \u0003\"קונם\u0004 (אסור כחרם) מה \u0003שאני עושה, לפיך\",\u0004 שלא תוכל להנות ממנו — \u0003אין\u0004 הבעל \u0003צריך להפר\u0004 את הנדר, משום שהיא חייבת מכוח הנישואין לעשות מלאכה עבורו ואין הנדר חל.","\u0003ר' עקיבא אומר:\u0004 מכל מקום \u0003יפר, שמא תעדיף עליו\u0004 (תרבה במלאכה עבורו) \u0003יתר מן הראוי לו\u0004 שקצבו חכמים לעבודת האשה, ועל העודף הזה חל האיסור, שהרי לגבי העודף אינה משועבדת לבעלה. ואף שבשעת הנדר לא היתה עדיין ההעדפה מכל מקום הנדר חל, משמע שיכול הנדר לחול אף על דבר שעדיין לא בא לעולם. ודוחים: \u0003האיתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 ש\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 כאן מדובר \u0003באומרת \"יקדשו ידי לעושיהם\"\u0004 (למי שעשה, שברא אותם), כלומר, שהיא מקדישה את ידיה עצמן, \u0003וידים\u0004 הרי \u0003איתנהו\u0004 \u0005[ישנן]\u0006 \u0003בעולם\u0004 ומשום כך חל הנדר.","\u0003האומר לאשה \"הרי את מקודשת לי על מנת שאדבר עליך\u0004 לטובה \u0003לשלטון\",\u0004 או \u0003\"\u0004על מנת ש\u0003אעשה\u0004 (אעבוד) \u0003עמך כפועל\",\u0004 אם \u0003דבר עליה לשלטון ועשה עמה כפועל\u0004 — \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 עשה כן — \u0003אינה מקודשת.\u0004","\u0003אמר ריש לקיש: והוא שנתן לה\u0004 בשעת קידושין \u0003שוה פרוטה,\u0004 אבל בדיבור או במלאכה עצמם אינה מתקדשת, אלא הם רק בגדר תנאי. ושואלים: \u0003ובשכר\u0004 העשיה והאמירה \u0003לא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 האומר לאשה \u0003\"\u0004הרי את מקודשת לי \u0003בשכר שהרכבתיך על החמור\",\u0004 או \u0003\"\u0004בשכר \u0003שהושבתיך בקרון\" או \"\u0004בשכר שהושבתיך \u0003בספינה\"\u0004 — \u0003אינה מקודשת,\u0004 שהרי זה כחוב שנתחייבה לו כבר, והמקדש במלוה שיש לו על האשה אינה מקודשת.","אבל אם אמר לה \u0003\"\u0004הרי את מקודשת לי \u0003בשכר שארכיבך על החמור\",\u0004 או \u0003\"\u0004הרי את מקודשת לי בשכר \u0003שאושיבך בקרון\" או \"\u0004שאושיבך \u0003בספינה\"\u0004 — \u0003מקודשת! וכי תימא\u0004 \u0005[ואם\u0006 \u0003תאמר]:\u0004 \u0003הכא נמי בדיהב\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005ב\u0006אופן \u0005שנתן]\u0006 \u0003לה שוה פרוטה, והא\u0004 \u0005[והרי]\u0006 \u0003\"בשכר\" קאמר\u0004 \u0005[אומר\u0006 הוא\u0005],\u0006 משמע שבשכר זה היא מתקדשת!","\u0003ועוד תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 אמרה האשה לגבר \u0003\"שב עמי בצוותא ואקדש לך\u0004 בשכר זה \u0003\",\u0004 או \u0003\"שחוק\u0004 (שחק) \u0003לפני\",\u0004 או \u0003\"רקוד לפני\",\u0004 או \u0003\"עשה\u0004 לי מלאכה \u0003כדימוס\u0004 (כנדבך הבנין) \u0003הזה\", שמין\u0004 (מעריכים), \u0003אם יש בו\u0004 בשירות שהוא נותן לה כדי \u0003שוה פרוטה\u0004 — \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה מקודשת! וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכא נמי בדיהב\u0004 \u0005[כאן גם כן\u0006 מדובר באופן \u0005שנתן]\u0006 \u0003לה שוה פרוטה\u0004 — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"שמין אותו\" קאמר\u0004 \u0005[אומר\u0006 הוא\u0005],\u0006 ואם היה זה רק תנאי, לשם מה צריך שומא. הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003ריש לקיש!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[יכול היה\u0006 \u0005לומר]\u0006 \u0003לך ריש לקיש: האי\u0004 \u0005[זה]\u0006 ה\u0003תנא ברא\u0004 \u0005[החיצון],\u0006 בעל המשנה החיצונית, הברייתא, \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003אינה לשכירות אלא לבסוף,\u0004 שחיוב תשלום שכר עבודה חל רק בסוף המלאכה, ובאותה שעה הריהי מתקדשת לו בכסף זה ואין זה מלוה. \u0003ו\u0004ה\u0003תנא דידן סבר\u0004 \u0005[שלנו סבור]\u0006 ש\u0003ישנה לשכירות מתחילה ועד סוף,\u0004 ובכל רגע ורגע של השכירות חל חיוב זה, ולכן בגמר העבודה נשאר רק חוב שהיא חייבת לו, ובמלוה אי אפשר לקדש.","ושואלים: \u0003ומאי דוחקיה\u0004 \u0005[ומה דוחקו]\u0006 של \u0003ריש לקיש לאוקמיה למתניתין\u0004 \u0005[להעמיד,\u0006 להסביר \u0005את משנתנו]\u0006 \u0003בישנה לשכירות מתחילה ועד סוף, ובדיהב\u0004 \u0005[ובשנתן]\u0006 \u0003לה\u0004 שווה פרוטה? ומדוע אינו מפרש כפשוטו שמקדשה בשכר הפעולה, וכדעת האומר שאינה לשכירות אלא לבסוף?","ומשיבים, \u0003אמר רבא: מתניתין קשיתיה\u0004 \u0005[המשנה היתה קשה לו];\u0006 \u0003מאי איריא דתני\u0004 \u0005[מה שייך, מדוע\u0006 דווקא \u0005שנה]\u0006 בלשון \u0003\"על מנת\"? ניתני\u0004 \u0005[שישנה]\u0006 בלשון \u0003\"בשכר\",\u0004 כמו בברייתא, \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003כל \"על מנת\"\u0004 הוא תנאי נוסף \u0003היכא דיהב\u0004 \u0005[היכן שנתן]\u0006 \u0003לה\u0004 כבר \u0003הוא\u0004 שווה פרוטה, ושכר הפעולה אינו עצם כסף הקידושין.","קידש את האשה ואמר לה \u0003\"על מנת שירצה אבא\u0004 בקדושין אלה \u0003\",\u0004 אם \u0003רצה האב\u0004 — \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה מקודשת.\u0004 אם \u0003מת האב\u0004 — \u0003הרי זו מקודשת\u0004 אף שלא גילה האב את דעתו. \u0003מת הבן\u0004 — \u0003מלמדין\u0004 את \u0003האב לומר שאינו רוצה,\u0004 ונמצאים קידושיה נעקרים למפרע, ולא תזדקק ליבום.","\u0003מאי\u0004 \u0005[מה]\u0006 משמעות \u0003\"על מנת שירצה אבא\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא \u0003עד דאמר אבא \"אין\"\u0004 \u0005[שיאמר האב \"כן\"]\u0006 ויגלה דעתו שהוא רוצה בכך, \u0003אימא מציעתא\u0004 \u0005[אמור\u0006 אם כן את \u0005אמצעה]\u0006 של המשנה: \u0003מת האב\u0004 — \u0003הרי זו מקודשת, והא\u0004 \u0005[והרי]\u0006 \u0003לא אמר \"אין\"\u0004 \u0005[\"כן\"]\u0006 ולא נתקיים התנאי! \u0003אלא:\u0004"],["\u0003על מנת שישתוק אבא,\u0004 שלא יאמר בשעת הקידושין שאינו רוצה. ואולם אם כן, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003מת הבן\u0004 — \u0003מלמדין את האב לומר שאינו רוצה. אמאי\u0004 \u0005[מדוע]\u0006 מועיל הדבר? \u0003והא שתיק\u0004 \u0005[והרי שתק]\u0006 תחילה כששמע זאת! אלא משמע ששתיקתו בלבד אינה נקראת רציה! \u0003אלא\u0004 בהכרח לומר ש\"על מנת שירצה אבא\" כוונתו ש\u0003אמר לה \"על מנת שלא ימחה אבא\"\u0004 לעולם בקידושין אלו.","ושואלים: מצאנו איפוא שמפרשים את המשנה \u0003רישא בחד טעמא ומציעתא וסיפא בחד טעמא\u0004 \u0005[\u0006את \u0005ראשה בטעם\u0006 באופן \u0005אחד, ו\u0006את \u0005אמצעה וסופה בטעם אחד]!\u0006 \u0003אמר ר' ינאי: אין\u0004 \u0005[כן],\u0006 כך באמת צריך לפרש. \u0003אמר ריש לקיש: שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003ר' ינאי\u0004 סבור כי \u0003דחקינן ומוקמינן מתניתין בתרי טעמא ואליבא דחד תנא\u0004 \u0005[דוחקים ומעמידים אנו\u0006 את \u0005משנתנו בשני טעמים\u0006 שני מקרים שונים, אבל \u0005לפי\u0006 שיטתו של \u0005תנא אחד]\u0006 \u0003ולא מוקמינן בתרי תנאי ובחד טעמא\u0004 \u0005[ואין אנו מעמידים\u0006 אותה \u0005כ\u0006דעת \u0005שני תנאים ובטעם אחד],\u0006 שיש להעדיף דרך זו של פרשנות השומרת על אחדות מחבר המשנה.","\u0003רב יוסף בר אמי אמר: לעולם\u0004 תפרש \u0003חד טעמא\u0004 \u0005[\u0006ש\u0005טעם אחד]\u0006 \u0003הוא,\u0004 כלומר, כל המשנה מדברת באופן אחד של הסבר, \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"על מנת שירצה אבא\"\u0004 — כוונתו \u0003על מנת שלא ימחה אבא מכאן ועד שלשים יום,\u0004 ולכן שתיקתו עד שלושים יום מלמדת שרצונו בקידושין.","אמר אדם \u0003\"קדשתי את בתי\u0004 הקטנה \u0003ואיני יודע למי קידשתיה\", ובא אחד ואמר \"אני קידשתיה\"\u0004 — הרי הוא \u0003נאמן;\u0004 אם באו שנים, ו\u0003זה,\u0004 אחד מהם, \u0003אמר \"אני קידשתיה\" וזה,\u0004 השני, \u0003אמר \"אני קידשתיה\"\u0004 — \u0003שניהם נותנים\u0004 לה \u0003גט\u0004 כדי להתירה. \u0003ואם רצו\u0004 — \u0003אחד\u0004 מהם \u0003נותן גט, ואחד כונס\u0004 אותה כאשתו.","\u0003אמר רב:\u0004 מה שאמרנו שאם בא אחד ואמר \"אני קידשתיה\" נאמן, הכוונה היא — \u0003נאמן ליתן גט, ואין נאמן לכנוס.\u0004 ומסבירים: \u0003נאמן ליתן גט\u0004 ואנו מאמינים שהוא היה זה שקידשה, משום שחזקה היא ש\u0003אין אדם חוטא ולא לו,\u0004 שאין לחשוד שאדם חוטא בדבר שאינו נהנה ממנו. ומכיון שאינו נושא אותה לעצמו — אין אנו מניחים שחטא ושיקר בלי שתהיה לו הנאה מכך. \u0003ואין\u0004 הוא \u0003נאמן לכנוס,\u0004 מדוע? \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003יצרו תוקפו,\u0004 ומשקר ואומר שהוא זה שקידשה.","\u0003רב אסי אמר: אף נאמן לכנוס,\u0004 שאינו מעיז לשקר בפני האב לטעון שקיבל ממנו קידושין. \u0003ומודה רב אסי ב\u0004אשה ה\u0003אומרת \"נתקדשתי ואיני יודעת למי נתקדשתי\" ובא אחד ואמר \"\u0004אני הוא ש\u0003קידשתיה\"\u0004 — \u0003שאין נאמן לכנוס\u0004 אותה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003רצו\u0004 — \u0003אחד\u0004 מהם \u0003נותן\u0004 לה \u0003גט, ואחד כונס\u0004 אותה, והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטתו של \u0003רב\u0004 שהאומר שקידשה נאמן אף לכנוס! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב:\u0004 \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 במשנתנו ש\u0003כיון דאיכא\u0004 \u0005[שיש\u0006 עוד\u0005]\u0006 \u0003אחר בהדיה\u0004 \u0005[איתו]\u0006 אדם נוסף הטוען שקידשה — \u0003אירתותי מירתת\u0004 \u0005[מפחד הוא]\u0006 לשקר.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב אסי:\u0004 אמר אדם \u0003\"קידשתי את בתי ואיני יודע למי קידשתיה\" ובא אחד ואמר\u0004 \u0003\"\u0004אני \u0003קידשתיה\"\u0004 — \u0003אף נאמן לכנוס\u0004 אותה. \u0003כנסה\u0004 אותו אדם, \u0003ובא אחר ואמר \"אני\u0004 הוא ש\u0003קדשתיה\"\u0004 — \u0003לא כל הימנו\u0004 (אין זה בכוחו) \u0003לאוסרה עליו,\u0004 על בעלה.","\u0003האשה שאמרה \"נתקדשתי ואיני יודעת למי נתקדשתי\" ובא אחד ואמר \"אני\u0004 הוא ש\u0003קידשתי\u0004 אותה \u0003\"\u0004— \u0003אין\u0004 הוא \u0003נאמן לכנוס\u0004 אותה. ומדוע — \u0003מפני שהיא מחפה עליו.\u0004 שייתכן שעכשיו היא רוצה בו, ומשקרת ואומרת שהוא האיש שקידשה למרות שמכירה שאינו זה. מה שאין כן באב, אין לחשוש שמחפה עליו, שהרי אין לו כל יצר בדבר.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים: \u0003מהו לסקול על ידו,\u0004 כלומר, האב שאמר \"קידשתי את בתי\", האם הוא נאמן עד כדי שאם זנתה סוקלים אותה? \u0003רב אמר: אין סוקלין. ורב אסי אמר: סוקלין.\u0004","\u0003רב אמר: אין סוקלין,\u0004 וטעמו: \u0003כי הימניה רחמנא\u0004 \u0005[כאשר האמינה התורה\u0006] \u0003לאב\u0004 שקידש את בתו, הרי זה \u0003ל\u0004ענין \u0003איסורא\u0004 \u0005[איסור],\u0006 שאסורה להינשא לאחר, אבל \u0003לקטלא\u0004 \u0005[ל\u0006ענין \u0005מיתה]\u0006 \u0003לא הימניה\u0004 \u0005[האמינתו]\u0006 התורה. \u0003רב אסי אמר:\u0004 אף \u0003סוקלין,\u0004 כי \u0003לכולה מילתיה הימניה רחמנא\u0004 \u0005[לכל דבר האמינה התורה\u0006] \u0003לאב\u0004 ואף לענין דיני נפשות. \u0003אמר רב אסי: ומודינא\u0004 \u0005[ומודה אני]\u0006 \u0003ב\u0004אשה ה\u0003אומרת \"נתקדשתי\"\u0004 וזנתה, \u0003שאין סוקלים\u0004 אותה על סמך הודאתה.","\u0003ואמר רב אסי: הני שמעתתא דידי מרפסן איגרי\u0004 \u0005[ההלכות הללו שלי שוברות גגות],\u0006 כלומר, הן נראות קשות ובלתי מובנות. \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005],\u0006 \u0003ומה במקום ש\u0004אמר האב \"קידשתי את בתי ואיני יודע למי\" ש\u0003אם בא\u0004 אדם מן השוק \u0003לכנוס\u0004 — \u0003כונס\u0004 ומאמינים לו, ובכגון זה \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 ש\u0003סוקלים\u0004 אותה על פי עדות האב אם זנתה, \u0003מקום\u0004 שאמרה אשה \"נתקדשתי ואיני יודעת למי\", שנאמנת לאסור את עצמה על הכל עד \u0003שאם בא\u0004 אדם מן השוק \u0003לכנוס אין כונס, אינו דין שסוקלין? ו\u0004יש לדחות:","\u0003לא היא, לאב הימניה רחמנא\u0004 \u0005[האמינה לו התורה]\u0006 ונתנה לו נאמנות גמורה להעיד שבתו מקודשת, ולכן סומכים על דיבורו גם לעונש סקילה, ואולם \u0003לדידה\u0004 \u0005[לה\u0006 עצמה\u0005]\u0006 \u0003לא הימנה\u0004 \u0005[האמינתה]\u0006 התורה, שלא נתנה לה נאמנות מיוחדת אף שיכולה לעשות את עצמה \"חתיכה דאיסורא\", ולכן יש לדון מקרה זה בדיני הראיות הרגילים.","\u0003ורב חסדא אמר: אחד זה\u0004 (\"קידשתי את בתי\") \u0003ואחד זה\u0004 (\"נתקדשתי\") — \u0003אין סוקלין.\u0004 ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003רב חסדא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב חסדא:\u0004 האומר \u0003\"בני זה בן תשע שנים ויום אחד\",\u0004 או \u0003\"בתי זו בת שלש שנים ויום אחד\"\u0004 ובעל הילד אשה מבוגרת האסורה לו, או הילדה נבעלה לאדם מבוגר האסור לה, הרי זה \u0003נאמן\u0004 על גילם \u0003ל\u0004ענין \u0003קרבן,\u0004 שאם עשו חטא זה בשגגה — צריכים המבוגרים להביא קרבן. \u0003אבל לא למכות ולא לעונשין.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב חסדא:\u0004 האומר \u0003\"בני זה בן שלש עשרה שנה ויום אחד\"\u0004 או \u0003\"בתי זו בת שתים עשרה שנה ויום אחד\"\u0004 —"],["\u0003נאמן\u0004 האב — ביחס לגילם של ילדיו \u0003ל\u0004גבי \u0003נדרים,\u0004 שאם נדרו נדר הריהו חל, \u0003ולחרמים,\u0004 אם הקדישו דבר על ידי שאמרו עליו שיהא \"חרם לה'\" \u0003ולהקדשות ולערכים,\u0004 שנדרו לקודש ערך קבוע של עצמם או של אחרים — בכל אלה נדריהם קיימים, \u0003אבל לא ל\u0004ענין קבלת עונש \u0003מכות\u0004 בבית דין \u0003ול\u0004שאר \u0003עונשין\u0004 (עונשי הגוף) על עבירות שעשו, משום שעדותו אינה מספקת שהרי הוא עד אחד, וקרוב משפחה.","האב האומר \u0003\"קדשתי את בתי\u0004 הקטנה\" או שאומר \u0003\"קדשתיה וגרשתיה\u0004 (קיבלתי את גירושיה) \u0003כשהיא קטנה\", והרי היא\u0004 עדיין \u0003קטנה,\u0004 כשאמר עליה דברים אלה — \u0003נאמן\u0004 לאוסרה משום אשת איש, או כגרושה לכהן. אבל אם אמר \u0003\"קדשתיה וגרשתיה כשהיא קטנה\" והרי היא\u0004 עתה כשאמר את דבריו אלה \u0003גדולה\u0004 — \u0003אינו נאמן.\u0004 וכן אם הוא אומר \u0003\"נשבית ופדיתיה\", בין שהיא קטנה בין שהיא גדולה\u0004 — \u0003אינו נאמן\u0004 לפסול אותה מלהינשא לכהן.","ושואלים: \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[מה שונה תחילת\u0006 המשנה \u0005ומה שונה סופה],\u0006 שבזמן שהבת קטנה אביה נאמן להעיד עליה, וכשהיא גדולה, או להעיד שהיתה שבויה, אינו נאמן? ועונים: \u0003רישא בידיה\u0004 \u0005[בתחילת\u0006 המשנה מדובר בדבר ש\u0005בידו],\u0006 שהרי יכול הוא גם עתה לקדשה ומשום כך נאמן לומר שקידש אותה קודם לכן, ואילו \u0003סיפא לאו בידיה\u0004 \u0005[בסוף\u0006 המשנה מדובר בדבר \u0005שאינו בידו],\u0006 שאינו יכול לקדש את בתו הגדולה. וכיוצא בזה אינו רשאי למוסרה לגוי ולפוסלה בין שהיא קטנה ובין שהיא גדולה — ולפיכך אינו נאמן לומר שנשבית.","ושואלים: \u0003ולא,\u0004 האם אין ביד האב לפוסלה? \u0003והרי בידו להשיאה\u0004 את בתו הקטנה \u0003לחלל\u0004 הנולד לכהן שנשא אשה האסורה עליו, \u0003דקא פסלה\u0004 \u0005[שפוסלה]\u0006 בכך \u0003מכהונה\u0004 ואם כן יהא נאמן גם להעיד שנשבתה!","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 שיש לומר שמשנתנו \u0003כ\u0004שיטת \u0003ר' דוסתאי בן יהודה\u0004 ש\u0003אמר: בנות ישראל\u0004 הן \u0003מקוה טהרה לחללין.\u0004 כלומר, שבנות ישראל שנישאו לחלל, מטהרות (מכשירות) את זרעם, ואם נולדה להם בת היא כשירה להינשא לכהן, וגם האשה אינה נפסלת על ידי ביאת החלל, ואם מת — מותרת להינשא לכהן כשר, ואם כן, אין בידי האב לפסול בתו לכהונה.","ושואלים: \u0003והרי בידו להשיאה לממזר\u0004 ותיפסל בכך לכהונה! ומשיבים: תנא זה סבור \u0003כ\u0004שיטת \u0003ר' עקיבא\u0004 ש\u0003אמר: אין קדושין תופסין\u0004 כלל \u0003בחייבי לאוין\u0004 ואף לא לממזר.","ומקשים: \u0003הרי בידו להשיאה\u0004 כשהיא \u0003אלמנה לכהן גדול, וכ\u0004שיטת \u0003ר' סימאי, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' סימאי אומר: מן הכל עושה ר' עקיבא ממזר,\u0004 כלומר, צאצאים מכל זיווג אסור מחשיב ר' עקיבא כממזרים, \u0003חוץ מאלמנה לכהן גדול, שהרי אמרה תורה\u0004 בכהן גדול: \"אלמנה... \u0003לא יקח... ולא יחלל\u0004 זרעו\" (ויקרא כא, יד–טו), ומכאן למדים: \u0003חלולים עושה\u0004 בזיווג כזה שצאצאיו נחשבים לחללים, \u0003ואין עושה ממזרים,\u0004 וכיון שאינו עושה ממזרים מודה ר' עקיבא שאף הקידושין תופסים בהם.","ומשיבים: התנא שלנו סבור \u0003כ\u0004שיטת \u0003ר' ישבב,\u0004 ש\u0003אמר: בואו ונצווח על עקיבא בן יוסף שהיה אומר: כל שאין לו ביאה בישראל הולד ממזר,\u0004 משמע מדבריו שלדעת ר' עקיבא אין ביאה אסורה שאין בה ממזרות, ולפיכך אין קידושין תופסים בכל איסור, ואין ביד האב לפסול את בתו.","ומקשים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003ר' ישבב אי לטעמיה דנפשיה\u0004 \u0005[אם\u0006 אמר את זה \u0005מטעם עצמו]\u0006 קביעה כללית לשיטת ר' עקיבא, שכל שאין לו ביאה בישראל הולד ממזר — \u0003שפיר\u0004 \u0005[יפה,\u0006 טוב\u0005].\u0006 \u0003אלא אי לאפוקי מטעמא\u0004 \u0005[אם להוציא מהטעם,\u0006 משיטתו\u0005]\u0006 ל\u0003ר' סימאי קאתי\u0004 \u0005[הוא בא],\u0006 שכוונתו רק לחלוק על דברי ר' סימאי בדין של אלמנה לכהן גדול, שר' ישבב סבור שלדעת ר' עקיבא כיון שאסורה בלא תעשה, אין קידושין תופסים כשאר חייבי לאוין, אבל באיסורי עשה הקידושין תופסים, \u0003הרי בידו\u0004 של האב \u0003להשיאה לחייבי עשה\u0004 שאינם בכלל זה!","\u0003אמר רב אשי: ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 שאפשר לקיים את ההסבר הראשון שב\u0003רישא\u0004 \u0005[בתחילת\u0006 המשנה\u0005]\u0006 \u0003משום\u0004 ש\u0003בידו הוא? נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003בידו לקדשה,\u0004 וכי \u0003בידו לגרשה?! ועוד: אילו אמר האי דלא ניחא בגוה מי מצי מקדש ניהליה בעל כרחיה\u0004 \u0005[אם אומר זה,\u0006 הבעל, \u0005שלא נוחה דעתו בה, האם יכול\u0006 הוא האב \u0005לקדש אותה לו בעל כרחו]?\u0006 הרי שאין האב יכול לקדש את בתו למי שירצה!","\u0003אלא אמר רב אשי: רישא\u0004 \u0005[בתחילת\u0006 המשנה\u0005]\u0006 הטעם הוא כי \u0003רחמנא הימניה\u0004 \u0005[התורה האמינה לו],\u0006 \u0003כ\u0004דברי \u0003רב הונא,\u0004 ש\u0003אמר רב הונא אמר רב: מנין לאב שנאמן לאסור את בתו מן התורה\u0004 — \u0003שנאמר \"את בתי נתתי לאיש הזה\"\u0004 (דברים כב, טז), כאשר אמר \u0003\"לאיש\"\u0004 — הרי \u0003אסרה\u0004 בכך לכל אדם, שלא פירש למי קידשה, וכשאמר \u0003\"הזה\"\u0004 — \u0003התירה\u0004 לזה שקידשה.","ויש איפוא להסביר כך: \u0003בנישואין הימניה רחמנא\u0004 \u0005[האמינה לו התורה]\u0006 \u0003לאב, בשבוייה לא הימניה\u0004 \u0005[האמינה לו],\u0006 כלומר, לא נתנה לו התורה מהימנות מיוחדת, ולכן אין עדותו מועילה שהרי הוא עד אחד.","\u0003מי שאמר בשעת מיתתו \"יש לי בנים\"\u0004 ולכן אין אשתו זקוקה ליבם לאחר מותו — הרי זה \u0003נאמן.\u0004 אבל אם אמר בשעת מיתתו \u0003\"יש לי אחים\"\u0004 ואסורה להינשא לשום אדם עד שיחלוץ לה אחד מהם — \u0003אינו נאמן.\u0004","\u0003אלמא\u0004 \u0005[מכאן\u0006 ממשנתנו\u0005]\u0006 ניתן להסיק ש\u0003נאמן להתיר ואין\u0004 הוא \u0003נאמן לאסור. נימא מתניתין\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' נתן.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בשעת קידושין אמר\u0004 ש\u0003יש לו בנים\u0004 ואילו \u0003בשעת מיתה אמר\u0004 ש\u0003אין לו בנים, בשעת קידושין אמר\u0004 ש\u0003אין לו אחים\u0004 ואילו \u0003בשעת מיתה אמר\u0004 ש\u0003יש לו אחים\u0004 — בכל אלה \u0003נאמן להתיר,\u0004 כלומר, להוציאה מחובת הייבום, וכפי דבריו שאמר בזמן הקידושין, \u0003ואין\u0004 הוא \u0003נאמן לאסור\u0004 בדבריו האחרונים, אלו \u0003דברי רבי. ר' נתן אומר: אף נאמן לאסור.\u0004","\u0003אמר רבא: שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003כיון\u0004 ש\u0003בשעת מיתה קא הדר ביה\u0004 \u0005[חוזר בו]\u0006 \u0003אימא קושטא קאמר\u0004 \u0005[אמור\u0006 ש\u0005אמת אומר]\u0006 שמחמת מיתה הוא מתחרט ומודה על האמת, אבל בדרך כלל אינו נאמן לאסור. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ולאו\u0004 \u0005[ו\u0006כי \u0005לא]\u0006 \u0003כל\u0004 ש\u0003כן הוא? השתא, ומה התם דקא מרע ליה לדבוריה\u0004 \u0005[עכשיו,\u0006 הרי, \u0005ומה שם ש\u0006הוא \u0005מרע את דיבורו]\u0006 הקודם, שהרי מתחילה אמר ההיפך, ועכשיו הוא משנה את דבריו — בכל זאת \u0003אמרת קושטא קאמר\u0004 \u0005[אומר אתה\u0006 ש\u0005אמת הוא אומר],\u0006 \u0003מתניתין דלא קא מרע ליה לדבוריה\u0004 \u0005[\u0006ב\u0005משנתנו שאינו מרע את דיבורו]\u0006 הקודם, שלא אמר בשעת הקידושין אם היו או לא היו לו בנים או אחים, \u0003לא כל שכן\u0004 שיהיה נאמן?","\u0003אלא אמר אביי: מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת במקרה ש\u0003לא מוחזק לן\u0004 \u0005[לנו]\u0006 \u0003באחי\u0004 \u0005[באחים\u0006 שיש לו\u0005]\u0006 \u0003ולא מוחזק לן\u0004 \u0005[לנו]\u0006 \u0003בבני\u0004 \u0005[בבנים\u0006 שיש לו\u0005],\u0006 \u0003דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003כיון\u0004 ש\u0003לא מוחזק לן\u0004 \u0005[לנו]\u0006 לא \u0003בבני ולא באחי\u0004 \u0005[באחים]\u0006 אם \u0003אמר \"יש לי בנים\"\u0004 — \u0003נאמן,\u0004 ואם אמר \u0003\"יש לי אחים\"\u0004 — \u0003אינו נאמן.\u0004 ומדוע? \u0003לאו כל כמיניה דאסר לה אכולי עלמא\u0004 \u0005[אין זה בכוחו לאסור אותה על כל העולם]\u0006 רק מחמת דיבורו שהיא נגד החזקה שאין לו אחים. ואילו ה\u0003ברייתא\u0004 מדברת באופן"],["\u0003מוחזק לן\u0004 \u0005[לנו]\u0006 \u0003באחי\u0004 \u0005[ב\u0006זה שיש לו \u0005אחים]\u0006 \u0003ולא מוחזק לן\u0004 \u0005[לנו]\u0006 \u0003בבני\u0004 \u0005[ב\u0006זה שיש לו \u0005בנים],\u0006 אף על פי שאין עדות גמורה בדבר. \u0003דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 בענין זה את הנימוק: \u0003\"מה לי לשקר\",\u0004 מדוע ישקר אדם ללא מטרה. שהרי \u0003מאי קאמר\u0004 \u0005[\u0006לשם \u0005מה\u0006 הוא \u0005אומר]\u0006 שיש לו בנים או שאין לו אחים אם לא כדי \u0003למיפטרה\u0004 \u0005[לפטור אותה]\u0006 \u0003מיבם,\u0004 הלא \u0003מצי אמר\u0004 \u0005[יכול\u0006 הוא \u0005לומר]\u0006 לה באותה שעה: \u0003פטרנא לך בגיטא\u0004 \u0005[אני פוטר אותך בגט],\u0006 ולכן כיון שאמר שיש לו בנים — ודאי אמת הוא אומר.","\u0003רבי סבר\u0004 בענין זה כי כוח הנימוק של \u0003\"מה לי לשקר\" כי\u0004 \u0005[כמו]\u0006 עדות \u0003עדים דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 \u0003ואתו\u0004 \u0005[ובאו]\u0006 \u0003עדים עקרי\u0004 \u0005[\u0006ו\u0005עוקרים]\u0006 את ה\u0003חזקה\u0004 ואין בכוחו שוב לאסור אותה בשעת מיתה. \u0003ור' נתן סבר: \"מה לי לשקר\" כי\u0004 \u0005[כמו]\u0006 \u0003חזקה דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006, והרי \u0003לא אתי\u0004 \u0005[באה]\u0006 \u0003חזקה ועקרה\u0004 \u0005[ועוקרת]\u0006 \u0003חזקה לגמרי.\u0004 ולכן הוא נאמן אף לאסור, שאם אמר בשעת מיתה שלא היו לו בנים, חוששים לחזקתו הראשונה.","\u0003המקדש את בתו סתם\u0004 ולא אמר איזו מהן — \u0003אין הבוגרות בכלל. מי שיש לו שתי כיתי\u0004 (קבוצות) של \u0003בנות משתי נשים\u0004 שהיו לו זו אחר זו, \u0003ואמר \"קדשתי את בתי הגדולה\u0004 לאיש, \u0003ואיני יודע אם\u0004 היה מדובר על הבת ה\u0003גדולה שב\u0004קבוצת הבנות ה\u0003גדולות, או גדולה שב\u0004קבוצת הבנות ה\u0003קטנות, או קטנה שב\u0004קבוצת הבנות ה\u0003גדולות שהיא\u0004 עדיין \u0003גדולה מן הגדולות שב\u0004קבוצת ה\u0003קטנות\"\u0004 — כל הבנות \u0003כולן אסורות, חוץ מן הקטנה שבקטנות,\u0004 אלו \u0003דברי ר' מאיר. ר' יוסי אומר:\u0004 למרות הספק \u0003כולן מותרות, חוץ מן הגדולה שבגדולות,\u0004 שסתם \"גדולה\" כוונתו לגדולה שבכולן.","וכן אם אמר \u0003\"קדשתי את בתי הקטנה, ואיני יודע אם\u0004 היתה זו \u0003קטנה שבקטנות, או קטנה שבגדולות, או גדולה שבקטנות שהיא קטנה מן הקטנות שבגדולות\"\u0004 — \u0003כולן אסורות, חוץ מן הגדולה שבגדולות,\u0004 אלו \u0003דברי ר' מאיר. ר' יוסי אומר: כולן מותרות, חוץ מן הקטנה שבקטנות.\u0004","ושואלים: שנינו במשנה שהמקדש את בתו סתם אין הבוגרות בכלל — \u0003הא\u0004 \u0005[הרי]\u0006 שה\u0003קטנות בכלל\u0004 אפילו אם היו כמה בנות,","\u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]:\u0006 ש\u0003קידושין שאין מסורים לביאה\u0004 שבפועל אינו יכול לשאת אף אחת מהן, שמא אינה זו שקידש ואסורה עליו משום אחות אשתו, בכל זאת \u0003הוו\u0004 \u0005[הריהם]\u0006 \u0003קידושין,\u0004 וכולן צריכות גט כדי להתירן להינשא, והרי זה בניגוד לדעת רבא האומר שקידושין שאין מסורים לביאה אינם תופסים כלל! ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — במקרה \u0003כשאין שם אלא\u0004 שתי בנות בלבד, \u0003גדולה וקטנה.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"בוגרות\" קתני\u0004 \u0005[שנה\u0006 במשנה\u0005]\u0006 בלשון רבים! ודוחים: \u0003מאי\u0004 \u0005[מה]\u0006 הכוונה בלשון הרבים של \u0003בוגרות\u0004 — לא הבוגרות בין בנותיו, אלא \u0003בוגרות דעלמא\u0004 \u0005[בכלל],\u0006 כלומר, שבכל מקרה שמקדש את בתו — בנות בוגרות אינן בכלל זה.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003בוגרות מאי עבידתייהו\u0004 \u0005[מה מעשיהן],\u0006 כלומר, כיצד אפשר להניח שמקדש את בתו הבוגרת? הרי אין רשות לאב אלא לקדש את בתו קטנה! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — באופן מיוחד, \u0003דשויתיה\u0004 \u0005[שמינתה\u0006 הבת הגדולה \u0005אותו]\u0006 \u0003שליח\u0004 לקבל עבורה קידושין, וקידש את בתו סתם, ובמקרה זה \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 הוא \u0003מקבל קידושי\u0004 \u0005[קידושין]\u0006 \u0003אדעתא דידה קא\u0004 \u0005[על דעתה שלה]\u0006 לקדש אותה את הבוגרת הוא \u0003מקבל,\u0004 שהרי הוא שלוחה, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 במשנה ש\u0003לא שביק איניש מידי דאית ליה\u0004 \u0005[אין אדם מניח דבר שיש לו]\u0006 \u0003הנאה מיניה\u0004 \u0005[ממנו]\u0006 כקידושי הבת הקטנה, שהוא נוטל לעצמו את כסף קידושיה, \u0003ועביד מידי דלית ליה\u0004 \u0005[ועושה דבר שאין לו]\u0006 \u0003הנאה מיניה\u0004 \u0005[ממנו],\u0006 שהרי כסף קידושי הבת הגדולה הם לעצמה.","ודוחים: \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 אפילו במקרה \u0003דאמרה ליה\u0004 \u0005[שאומרת לו]\u0006 הבת \u0003\"\u0004בשכר שליחותך כסף \u0003קדושיי\u0004 יהיה \u0003לך\"?\u0004 ואם כן, אף בקידושיה יש לו הנאה. ודוחים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא שביק איניש\u0004 \u0005[אין אדם מניח]\u0006 \u0003מצוה דרמיא עליה\u0004 \u0005[המוטלת עליו]\u0006 לקדש את בתו הקטנה \u0003ועביד\u0004 \u0005[ועושה]\u0006 \u0003מצוה דלא רמיא עליה\u0004 \u0005[שאינה מוטלת עליו]\u0006 במישרין בבתו הגדולה, שכיון שבוגרת היא — מוטלת המצוה עליה.","שנינו במשנה שבענין \u0003מי שיש לו שתי כיתי בנות\u0004 וקידש את הגדולה, אבל לא היה ברור לו למי מן הבנות התכוון נחלקו ר' מאיר ור' יוסי באיזו מהן מקודשת, וכן שנינו מחלוקת זו במקדש בתו הקטנה. ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 הדבר להיאמר בשני המקרים; \u0003דאי אשמעינן קמייתא\u0004 \u0005[שאילו היה משמיע לנו\u0006 רק את המחלוקת ביניהם בהלכה \u0005הראשונה]\u0006 במקדש בתו הגדולה, היינו אומרים: \u0003בהך קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003ר' מאיר\u0004 שכולן אסורות חוץ מן הקטנה שבקטנות, \u0003דכיון דאיכא זוטרא מינה\u0004 \u0005[שיש קטנה ממנה],\u0006 \u0003להך\u0004 \u0005[לזו]\u0006 — \u0003\"גדולה\" קרי\u0004 \u0005[\u0006הוא \u0005קורא]\u0006 \u0003לה\u0004 כל שיש קטנה ממנה,","\u0003אבל בהא\u0004 \u0005[בזו],\u0006 במקדש בתו הקטנה \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לר' יוסי\u0004 ש\u0003\"קטנה\"\u0004 — \u0003להך\u0004 \u0005[לזו]\u0006 היא ה\u0003קטנה דכולהו קרי לה\u0004 \u0005[שבכולן\u0006 הוא \u0005קורא],\u0006 שנאה לו לאדם לאמר על בתו שהיא \"גדולה\". ולהיפך, \u0003ואי איתמר בהא\u0004 \u0005[ואילו היה נאמר\u0006 רק \u0005בזו],\u0006 בקטנה, היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו\u0006 בלבד \u0005אומר]\u0006 \u0003ר' יוסי,\u0004 מאותו טעם שהזכרנו, \u0003אבל בהך\u0004 \u0005[בזו],\u0006 בגדולה, \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לר' מאיר,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר בשני המקרים.","לגופן של השיטות שואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 כמסקנה מדברים אלה ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]\u0006 כי \u0003מחית איניש נפשיה לספיקא\u0004 \u0005[אדם מוריד,\u0006 מכניס, \u0005את עצמו לספק],\u0006 כלומר, אדם מקבל על עצמו אפילו דבר שאין בו הגדרה ברורה, ויש בו ספק. \u0003ור' יוסי סבר\u0004 \u0005[סבור]\u0006 ש\u0003לא מחית איניש לספיקא\u0004 \u0005[מוריד,\u0006 מכניס \u0005אדם את עצמו לספק]\u0006 ומתכוון רק לדברים ברורים ומוגדרים. \u0003והאיפכא שמעינן להו\u0004 \u0005[והרי ההיפך\u0006 מכך \u0005אנו שומעים אותם]\u0006 שאמרו, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנודר\u0004 בדבר וקובע לו זמן, שיחול הנדר \u0003\"עד הפסח\",\u0004 אמרו ש\u0003אסור\u0004 בדבר שנדר בו \u0003עד שיגיע\u0004 הפסח. אם אמר בנדרו שהוא נודר \u0003\"עד שיהא פסח\"\u0004 — \u0003אסור עד שיצא\u0004 הפסח.","ואם אמר \u0003\"עד פני פסח\"\u0004 — \u0003ר' מאיר אומר: אסור עד שיגיע\u0004 פסח, \u0003ר' יוסי אומר: עד שיצא\u0004 הפסח.","משמע שלדעת ר' מאיר אין אדם מכניס את עצמו לספק, שאף שהזכיר פסח לא היתה כוונתו בתוך ימי הפסח, אלא עד לזמן שמגיע פסח, ואילו לדעת ר' יוסי אדם יכול להכניס את עצמו לספק בכל אחד ואחד מימי הפסח, והוא היפך הדברים שהסברנו במשנתנו! \u0003אמר ר' חנינא בר אבדימי אמר רב: מוחלפת השיטה,\u0004 שצריך להחליף את הדעות במשנה זו, ולפי זה יתיישבו הדברים. \u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003זה הכלל: כל\u0004 דבר אם נדר למועד \u0003שזמנו קבוע, ואמר\u0004 בלשון \u0003\"עד פני\"\u0004 — \u0003ר' מאיר אומר:\u0004 הכוונה \u0003עד שיצא, ר' יוסי אומר:\u0004 הכוונה היא \u0003עד שיגיע,\u0004 והוא כפי שהצענו בהיפוך השיטות.","\u0003אמר אביי: מחלוקת\u0004 זו של ר' מאיר ור' יוסי היא \u0003בשתי כיתי בנות,\u0004 שלדעת ר' מאיר שתי הכיתות חוץ מהקטנה שבקטנות נקראות \"גדולה\" מספק, \u0003אבל בכת אחת,\u0004 כלומר, שהיו לו רק בנות מאשה אחת — \u0003דברי הכל\u0004 כשאמר \u0003גדולה,\u0004 כוונתו לגדולה שבהן \u0003ממש,\u0004 אמר \u0003קטנה\u0004 כוונתו לקטנה שבהן \u0003ממש,\u0004 ולבת \u0003אמצעית\u0004 אין קוראים לה לא גדולה ולא קטנה אלא \u0003בשמה קרי לה\u0004 \u0005[קורא\u0006 הוא \u0005אותה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר מתנה לאביי: אלא מעתה,\u0004 לפי שיטה זו,"],["\u0003אמצעית שבכת שניה,\u0004 כלומר, שבין הבנות הקטנות \u0003תשתרי\u0004 \u0005[תהיה מותרת]\u0006 אם אמר \"קידשתי את בתי הגדולה\", שהרי אמרנו שהוא קורא לה בשמה ואין היא בכלל \"גדולה\"! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בשאין שם אלא\u0004 שתי בנות: \u0003גדולה וקטנה\u0004 בלבד, ואין אמצעית.","ומעירים: \u0003והכי נמי מסתברא\u0004 \u0005[ו\u0006אכן \u0005כך גם כן מסתבר]\u0006 לומר, ש\u0003אם איתא דאיכא\u0004 \u0005[אמנם יש]\u0006 בת אמצעית, \u0003ליתנייה\u0004 \u0005[שישנה אותה]\u0006 אם כן במחלוקת במשנה, שהרי גם לגביה יש ספק. ודוחים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שכך אתה רוצה לדייק, אם כן \u0003אמצעית שבכת ראשונה,\u0004 ש\u0003ודאי\u0004 היא \u0003ספיקא\u0004 \u0005[ספק],\u0006 \u0003ואסירא ליה\u0004 \u0005[ואסורה\u0006 היא \u0005לו],\u0006 \u0003מי קתני לה\u0004 \u0005[האם שונה אותה]?\u0006","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם תנא\u0004 \u0005[שם שנה]\u0006 את ה\u0003קטנה דידה לאיסורא\u0004 \u0005[ממנה לאיסור],\u0006 שהרי אמר שהספק הוא אפילו בקטנה שבגדולות, \u0003והוא הדין להך דקשישא מינה\u0004 \u0005[לזו\u0006 האמצעית \u0005שמבוגרת ממנה]\u0006 שהיא בודאי בכלל ספק זה, אבל","\u0003הכא\u0004 \u0005[כאן]\u0006 בכת הבנות הקטנות, \u0003אם איתא דאיכא\u0004 \u0005[יש\u0006 מקום לומר \u0005שיש]\u0006 ספק לגבי האמצעית — \u0003ניתנייה\u0004 \u0005[שישנה אותה]\u0006 ויפרש מה דינה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרבא: הא\u0004 \u0005[הרי]\u0006 מצאנו שדנו בענין \u0003פסח, דכי\u0004 \u0005[שכמו]\u0006 \u0003כת אחת דמי\u0004 \u0005[נחשב],\u0006 \u0003ופליגי\u0004 \u0005[ו\u0006הם \u0005חלוקים],\u0006 וקשה מכאן על דברי אביי שבכת אחת אין מחלוקת!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003בלישנא דעלמא קמיפלגי\u0004 \u0005[בלשון העולם\u0006 הם \u0005חלוקים],\u0006 כלומר, מחלוקתם שם אינה בבעיה עקרונית אם מכניס אדם את עצמו לספק, אלא מה משמעות לשון בני אדם. \u0003מר סבר\u0004 \u0005[חכם זה סבור]\u0006 שהביטוי \u0003\"עד פני הפסח\"\u0004 כוונתו \u0003עד קמי פיסחא\u0004 \u0005[לפני הפסח]\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה סבור]\u0006 שמובנו: \u0003עד דמיפני פיסחא\u0004 \u0005[שפונה הפסח\u0006 ויוצא\u0005].\u0006","\u0003האומר לאשה \"קדשתיך\" והיא אומרת \"לא קדשתני\"\u0004 — \u0003הוא אסור בקרובותיה,\u0004 שהרי לדבריו קידש אותה, ונעשו בכך קרובותיה עבורו כ\"חתיכה של איסור\", \u0003והיא מותרת בקרוביו,\u0004 שהרי היא טוענת שלא נתקדשה. \u0003היא אומרת \"קדשתני\" והוא אומר \"לא קדשתיך\"\u0004 — \u0003הוא מותר בקרובותיה והיא אסורה בקרוביו,\u0004 מאותו טעם.","הוא אומר לה \u0003\"קידשתיך\" והיא אומרת \"לא קידשת\u0004 אותי \u0003אלא\u0004 את \u0003בתי\"\u0004 — \u0003הוא אסור בקרובות גדולה\u0004 (האם), שהרי הוא טוען שקידש אותה, \u0003וגדולה מותרת בקרוביו. הוא מותר בקרובות קטנה\u0004 (הבת), שהרי לדבריו לא קידש אותה \u0003וקטנה מותרת בקרוביו,\u0004 שהרי היא לא אמרה שהתקדשה לו ודבריה של האם בלבד אינם מועילים לאוסרה.","וכן אם הוא אומר \u0003\"קדשתי את בתך\" והיא אומרת \"לא קדשת\u0004 את בתי \u0003אלא אותי\"\u0004 — \u0003הוא אסור בקרובות קטנה, וקטנה מותרת בקרוביו, הוא מותר בקרובות גדולה וגדולה אסורה בקרוביו.\u0004","שנינו במשנה: \u0003האומר לאשה קדשתיך וכו'. וצריכא\u0004 \u0005[וצריך]\u0006 לשנות במשנה את כל הפרטים השונים, למרות שלכאורה עניינם אחד. \u0003דאי אשמעינן גביה דידיה\u0004 \u0005[שאם היה משמיע לנו\u0006 רק \u0005לגבי עצמו],\u0006 שטוען שקידש את האשה, היינו אומרים שאינו נאמן לאוסרה \u0003משום דגברא\u0004 \u0005[שאיש]\u0006 \u0003לא איכפת ליה\u0004 \u0005[לו]\u0006 \u0003ומיקרי אמר\u0004 \u0005[ומזדמן ואומר]\u0006 שקידש אשה אף שלא קידש אותה, שהרי הוא יכול לשאת אשה נוספת.","\u0003אבל איהי, אימא\u0004 \u0005[היא, אמור]:\u0006 \u0003אי לאו דקים\u0004 \u0005[אם לא שברור]\u0006 \u0003לה בדיבורה,\u0004 כלומר, במה שהיא אומרת, \u0003לא הות אמרה\u0004 \u0005[היתה אומרת],\u0006 שהרי כשאומרת שקידש אותה אוסרת היא בכך את עצמה לכל העולם, ומן הסתם מדקדקת בדבר, \u0003ו\u0004משום כך \u0003ליתסר איהו\u0004 \u0005[שייאסר\u0006 גם \u0005הוא]\u0006 \u0003בקרובותיה\u0004 משום חזקה זו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא.","על מה ששנינו במשנה שהוא אומר לה \u0003\"קידשתיך\" והיא אומרת\u0004 \"קידשת את בתי\", שהוא אסור בקרובותיה והיא מותרת בקרוביו, שואלים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי?\u0004 הרי לכאורה אנו כבר יודעים את הפתרון העקרוני! ומשיבים: \u0003איצטריך\u0004 \u0005[צריך]\u0006 היה הדבר להיאמר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003מדאורייתא הימניה רחמנא\u0004 \u0005[מ\u0006דין \u0005התורה האמינה התורה]\u0006 \u0003לאב\u0004 שאם הוא אומר שקידש את בתו לאדם מסויים — הרי הוא נאמן בכך, ושמא נאמר \u0003מדרבנן הימנוה לדידה ותיתסר ברתה\u0004 \u0005[מדברי חכמים האמינו\u0006 גם \u0005לה,\u0006 לאם, \u0005ותיאסר בתה]\u0006 \u0003בדיבורה\u0004 (על פי מה שאמרה), על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאינה נאמנת.","ועל מה ששנינו במשנה שהוא אומר \u0003\"קידשתי את בתך\"\u0004 והיא אומרת \"לא קידשת אלא אותי\", שואלים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי,\u0004 הרי אין בה שום חידוש? ומשיבים: \u0003איידי דתנא הא, תנא נמי הא\u0004 \u0005[מתוך ששנה\u0006 את \u0005זו\u0006 (\"קידשתיך\", \"קידשת את בתי\") \u0005שנה גם\u0006 את \u0005זו]\u0006 כדי להשלים את כל המקרים, אף שאין בהם חידוש עקרוני.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים מה עושים בפועל, \u0003רב אמר: כופין\u0004 את האיש שיתן לה גט, \u0003ושמואל אמר: מבקשין\u0004 ממנו שיתן. ושואלים: \u0003אהייא\u0004 \u0005[על איזה]\u0006 מקרה נחלקו? \u0003אילימא ארישא\u0004 \u0005[אם תאמר על ראש\u0006 המשנה\u0005]\u0006 שהוא אומר לה \"קידשתיך\" והיא אומרת \"לא נתקדשתי\" — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003\"כופין\" איכא\u0004 \u0005[יש\u0006 כאן\u0005]\u0006 \u0003ולא \"מבקשין\" איכא\u0004 \u0005[יש\u0006 כאן\u0005],\u0006 שהרי אמרנו שהיא מותרת אפילו בקרוביו, וכל שכן שהיא מותרת באדם אחר, ולשם מה יכפוהו לתת לה גט? \u0003אלא\u0004 המחלוקת היא \u0003אסיפא\u0004 \u0005[על סופה,\u0006 המשך המשנה\u0005],\u0006 שהיא אומרת שקידש אותה והוא מכחיש. שבזה, כדי לאפשר לה להינשא לאדם אחר, כופים אותו או מבקשים ממנו שיתן גט.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שאומרים \u0003\"מבקשין\"\u0004 הרי זה \u0003לחיי\u0004 \u0005[בסדר],\u0006 שכיון שהיא אוסרת את עצמה לכול מבקשים ממנו שיתיר אותה, \u0003אלא \"כופין\" אמאי\u0004 \u0005[מדוע]?\u0006 הרי נאסר בכך בקרובותיה?! \u0003אמר\u0004 \u0005[\u0006יכול הוא \u0005לומר]:\u0006 \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי דאיתסר בקריבה\u0004 \u0005[שאיאסר בקרובותיה],\u0006 שעל ידי נתינת הגט נמצא כמודה שקידשה ונאסר בקרובותיה.","\u0003אלא\u0004 יש להסביר הדבר אחרת: \u0003שמעתתא אהדדי איתמר\u0004 \u0005[השמועות\u0006 הללו, \u0005זו על זו נאמרו],\u0006 ובאופן זה, \u0003אמר שמואל: מבקשין ממנו ליתן גט. אמר רב: אם נתן גט מעצמו\u0004 בלי שיבקשו ממנו, על פי טענתה בלבד — \u0003כופין אותו ליתן\u0004 גם \u0003כתובה.\u0004 משום שאם נתן גט מדעת עצמו — משמע שהוא מודה לה אף שלא אמר זאת במפורש, ולכן יתן גם כתובה.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]:\u0006 \u0003אמר רב אחא בר אדא, אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב אחא בר אדא, אמר רב המנונא, אמר רב: כופין ומבקשין.\u0004 ויש לתהות: והרי \u0003תרתי\u0004 \u0005[שתי]\u0006 אמירות סותרות הן?! אלא יש לתרץ כי \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003מבקשין ממנו ליתן גט, ואם נתן\u0004 גט \u0003מעצמו\u0004 — \u0003כופין אותו ליתן כתובה.\u0004","\u0003אמר רב יהודה: המקדש בעד אחד\u0004 — \u0003אין חוששין ל\u0004תפיסת \u0003קידושיו,\u0004 שאין להם כל תוקף. \u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 התלמידים \u0003מרב יהודה:\u0004 אם היו \u0003שניהם,\u0004 גם האיש וגם האשה \u0003מודים\u0004 שהיו קידושין, \u0003מאי\u0004 \u0005[מה]\u0006 הדין לענין תוקף הקידושין? והיה רב יהודה פעמים אומר \u0003אין\u0004 \u0005[כן]\u0006 \u0003ו\u0004פעמים היה אומר \u0003לא, ורפיא בידיה\u0004 \u0005[והיה\u0006 הדבר \u0005רופף בידו],\u0006 שלא היתה לו תשובה ברורה לענין זה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שדנו אמוראים בשאלה זו, \u0003אמר רב נחמן אמר שמואל: המקדש בעד אחד\u0004 — \u0003אין חוששין לקידושיו\u0004 כלל, \u0003ואפילו שניהם מודים\u0004 שהיו קידושין.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו: \u0003האומר לאשה \"קדשתיך\" והיא אומרת \"לא קדשתני\"\u0004 — \u0003הוא אסור בקרובותיה והיא מותרת בקרוביו.\u0004 ונברר מה היה המקרה בדיוק, \u0003אי דאיכא\u0004 \u0005[אם שיש]\u0006 \u0003עדים\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 היא \u0003מותרת בקרוביו?\u0004 הרי היו שם עדים, וקידושין גמורים הם! \u0003ואי דליכא\u0004 \u0005[ואם שאין]\u0006 \u0003עדים\u0004 כלל — \u0003אמאי\u0004 \u0005[מדוע]\u0006 הוא יהא \u0003אסור בקרובותיה\u0004 אם אין כל עדות על הדבר? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003בעד אחד?\u0004","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון\u0004 ש\u0003אמר לה \"קידשתיך בפני פלוני ופלוני\",\u0004 שהיו שני עדים לקידושין, \u0003והלכו להם\u0004 העדים \u0003למדינת הים,\u0004 ואין לנו דרך לברר מה באמת אירע באותה שעה, ואין לסמוך אלא על דברי שניהם. ולפי דבריו היו שם קידושין גמורים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו: \u0003המגרש את אשתו ו\u0004לאחר מכן \u0003לנה עמו בפונדקי\u0004 (פונדק), \u0003בית שמאי אומרים: אינה צריכה הימנו גט שני,\u0004 שאין אנו מניחים שחזר ובא עליה לשם קידושין, \u0003ובית הלל אומרים: צריכה הימנו גט שני,\u0004 שמא נתייחד עימה לשם קידושין. ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דאיכא\u0004 \u0005[אם שיש]\u0006 \u0003עדים\u0004 שראו אותם — \u0003מאי טעמייהו\u0004 \u0005[מה טעמם]\u0006 של \u0003בית שמאי\u0004 שאינה צריכה גט? \u0003ואי דליכא\u0004 \u0005[ואם שאין]\u0006 \u0003עדים\u0004 — \u0003מאי טעמייהו\u0004 \u0005[מה טעמם]\u0006 של \u0003בית הלל? אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003בעד אחד\u0004 בלבד?","ודחה רב נחמן: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שכך אתה מפרש, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של משנה זו: \u0003ומודים\u0004 גם בית הלל \u0003בנתגרשה מן האירוסין שאין צריכה הימנו גט שני, מפני שאין לבו גס בה\u0004 וכיון שאינו רגיל בה, אין לחשוש שמא בא עליה. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003עד אחד מהימן\u0004 (נאמן) בזה — אם היה שם עד שמעיד עליהם \u0003מה לי מן האירוסין, מה לי מן הנשואין?\u0004","\u0003אלא\u0004 אין מדובר כאן בעד אחד, \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דאיכא\u0004 \u0005[שיש]\u0006 \u0003עדי יחוד\u0004 המעידים שנתייחדו \u0003וליכא\u0004 \u0005[ואין]\u0006 \u0003עדי ביאה,\u0004 והמחלוקת היא במסקנות שאנו מסיקים מן הייחוד. \u0003בית שמאי סברי\u0004 \u0005[סבורים]:\u0006 \u0003לא\u0004"],["\u0003אמרינן\u0004 \u0005[אין אנו אומרים]:\u0006 \u0003הן הן עדי יחוד, הן הן עדי ביאה\u0004 ואף שנתייחדו אין אנו מניחים שבא עליה, ואינה אף ספק מקודשת. \u0003ובית הלל סברי\u0004 \u0005[סבורים]\u0006 \u0003אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003הן הן עדי יחוד, הן הן עדי ביאה\u0004 ויש לחשוש שמא בא עליה לשם נישואין. \u0003ומודים\u0004 בית הלל \u0003ודאי בנתגרשה מן האירוסין, דלא אמרינן\u0004 \u0005[שאין אנו אומרים]\u0006 \u0003הן הן עדי יחוד הן הן עדי ביאה, מפני שאין לבו גס בה.\u0004","\u0003אמר רב יצחק בר שמואל בר מרתא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: המקדש\u0004 אשה \u0003בעד אחד\u0004 — \u0003אין חוששין\u0004 כלל \u0003לקידושיו, ואפילו שניהם מודים\u0004 שנתקדשו. \u0003אמר רבה בר רב הונא: המקדש בעד אחד, בי דינא רבה אמרי\u0004 \u0005[בית הדין הגדול אומרים]:\u0006 \u0003אין חוששין לקידושיו.\u0004 ושואלים: \u0003מאן בי דינא רבה\u0004 \u0005[מיהו בית הדין הגדול]\u0006 שמזכיר? ומשיבים: זהו כינוי שניתן לאמורא \u0003רב. ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת: \u0003אמר רבה בר רב הונא אמר רב: המקדש בעד אחד, בי דינא רבה אמרי\u0004 \u0005[בית הדין הגדול אומרים]:\u0006 \u0003אין חוששין לקידושיו. מאן בי דינא רבה\u0004 \u0005[מיהו בית דין הגדול]\u0006 זה שנזכר — \u0003רבי.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אחדבוי בר אמי\u0004 מברייתא זו: \u0003שנים\u0004 (שני גברים) \u0003שבאו ממדינת הים ואשה עמהם, וחבילה עמהם, זה,\u0004 אחד מהם, \u0003אומר: זו אשתי, וזה,\u0004 האיש השני הוא \u0003עבדי, וזו חבילתי, וזה,\u0004 האיש השני, \u0003אומר: זו אשתי, וזה\u0004 האיש האחר הוא \u0003עבדי, וזו חבילתי. ואשה אומרת: אלו שני עבדי, וחבילה שלי\u0004 — הרי במקרה זה \u0003צריכה\u0004 האשה \u0003שני גיטין,\u0004 שהרי יש חשש שמא היא נשואה לכל אחד מהם לפי טענתם, \u0003וגובה כתובתה מן החבילה,\u0004 שהרי אף לדבריהם לפחות דמי כתובה יש לה מן החבילה.","ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה\u0006 הדבר\u0005]?\u0006 \u0003אי דאית ליה סהדי להאי ואית ליה סהדי להאי\u0004 \u0005[אם\u0006 מדובר \u0005שיש לו עדים לזה ויש לו עדים לזה],\u0006 לכל אחד מן הגברים, \u0003מי מצי אמרה\u0004 \u0005[האם יכולה\u0006 האשה \u0005לומר]:\u0006 \u0003אלו שני עבדי וחבילה שלי?\u0004 הרי יש שני עדים שאחד משני אנשים אלה הוא בעלה! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003ב\u0004שיש \u0003עד אחד\u0004 לכל אחד מן הגברים? ומכאן ראיה שיש קידושין על ידי עד אחד, שהרי צריכה גט משניהם!","ודוחים: \u0003ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 שכך אפשר להבין? והרי במקום שיש רק \u0003עד אחד\u0004 המעיד על דבר \u0003ב\u0004מקום שיש \u0003הכחשה\u0004 נגדו, כגון כאן, שעד אחר מכחיש אותו שנתקדשה לאחר, \u0003מי מהימן\u0004 \u0005[האם נאמן]\u0006 העד האחד כלל? \u0003אלא\u0004 כך צריך להבין: \u0003למישרי לעלמא\u0004 — \u0005[להתיר\u0006 אותה \u0005לעולם,\u0006 לכל אדם\u0005],\u0006 — \u0003דכולי עלמא לא פליגי דשרי\u0004 \u0005[\u0006\u0005לכל הדעות אין חולקים ש\u0006היא \u0005מותרת]\u0006 אפילו בלי שיתנו לה גט,","\u0003והכא הכי קאמר\u0004 \u0005[וכאן כך אמר]:\u0006 מה טעם \u0003צריכה שני גיטין\u0004 — \u0003כדי לגבות\u0004 את \u0003כתובתה מן החבילה. ו\u0004שיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר:\u0004 אף \u0003מטלטלי משתעבדי\u0004 \u0005[מטלטלים משתעבדים]\u0006 \u0003לכתובה\u0004 ולא רק נכסי דלא ניידי. ולכן כדי לגבות כתובה מן החבילה שיש עליה שלושה טוענים — צריכה היא לקבל מהם גיטין המחייבים אותם לתת לה כתובה.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה,\u0006 מה אמרו \u0005עליה],\u0006 על בעיה זו של המקדש בעד אחד? \u0003רב כהנא אמר: אין חוששין לקידושיו. רב פפא אמר: חוששין לקדושיו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: מאי דעתיך\u0004 \u0005[דעתך]\u0006 שאתה אומר שאין חוששים לקידושיו — \u0003דילפת\u0004 \u0005[שאתה לומד]\u0006 בגזירה שווה \u0003\"דבר\" \"דבר\" מממון,\u0004 ונאמר שם \"על פי שני עדים או על פי שלושה עדים יקום דבר\" (דברים יט, טו),","\u0003אי מה להלן\u0004 \u0005[אם\u0006 כן נאמר \u0005מה שם]\u0006 בממון הרי \u0003הודאת בעל דין כמאה עדים דמי\u0004 \u0005[נחשבת]\u0006 ויש לה כוח לחייב את המודה, \u0003אף כאן הודאת בעל די\u0004 \u0003ן כמאה עדים דמי\u0004 \u0005[נחשבת],\u0006 ובמקרה ששניהם מודים שהם נשואים תהא הודאתם מחייבת אותם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: יש להבחין בין הדברים; \u0003התם לא קא חייב לאחריני\u0004 \u0005[שם\u0006 שמודה שחייב ממון \u0005אינו מחייב אחרים]\u0006 בהודאה זו, אבל \u0003הכא קא חייב לאחריני\u0004 \u0005[כאן הוא מחייב אחרים],\u0006 שהרי על ידי הודאה זו הם אוסרים זה על זה את קרוביהם, ונמצא שגם אחרים מתחייבים על ידי כך.","מסופר: \u0003מר זוטרא ורב אדא סבא\u0004 שהיו שניהם \u0003בני רב מרי בר\u0004 (בן) \u0003איסור, פליג ניכסייהו בהדי הדדי\u0004 \u0005[חילקו נכסיהם זה עם זה].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב אשי, אמרו\u0004 (שאלו) \u0003ליה\u0004 \u0005[לו]\u0006 לרב אשי: \u0003\"על פי שני עדים...\u0004 יקום דבר\u0003\"\u0004 (דברים יט, טו) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 ומדוע דרושים שני עדים — \u0003דאי בעי למיהדר לא מצי הדרי בהו\u0004 \u0005[שאם רוצים לחזור\u0006 בהם ולומר \"לא היו דברים מעולם\", \u0005אינם יכולים לחזור בהם],\u0006 \u0003ואנן לא הדרי\u0004 \u0005[ו\u0006אילו \u0005אנו איננו חוזרים],\u0006 ולכן איננו זקוקים לעדים לקיים את החלוקה.","\u0003או דלמא לא מקיימא מלתא\u0004 \u0005[שמא אין דבר מתקיים]\u0006 \u0003אלא בסהדי\u0004 \u0005[בעדים],\u0006 שהעדים באים לקיים את החלוקה מבחינה משפטית ולא לאימות בלבד? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא איברו סהדי\u0004 \u0005[נבראו עדים]\u0006 \u0003אלא לשקרי\u0004 \u0005[\u0006עבור \u0005השקרנים],\u0006 ובמקום שאין הכחשה, העיסקה קיימת ממילא.","ועוד באותו ענין, \u0003אמר אביי: אמר לו עד אחד\u0004 לאדם \u0003\"אכלת חלב\", והלה\u0004 שהעידו בו \u0003שותק\u0004 ואיננו מכחיש — הרי זה, העד, \u0003נאמן\u0004 וחייב קרבן חטאת על שגגתו זו. \u0003ותנא תונא\u0004 \u0005[ושנה\u0006 כמו כן \u0005התנא שלנו]:\u0006 \u0003אמר לו עד אחד \"אכלת חלב\" והלה אומר \"לא אכלתי\"\u0004 — \u0003פטור\u0004 מקרבן. ונבין מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]\u0006 בוודאות \u0003\"לא\u0004 אכלתי \u0003\",\u0004 \u0003הא אישתיק\u0004 \u0005[הרי\u0006 אם הוא \u0005שותק]\u0006 — \u0003מהימן\u0004 \u0005[נאמן]\u0006 העד.","\u0003ואמר אביי: אמר לו עד אחד\u0004 לאדם אחד \u0003\"נטמאו טהרותיך\"\u0004 (אוכל שנשמר בטהרה), \u0003והלה,\u0004 בעל הטהרות, \u0003שותק\u0004 — \u0003נאמן. ותנא תונא\u0004 \u0005[ו\u0006כן \u0005שנה התנא שלנו]:\u0006 \u0003עד אחד אומר \"נטמאו\" והלה,\u0004 בעל הטהרות, \u0003אומר \"לא נטמאו\"\u0004 — \u0003פטור. טעמא דאמר\u0004 \u0005[הטעם\u0006 דווקא \u0005ש\u0006הוא \u0005אומר]\u0006 \u0003\"לא\u0004 נטמאו \u0003\",\u0004 \u0003הא אישתיק\u0004 \u0005[הרי\u0006 אם הוא \u0005שותק]\u0006 — \u0003מהימן\u0004 \u0005[נאמן]\u0006 העד האחד.","\u0003ואמר אביי: אמר לו עד אחד\u0004"],["\u0003\"שורך נרבע\"\u0004 ופסול לקרבן \u0003והלה,\u0004 בעל השור, \u0003שותק\u0004 — \u0003נאמן, ותנא תונא\u0004 \u0005[ו\u0006כן \u0005שנה התנא\u0006 שלנו\u0005]\u0006 במשנה: \u0003ו\u0004בהמה \u0003שנעבדה בו עבירה,\u0004 או \u0003שהמית על פי עד אחד או על פי הבעלים\u0004 — \u0003נאמן.\u0004 ונברר: \u0003האי\u0004 \u0005[זה]\u0006 שאמרנו במשנה: ושהמית \u0003על פי עד אחד, היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דקא מודו\u0004 \u0005[אם שמודים]\u0006 ה\u0003בעלים\u0004 — \u0003היינו\u0004 \u0005[הרי זה]\u0006 מה שאמרנו \u0003\"על פי הבעלים\", אלא לאו דשתיק\u0004 \u0005[\u0006האם \u0005לא\u0006 מדובר באופן \u0005ש\u0006הוא \u0005שותק].\u0006","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו כל המימרות של אביי; \u0003דאי אשמעינן הך קמייתא\u0004 \u0005[שאם היה משמיע לנו\u0006 רק \u0005את זו, הראשונה]\u0006 (\"אכלת חלב\"), היינו אומרים שטעם הנאמנות הוא \u0003אי לאו דקים ליה בנפשיה דעבד\u0004 \u0005[אם לא ש\u0006היה \u0005מוחזק לו בעצמו שעשה\u0006 עבירה\u0005]\u0006 — בהמת \u0003חולין בעזרה לא הוה מייתי\u0004 \u0005[היה מביא]\u0006 רק על פי עדות שאינה מחייבת, וכיון ששתק משמע שהוא מודה בדבר.","\u0003אבל\u0004 אם אמר לו \u0003\"נטמאו טהרותיך\"\u0004 ושתק — \u0003מימר אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003האי דשתיק\u0004 \u0005[זה\u0006 \u0005ש\u0006הוא \u0005שותק]\u0006 ולא מכחיש את העד — משום \u0003דסבר\u0004 \u0005[ש\u0006הוא \u0005סבור]\u0006 שאין הפסד גדול בדבר, שהרי \u0003חזי ליה\u0004 \u0005[ראוי לו]\u0006 הדבר לאוכלו \u0003בימי טומאתו,\u0004 שגם אם אינם טהורים, מכל מקום לא נפסדו לגמרי.","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק במקרה של \"נטמאו טהרותיך\", היינו אומרים \u0003הא\u0004 \u0005[זה]\u0006 שהעד נאמן הוא \u0003משום דקא מפסיד ליה\u0004 \u0005[שהוא מפסיד לו]\u0006 \u0003בימי טהרתו,\u0004 וכיון שאינו מוחה — מן הסתם אמת היה הדבר, \u0003אבל \"שורו נרבע\" מימר אמר\u0004 \u0005[אומר]\u0006 הבעלים לגבי השור: \u0003כל השוורים\u0004 שבעולם, מן הסתם \u0003לאו\u0004 \u0005[לא]\u0006 \u0003לגבי\u0004 (לצורך) \u0003מזבח קיימי\u0004 \u0005[\u0006הם \u0005עומדים],\u0006 ואם כן, גם אם מודה שנרבע השור, אין זה אלא פוסלו מלהיות קרבן, וכיון שאין הפסד מרובה בדבר — אינו מוחה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו כל המקרים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: אם אומרים לו לאדם ש\u0003אשתו זינתה בעד אחד, ושותק\u0004 הבעל \u0003מהו\u0004 הדין בכגון זה? \u0003אמר אביי: נאמן\u0004 העד. \u0003רבא אמר: אינו נאמן.\u0004 ומדוע? \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003דבר שבערוה, ו\u0004כלל בידינו: \u0003אין\u0004 עדות לגבי \u0003דבר שבערוה פחות משנים.\u0004","\u0003אמר אביי: מנא אמינא לה\u0004 \u0005[מניין אומר אני אותה],\u0006 את הסברה הזו שלי — \u0003דההוא סמיא דהוה מסדר מתנייתא קמיה\u0004 \u0005[עיור אחד שהיה מסדר,\u0006 חוזר \u0005משניות לפני]\u0006 \u0003מר שמואל. יומא חד נגה ליה ולא הוה קאתי\u0004 \u0005[יום אחד התאחר לו\u0006 העיור \u0005ולא בא].\u0006 \u0003שדר שליחא אבתריה\u0004 \u0005[שלח\u0006 שמואל \u0005שליח אחריו\u0006 שיבוא\u0005].\u0006 \u0003אדאזיל\u0004 \u0005[ב\u0006עוד \u0005שהולך]\u0006 ה\u0003שליח\u0004 לביתו של העיור \u0003בחדא אורחא\u0004 \u0005[בדרך אחת],\u0006 \u0003אתא איהו בחדא\u0004 \u0005[הלך הוא,\u0006 העיור, לבית המדרש \u0005ב\u0006דרך \u0005אחת,\u0006 אחרת\u0005]\u0006 ולכן לא פגש אותו השליח, והגיע עד ביתו. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 ה\u0003שליח\u0004 משליחותו, \u0003אמר\u0004 שהיה בביתו של העיור וראה ש\u0003אשתו זינתה. אתא לקמיה\u0004 \u0005[בא\u0006 העיור \u0005לפני]\u0006 \u0003מר שמואל\u0004 לשאול האם עליו להתחשב בעדות זו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי מהימן לך\u0004 \u0005[נאמן עליך]\u0006 השליח הזה — \u0003זיל אפקה\u0004 \u0005[לך הוצא,\u0006 גרש \u0005אותה]\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא תפיק\u0004 \u0005[אל תוציא].\u0006","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003אי מהימן עלך דלאו גזלנא הוא\u0004 \u0005[אם נאמן עליך שאינו גזלן,\u0006 שאינו פסול לעדות\u0005],\u0006 וכיון שלדעתך הוא עד כשר צריך אתה לסמוך עליו, ואם כן ראיה שעד אחד כשר נאמן בכל מקרה. \u0003ורבא\u0004 מפרש שהכוונה בדברי שמואל היתה: \u0003אי מהימן לך כבי תרי\u0004 \u0005[אם\u0006 הוא \u0005נאמן עליך כשנים]\u0006 — \u0003זיל אפקה\u0004 \u0005[לך\u0006 ו\u0005הוצא אותה]\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא תפקה\u0004 \u0005[אל תוציא אותה].\u0006 ואם כן אין ראיה ממעשה זה.","\u0003ואמר אביי: מנא אמינא לה\u0004 \u0005[מניין אומר אני אותה],\u0006 את הלכתי זו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה בינאי המלך שהלך ל\u0004אזור \u0003כוחלית שבמדבר, וכיבש\u0004 (כבש) \u0003שם ששים כרכים, ובחזרתו היה שמח שמחה גדולה\u0004 על הנצחון. \u0003וקרא לכל חכמי ישראל,\u0004 ו\u0003אמר להם: אבותינו,\u0004 מתוך דלותם, \u0003היו אוכלים מלוחים בזמן שהיו עסוקים בבנין בית המקדש,\u0004 \u0003אף אנו נאכל מלוחים זכר לאבותינו. והעלו מלוחים על שולחנות של זהב, ואכלו.\u0004","\u0003והיה שם אחד, איש לץ לב רע ובליעל, ואלעזר בן פועירה שמו. ויאמר אלעזר בן פועירה לינאי המלך: ינאי המלך, לבם של פרושים עליך,\u0004 כלומר, יש בלבם תרעומת נסתרת עליך, ואינם אוהבים אותך. אמר לו: \u0003ומה אעשה\u0004 כדי לברר אם נכון הדבר? אמר לו: \u0003הקם להם\u0004 (השבע אותם) \u0003בציץ שבין עיניך,\u0004 שעליו יש השם המפורש, שהיה ינאי מזרע החשמונאים, שהיו כהנים, ושימש ככהן גדול. \u0003הקים להם בציץ שבין עיניו.\u0004","\u0003היה שם זקן אחד ויהודה בן גדידיה שמו, ויאמר יהודה בן גדידיה לינאי המלך: ינאי המלך! רב לך כתר מלכות,\u0004 כלומר, די לך במלכות, \u0003הנח כתר כהונה לזרעו של אהרן.\u0004 ומסבירים, \u0003שהיו אומרים: אמו\u0004 של ינאי \u0003נשבית במודיעים\u0004 ונפסלה לכהונה, ואם כן הוא אינו כהן כשר, אלא חלל. \u0003ויבוקש הדבר ולא נמצא,\u0004 שחיפשו למצוא עדויות לגבי אותו מעשה ולא נמצאו עדויות. \u0003ויבדלו\u0004 (הורחקו) \u0003חכמי ישראל בזעם\u0004 של המלך, שכעס עליהם על שמועה זו.","\u0003ויאמר אלעזר בן פועירה לינאי המלך: ינאי המלך, הדיוט שבישראל כך הוא דינו,\u0004 כלומר, שאם נתברר שהעלילו עליו עלילה אין עושים דבר, \u0003ואתה מלך וכהן גדול כך הוא דינך\u0004 שיפטר בלא כלום על דיבה זו? אמר לו ינאי: \u0003ומה אעשה?\u0004 אמר לו: \u0003אם אתה שומע לעצתי: רומסם\u0004 (רמוס אותם, והשמידם). שאל ינאי: \u0003ותורה מה תהא עליה?\u0004 אמר לו: \u0003הרי\u0004 היא \u0003כרוכה ומונחת בקרן זוית, כל הרוצה ללמוד יבוא וילמוד\u0004 ואין צורך בחכמים.","\u0003אמר רב נחמן בר יצחק: מיד נזרקה בו מינות\u0004 בינאי, \u0003דהוה ליה למימר\u0004 \u0005[שהיה לו לומר]\u0006 לאלעזר בן פועירה: \u0003תינח\u0004 \u0005[נניח]\u0006 \u0003תורה שבכתב\u0004 אכן היא מונחת בקרן זוית, ואולם \u0003תורה שבעל פה מאי\u0004 \u0005[מה]\u0006 יהא עליה? שהרי היא נשמרת על ידי החכמים. \u0003מיד: ותוצץ\u0004 (עלתה ונתלקחה) \u0003הרעה על ידי אלעזר בן פועירה, ויהרגו כל חכמי ישראל, והיה העולם משתומם\u0004 (שמם) מתורה, \u0003עד שבא שמעון בן שטח והחזיר את התורה ליושנה.\u0004 עד כאן לשון הברייתא.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק]\u0006 הפריכו את השמועה שנשבתה אמו של ינאי? \u0003אילימא דבי תרי אמרי \"אישתבאי\"\u0004 \u0005[אם תאמר ששנים אמרו \"נשבתה\"]\u0006 \u0003ובי תרי אמרי \"לא אישתבאי\"\u0004 \u0005[ושנים אמרו \"לא נשבתה\"]\u0006 — \u0003מאי חזית דסמכת אהני\u0004 \u0005[מה ראית שאתה סומך על אלה]\u0006 שאמרו \"לא נשבתה\", \u0003סמוך אהני\u0004 \u0005[על אלה]\u0006 שאמרו \"נשבתה\"! ואם כן אי אפשר לומר בוודאות \"ויבוקש הדבר ולא נמצא\"!","\u0003אלא\u0004 מדובר \u0003בעד אחד\u0004 שהעיד שנשבתה ובאו שניים ואמרו שלא נשבתה, \u0003וטעמא\u0004 \u0005[והטעם]\u0006 שאינו נאמן דווקא הוא \u0003דקא מכחשי ליה בי תרי\u0004 \u0005[שמכחישים אותו שנים\u0006 אחרים\u0005],\u0006 \u0003הא לאו הכי מהימן\u0004 \u0005[הרי לולא זה היה נאמן],\u0006 ומכאן ראיה לאביי שעד אחד נאמן כשאין מי שמכחיש אותו.","\u0003ורבא\u0004 אומר שמכאן אין ראיה: \u0003לעולם\u0004 אמור שהיו שם \u0003תרי ותרי\u0004 \u0005[שני\u0006 עדים כנגד \u0005שני\u0006 עדים\u0005]\u0006 \u0003וכדאמר\u0004 \u0005[וכפי שאמר]\u0006 \u0003רב אחא בר רב מניומי\u0004 בענין אחר, שמדובר \u0003בעדי הזמה.\u0004 כלומר, שהעדים השניים לא הכחישו את המעשה אלא הזימו את העדים הראשונים שאמרו: עמנו הייתם באותה שעה במקום אחר ואינכם יכולים איפוא להעיד על דבר שהיה באותו זמן באותו מקום, ונתבטלה עדותם של הראשונים מכל וכל, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בעדי הזמה.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שהיה הענין כפי שסיפר \u0003ר' יצחק,\u0004 ש\u0003אמר ר' יצחק: שפחה הכניסו תחתיה,\u0004 במקום אמו של ינאי. שהעדים הראשונים ראו שעומדים לשבות את אמו של ינאי ובאו העדים השניים וספרו ששפחה הכניסו תחתיה, ואם כן בטלה לגמרי עדותם של הראשונים.","\u0003אמר רבא:\u0004"],["\u0003מנא אמינא לה\u0004 \u0005[מניין אומר אני אותה]\u0006 את דעתי שאין סומכים על עד אחד בדבר של ערוה — על זה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003אמר ר' שמעון: מעשה במגורה\u0004 (מאגר מים) \u0003של דסקים\u0004 (שם מקום או אדם) \u0003ביבנה שהיתה עומדת בחזקת שלימה,\u0004 שהיו סבורים שיש בה ארבעים סאה, כשיעור מקוה לטהר, \u0003ומדדו\u0004 לאחר זמן \u0003ונמצאת\u0004 שהיא \u0003חסירה\u0004 שהיה בה פחות משיעור זה ו","\u0003כל טהרות שנעשו על גבה,\u0004 שטבלו טמאים לשם טהרות במגורה זו עד שנמדדה, \u0003היה ר' טרפון מטהר, ור' עקיבא מטמא.\u0004 והיו מתדיינים בנושא זה. \u0003אמר ר' טרפון: מקוה זה בחזקת שלם הוא עומד\u0004 משך כל הזמן, \u0003מספק אתה בא לחסרו,\u0004 לומר שהיה חסר גם בעבר — \u0003אל תחסרנו מספק. אמר ר' עקיבא\u0004 כנגד זה: \u0003אדם זה\u0004 שטבל באותו מקוה \u0003בחזקת טמא הוא עומד\u0004 לפני שטבל, \u0003מספק אתה בא לטהרו\u0004 — \u0003אל תטהרנו מספק.\u0004","חזר ו\u0003אמר ר' טרפון: משל ל\u0004כהן שהיה \u0003עומד ומקריב על גבי המזבח, ונודע שהוא בן גרושה או בן חלוצה\u0004 — \u0003שעבודתו\u0004 שעשה לפני שנודע פסולו — \u0003כשירה. אמר ר' עקיבא: משל לעומד ומקריב על גבי המזבח ונודע שהוא בעל מום\u0004 — \u0003שעבודתו\u0004 שעבד משנעשה בעל מום \u0003פסולה.\u0004","\u0003אמר ר' טרפון: אתה דימיתו\u0004 את דין המקוה שנמצא חסר \u0003לבעל מום, ואני דמיתיו לבן גרושה או לבן חלוצה, נראה למי דומה. אי\u0004 \u0005[אם]\u0006 \u0003דומה לבן גרושה ולבן חלוצה\u0004 — \u0003נדוננו כבן גרושה או כבן חלוצה, אם דומה לבעל מום\u0004 — \u0003נדוננו כבעל מום.\u0004","\u0003התחיל ר' עקיבא לדון: מקוה פסולו ביחיד,\u0004 שאין צורך בשני עדים לקבוע על פיהם שהמקוה חסר, \u0003ו\u0004כן \u0003בעל מום פסולו ביחיד,\u0004 שאין צורך בשני עדים להעיד שהוא בעל מום, \u0003ואל יוכיח בן גרושה ובן חלוצה שפסולו בשנים,\u0004 שצריכים שני עדים להעיד על אמו כדי לפוסלו, ולא די באחד.","\u0003דבר אחר\u0004 אפשר לומר: \u0003מקוה פסולו בגופו,\u0004 וכן \u0003בעל מום פסולו בגופו, ואל יוכיח בן גרושה ובן חלוצה שפסולו מאחרים\u0004 (מכוח אמו). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' טרפון: עקיבא! כל הפורש ממך כפורש מן החיים.\u0004 שהתפעל ר' טרפון מדברי ר' עקיבא וקיבלם.","עד כאן דברי הברייתא, ומעתה לענייננו: \u0003האי\u0004 \u0005[זה]\u0006 \u0003בעל מום שפסולו ביחיד היכי דמי\u0004 \u0005[כיצד בדיוק היה]?\u0006 \u0003אי דקא\u0004 \u0005[אם שהוא]\u0006 \u0003מכחיש ליה\u0004 \u0005[אותו],\u0006 שבעל המום טוען שאין בו מום — \u0003מי מהימן\u0004 \u0005[האם\u0006 יהיה \u0005נאמן]\u0006 העד האחד? \u0003אלא\u0004 ודאי \u0003מדובר באופן\u0004 \u0003דשתיק\u0004 \u0005[ששותק]\u0006 בעל המום ונחשב לו הדבר כהודאה,","\u0003ודכותיה\u0004 \u0005[וכיוצא בו]\u0006 \u0003גבי בן גרושה ובן חלוצה\u0004 גם כן צריך לומר \u0003דשתיק\u0004 \u0005[ש\u0006האיש עצמו \u0005שותק]\u0006 ואיננו מוחה, \u0003וקתני\u0004 \u0005[ושנה]\u0006 שם: \u0003מקוה פסולו ביחיד ובעל מום פסולו ביחיד, ואל יוכיח בן גרושה ובן חלוצה שפסולו בשנים.\u0004 משמע שעל פי עד אחד, ואפילו בעל הדבר שותק — אין פוסלים אשה!","\u0003ואביי אמר\u0004 כנגד טענה זו: \u0003לעולם\u0004 אתה צריך לפרש בשני המקרים \u0003דקא\u0004 \u0005[שהוא,\u0006 בעל הדבר\u0005]\u0006 \u0003מכחיש ליה\u0004 \u0005[אותו]\u0006 את העד, \u0003ודקאמרת\u0004 \u0005[ו\u0006מה \u0005שאתה אומר]:\u0006 \u0003אמאי מהימן\u0004 \u0005[מדוע\u0006 הוא, העד, \u0005נאמן]\u0006 לומר שהוא בעל מום — יש להסביר \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 העד: \u0003שלח אחוי\u0004 \u0005[פשוט\u0006 בגדיך ו\u0005הראה]\u0006 שאין בך מום, וכיון שיכול הדבר להתגלות — נאמן העד, שהרי אם שקר הוא מעיד יכול הכהן להוכיח זאת. \u0003והיינו דקתני\u0004 \u0005[וזהו ששנינו]:\u0006 \u0003מקוה פסולו בגופו ובעל מום פסולו בגופו,\u0004 שניתן הדבר לבדיקה בו עצמו \u0003ואל יוכיח בן גרושה ובן חלוצה שפסולו מאחרים.\u0004","לגופו של דבר שהזכרנו בברייתא שואלים: \u0003ובן גרושה ובן חלוצה,\u0004 ש\u0003עבודתו\u0004 בדיעבד \u0003כשירה, מנלן\u0004 \u0005[מניין לנו]?\u0006 \u0003אמר רבי יהודה אמר שמואל:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 על פנחס: \u0003\"והיתה לו ולזרעו אחריו\u0004 ברית כהונת עולם\u0003\"\u0004 (במדבר כה, יג), וכוונתו: \u0003בין זרע כשר ובין זרע פסול.\u0004 ומכאן למדים שבדיעבד אין עבודת כהן זה נפסלת אף שנתברר שהיה פסול.","\u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל אמר: מהכא\u0004 \u0005[\u0006ראיה לדבר \u0005מכאן],\u0006 שנאמר בברכה לשבט לוי: \u0003\"ברך ה' חילו ופעל ידיו תרצה\"\u0004 (דברים לג, יא), שדרש מן המלה \"חילו\" ש\u0003אפילו חולין\u0004 (חללים) \u0003שבו תרצה\u0004 את עבודתם בדיעבד.","\u0003ר' ינאי אמר: מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה לדבר, שנאמר בדין הביכורים: \u0003\"ובאת אל הכהן אשר יהיה בימים ההם\"\u0004 (שם כו, ג), \u0003וכי תעלה על דעתך שאדם הולך אצל כהן שלא היה בימיו?\u0004 ואם כן מהו הלשון \"בימים ההם\"? \u0003אלא זה\u0004 שהיה כהן \u0003כשר ונתחלל,\u0004 שכל ימיו שעבד בכהונה, נחשב לכהן (כשר).","וממשיכים לברר את האמור בברייתא: \u0003בעל מום\u0004 ש\u0003עבודתו פסולה\u0004 למפרע \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 \u0003אמר רב יהודה אמר שמואל:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 על פנחס הכהן \u0003\"לכן אמר הנני נתן לו את בריתי שלום\"\u0004 (במדבר כה, יב), וכוונתו \u0003כשהוא שלם\u0004 נכרתה לו ברית \u0003ולא כשהוא חסר\u0004 אבר שהוא בעל מום. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"שלום\" כתיב\u0004 \u0005[כתוב]\u0006 ולא \"שלם\"! \u0003אמר רב נחמן:\u0004 האות \u0003וי\"ו\u0004 של המלה \u0003שלום קטיעה\u0004 \u0005[קטועה]\u0006 \u0003היא,\u0004 שמסורת היא שכותבים אותה קטועה, וניתן לקרוא את המלה כאילו היתה כתובה \"שלם\".","כלל הוא בהלכות יוחסין: \u0003כל מקום שיש,\u0004 שתופסים, \u0003קידושין ואין עבירה\u0004 בנישואין הללו, שאין בהם איסור מן התורה — \u0003הולד הולך אחר הזכר,\u0004 שייחוסו נחשב אחרי אביו. \u0003ואיזה זו\u0004 — כגון \u0003זו כהנת,\u0004 או \u0003לויה,\u0004 או \u0003ישראלית, שנשאו לכהן,\u0004 או ל\u0003לוי,\u0004 או ל\u0003ישראל,\u0004 שבכל אלה הולד מתייחס אחר משפחת אביו.","\u0003וכל מקום שיש,\u0004 שתופסים, \u0003קידושין ויש עבירה\u0004 — \u0003הולד הולך אחר ה\u0004הורה ה\u0003פגום. ואיזה זו\u0004 למשל \u0003זו אלמנה\u0004 שנישאה \u0003לכהן גדול,\u0004 או \u0003גרושה,\u0004 או \u0003חלוצה\u0004 שנישאה \u0003לכהן הדיוט,\u0004 או \u0003ממזרת,\u0004 או \u0003נתינה\u0004 שנישאה \u0003לישראל,\u0004 או \u0003בת ישראל\u0004 שנישאה \u0003לממזר,\u0004 או \u0003לנתין,\u0004 שדין הולד כדין ההורה הפגום שביניהם.","\u0003וכל מי שאין לה עליו קידושין\u0004 בזיווג זה, שהקידושין אינם תופסים, \u0003אבל יש לה על אחרים קידושין,\u0004 כלומר, אותה אשה יכולה באופן כללי להתקדש, שהיא מכלל ישראל — במקרה כזה \u0003הולד ממזר. ואיזה זה\u0004 — \u0003זה הבא על אחת מכל העריות ש\u0004כתובות \u0003בתורה. וכל מי שאין לה לא עליו ולא על אחרים קידושין\u0004 — במקרה זה \u0003הולד כמותה,\u0004 שאינו מתייחס ואינו נחשב כלל כבן אביו, אלא הריהו כאמו. \u0003ואיזה זה\u0004 — \u0003זה ולד שפחה,\u0004 או \u0003גויה\u0004 שולדה הוא כמותה עבד או גוי, ואם יתגייר אינו קרוי ממזר.","שנינו במשנה ש\u0003כל מקום שיש קידושין\u0004 ואין עבירה — הולד הולך אחר הזכר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון לר' יוחנן:\u0004 האם \u0003כללא\u0004 \u0005[כלל]\u0006 \u0003הוא\u0004 ש\u0003כל מקום שיש קידושין ואין עבירה הולד הולך\u0004 תמיד \u0003אחר הזכר? הרי\u0004"],["\u0003גר שנשא ממזרת\u0004 ש\u0003יש קידושין,\u0004 שקידושיו תופסים בה \u0003ואין עבירה\u0004 בדבר, שכן הם מותרים זה לזו ובכל זאת \u0003הולד הולך אחר הפגום,\u0004 והוא ממזר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גר שנשא ממזרת\u0004 — \u0003הולד ממזר,\u0004 אלו \u0003דברי ר' יוסי! אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 כשיטת \u0003ר' יוסי היא?\u0004 — לא, \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 כשיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר: גר לא ישא ממזרת, ו\u0004אם כן לדעתו זהו מקרה ש\u0003יש קידושין ויש עבירה,\u0004 ולכן \u0003הולד הולך אחר הפגום.\u0004","ושואלים: אם כן \u0003וניתנייה\u0004 \u0005[ושישנה אותה]\u0006 במשנה בתוך הדוגמאות שהביא! ומשיבים: \u0003תנא\u0004 \u0005[\u0006מה \u0005ששנה]\u0006 במשנה את הכלל \u0003\"כל מקום\u0004 שיש קידושין ויש עבירה \u0003\"\u0004\u0003דסיפא\u0004 \u0005[ש\u0006שנינו \u0005בסוף],\u0006 הרי זה בא \u0003לאתויי\u0004 \u0005[להביא\u0006 להוסיף\u0005]\u0006 גם מקרה זה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003לעולם\u0004 משנתנו כשיטת \u0003ר' יוסי היא, ותנא\u0004 \u0005[ושנה]\u0006 \u0003\"איזו זו\" למעוטי\u0004 \u0005[למעט],\u0006 שרק המקרים שמנה שיש בהם קידושין ואין עבירה, הם המקרים שבהם הולד הולך אחר האב.","ושואלים: \u0003ו\u0004כי \u0003\"איזו זו\" ותו לא\u0004 \u0005[ואין עוד]\u0006 מקרים שהם בכלל זה? \u0003והרי חלל שנשא בת ישראל,\u0004 ש\u0003יש קידושין ואין עבירה\u0004 בכך, ובכל זאת \u0003הולד הולך אחר הזכר\u0004 והוא חלל! ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 שאפשר לומר שהתנא של משנתנו \u0003כ\u0004דעת \u0003ר' דוסתאי בן ר' יהודה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שלדעתו הולד כשר לגמרי.","ומקשים: \u0003והרי ישראל שנשא חללה,\u0004 ש\u0003יש קידושין ואין עבירה\u0004 בכך ועם כל זה \u0003הולד הולך אחר הזכר\u0004 ובכל זאת לא נשנה הדבר במפורש! ומשיבים: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003\"כל מקום\u0004 שיש קידושין ואין עבירה \u0003\"\u0004\u0003דרישא\u0004 \u0005[ש\u0006נאמר \u0005בראש\u0006 המשנה\u0005]\u0006 \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 גם מקרה זה.","ומקשים: \u0003וניתנייה בהדיא\u0004 \u0005[ושישנה זאת במפורש]!\u0006 ומשיבים: \u0003משום\u0004 ש\u0003לא מתני\u0004 \u0005[נשנית]\u0006 \u0003לה.\u0004 כלומר, אינו יכול להכניס הלכה זו בקיצור בתוך ניסוחי הדברים של המשנה. כי \u0003היכי ניתני\u0004 \u0005[כיצד ישנה]?\u0006 אם ישנה \u0003כהנת, ולויה, וישראלית, וחללה, שנשאת לכהן לוי וישראל\u0004 — אולם אי אפשר לומר את המשפט כך, כי \u0003וחללה לכהן מי חזיא\u0004 \u0005[האם\u0006 היא \u0005ראויה],\u0006 הרי יש בקידושין אלו עבירה? ולכן לא שנה בדרך זו.","ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 גם ההלכה של \u0003רבה בר בר חנה.\u0004 ש\u0003אמר רבה בר בר חנה, אמר ר' יוחנן: מצרי שני\u0004 (בנו של גר מצרי) \u0003שנשא מצרית ראשונה\u0004 (שהיא עצמה התגיירה) — \u0003בנה שלישי הוי\u0004 \u0005[הוא]\u0006 וכשר לבוא בקהל. והוא דוגמא שיש קידושין ואין עבירה והולד הולך אחר האב!","ומשיבים: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003\"כל מקום\" דרישא\u0004 \u0005[שבראש\u0006 המשנה\u0005]\u0006 \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 גם מקרה זה. ומעירים: \u0003ול\u0004דעת \u0003רב דימי,\u0004 ש\u0003אמר\u0004 שולד זה מצרי \u0003שני הוי\u0004 \u0005[הוא],\u0006 אם כן לדעתו \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003\"איזו זו\"\u0004 בראש המשנה (יש קידושין ואין עבירה) \u0003למעוטי\u0004 \u0005[למעט]\u0006 מקרה זה (שהרי לדעתו עדיין בן זה אסור לבוא בקהל).","ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 מקרה הסותר לדין משנתנו, \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: באומות,\u0004 אם בני שתי אומות, בהיותם גויים, התחתנו זה בזה — \u0003הלך\u0004 \u0005[לך]\u0006 לענין דינו של הולד הנולד להם \u0003אחר הזכר,\u0004 בין שהוא גוי סתם וראוי לבוא בקהל ישראל מיד לכשיתגייר או שהוא עמוני או מצרי ואינו ראוי לבוא בקהל, שהולד מתייחס לענין הלכה אחר האב.","אם \u0003נתגיירו\u0004 שניהם, בני שתי האומות — \u0003הלך\u0004 \u0005[לך]\u0006 \u0003אחר הפגום שבשניהם.\u0004 והרי גרים אלה מותרים זה בזה ויש להם קידושין, ואם היו האב או האם מצרי — הולד הולך אחר ההורה הפגום ונחשב כמצרי, ולפי המשנה — הלך אחר הזכר! ומשיבים: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003\"איזו זו\" למעוטי\u0004 \u0005[למעט]\u0006 מקרה זה.","ודוחים: \u0003האי מאי\u0004 \u0005[זה\u0006 שהסברנו לעיל את משנתנו לפי ר' יוסי \u0005מהו]?\u0006 \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 כשיטת \u0003ר' יהודה היא,\u0004 אפשר לפרש ש\u0003\"כל מקום\"\u0004 ששנה \u0003דרישא\u0004 \u0005[בתחילה]\u0006 \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003ישראל שנשא חללה,\u0004 שגם בזה הולד הולך אחר האב, \u0003ו\u0004להביא גם מה שאמר \u0003רבה בר בר חנה\u0004 שמצרי שני שנשא מצרית ראשונה בנה הריהו שלישי, ומה שאמר \u0003\"איזו זו\"\u0004 שבא למעט — הרי זה \u0003למעוטי\u0004 \u0005[למעט]\u0006 את מה שאמר \u0003רב דימי\u0004 שבנה שני, או רק את מה שאמר \u0003רבין\u0004 בשם ר' יוחנן"],["\u0003\"כל מקום\"\u0004 (יש קידושין ויש עבירה) \u0003דסיפא\u0004 \u0005[ש\u0006נאמר \u0005בסוף\u0006 המשנה\u0005]\u0006 — \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003גר שנשא ממזרת. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שמשנתנו שיטת \u0003ר' יוסי היא, \"כל מקום\"\u0004 (יש קידושין ואין עבירה) \u0003דרישא\u0004 \u0005[שבראש\u0006 המשנה\u0005]\u0006 \u0003כדאמרן\u0004 \u0005[כפי שאמרנו]\u0006 לרבות ישראל שנשא חללה, \u0003\"איזו זו\"\u0004 שבא למעט גם הוא \u0003כדאמרן\u0004 \u0005[כפי שאמרנו],\u0006 כדברי רבין או רב דימי, וכן גר שנשא ממזרת, \u0003אלא \"כל מקום\" דסיפא\u0004 \u0005[ש\u0006נאמר \u0005בסוף]\u0006 \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]\u0006 בא?","ודוחים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 הלא גם \u0003לר' יהודה \"איזו זו\" דסיפא\u0004 \u0005[ש\u0006נאמר \u0005בסוף]\u0006 \u0003למה לי? אלא\u0004 חייב אתה לומר: \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה\u0006 ב\u0005ראש]\u0006 לשון \u0003\"איזו זו\", תנא סיפא\u0004 \u0005[שנה\u0006 ב\u0005סוף]\u0006 גם כן \u0003\"איזו זו\"\u0004 אף שאינו לצורך, אלא רק לשם אחידות הלשון. אם כן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר לגבי שיטת ר' יוסי \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה\u0006 ב\u0005ראש]\u0006 \u0003\"כל מקום\", תנא נמי סיפא\u0004 \u0005[שנה גם כן\u0006 ב\u0005סוף]\u0006 \u0003\"כל מקום\".\u0004","\u0003גופא\u0004 \u0005[\u0006ל\u0005גופה]\u0006 של אותה הלכה שהזכרנו: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: באומות,\u0004 כלומר, בנים להורים משתי אומות שנישאו זה לזה — \u0003הלך\u0004 \u0005[לך]\u0006 \u0003אחר הזכר\u0004 ולפי זה הם נידונים בהלכה. ואם \u0003נתגיירו\u0004 שניהם ואז נישאו — \u0003הלך\u0004 \u0005[לך]\u0006 \u0003אחר הפגום שבשניהם.\u0004","ומסבירים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"באומות הלך\u0004 \u0005[לך]\u0006 \u0003אחר הזכר\"\u0004 — \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מנין לאחד מן האומות\u0004 שמחוץ לארץ ישראל \u0003שבא על הכנענית והוליד\u0004 ממנה \u0003בן, שאתה רשאי לקנותו בעבד\u0004 ואינו בכלל העמים הכנענים שאסור להחיותם בארץ —","\u0003תלמוד לומר: \"וגם מבני התושבים הגרים עמכם מהם תקנו\"\u0004 (ויקרא כה, מה), שיש אופן שניתן לקנות עבדים גם מבני ארץ כנען. \u0003יכול אף עבד,\u0004 כלומר, כנעני \u0003שבא על שפחה מן האומות והוליד בן, שאתה רשאי לקנותו בעבד\u0004 — \u0003תלמוד לומר: \"אשר הולידו בארצכם\"\u0004 (שם), וכוונתו: \u0003מן הנולדין בארצכם,\u0004 אבל אביהם אינו מן האומות שבארץ, \u0003ולא מן הגרים בארצכם,\u0004 אותם שאביהם משבע אומות.","ועוד באותה הלכה שאמר ר' יוחנן, \u0003\"נתגיירו הלך\u0004 \u0005[לך]\u0006 \u0003אחר הפגום שבשניהם\",\u0004 ונברר: \u0003במאי\u0004 \u0005[במה],\u0006 באיזה מקרה מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי מדובר \u0003במצרי שנשא עמונית, מאי\u0004 \u0005[מה]\u0006 \u0003פגום\u0004 בשניהם \u0003איכא\u0004 \u0005[יש כאן]?\u0006 הרי העמונית אינה פגומה כלל לאחר שהתגיירה, שהרי כבר דרשו חכמים על הפסוק \"לא יבוא עמוני... בקהל ה'\" (דברים כג, ד) — \u0003עמוני ולא עמונית\u0004 והיא רשאית לבוא בקהל ישראל.","\u0003אלא\u0004 צריך לפרש כי מדובר \u0003בעמוני שנשא מצרית ו\u0004במקרה זה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003זכר הוי\u0004 \u0005[הוא]\u0006 הולד — \u0003האי, שדיא אבתריה דידיה\u0004 \u0005[זה, השלך,\u0006 הטל \u0005אותו אחריו],\u0006 אחרי אביו, והחשב אותו לעמוני, ואסור לבוא בקהל לעולם. \u0003ואם נקבה הויא\u0004 \u0005[היא]\u0006 הנולדת מהם — \u0003שדיא אבתרה דידה\u0004 \u0005[השלך אותה עליה]\u0006 והיא נחשבת למצרית שניה, האסורה לבוא בקהל.","שנינו במשנה כי \u0003כל שאין לה עליו קידושין\u0004 אבל יש לה על אחרים קידושין — הולד ממזר. ומסבירים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן ומטו בה\u0004 \u0005[ו\u0006יש \u0005מושכים,\u0006 ממשיכים, \u0005אותה\u0006 מסורת\u0005]\u0006 \u0003משום\u0004 (בשם) \u0003ר' ינאי. ורב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא\u0004 היה אומר \u0003ומטו בה\u0004 \u0005[ו\u0006מגיעים, \u0005מושכים אותה]\u0006 עד \u0003משום\u0004 (בשם) \u0003ר' יוסי הגלילי: אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין אשה שנתגרשה מבעלה: \u0003\"ויצאה מביתו והלכה והיתה לאיש אחר\"\u0004 (דברים כד, ב) ויש בכך הדגשה — \u0003לאחרים\u0004 יכולה היא להיות לאשה \u0003ולא לקרובים,\u0004 שאין קידושין שלהם תופסים בה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אבא: ואימא\u0004 \u0005[ואמור,\u0006 פרש\u0005]\u0006 כי \u0003\"לאחר\"\u0004 כוונתו \u0003ולא לבן\u0004 בעלה, ותלמד מכאן רק למקום שיש בו איסור מיתת בית דין ולא לאיסורי כרת! ודוחים: \u0003בן בהדיא כתיב ביה\u0004 \u0005[במפורש נאמר בו]\u0006 \u0003\"לא יקח איש את אשת אביו\"\u0004 (שם כג, א), כלומר, שאין הקידושין תופסים (\"לא יקח\"), ואם כן ההדגשה \u0003\"אחר\" למה לי\u0004 — \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 \u0003לאחרים ולא לקרובים.\u0004","ודוחים, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003אידי ואידי\u0004 \u0005[זה וזה],\u0006 שני המקראות נאמרו \u0003לבן,\u0004 ומדוע צריכים שני מקראות — \u0003הא\u0004 \u0005[זה]\u0006 הפסוק \"לא יקח\" — \u0003לכתחילה,\u0004 ואין כוונתו לומר שאין קידושין תופסים בה, אלא רק שאסור לעשות כן, \u0003והא\u0004 \u0005[וזה]\u0006 הפסוק \"והיתה לאיש אחר\" ללמד שגם ב\u0003דיעבד\u0004 אם קידש אותה הבן אין הקידושין תופסים.","ומקשים: שקידושין אסורים בבן \u0003לכתחילה\u0004 יודעים אנו ממקור אחר, שכן \u0003מאחות אשה נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006 שאנו למדים בקל וחומר: \u0003ומה אחות אשה\u0004 שהיא \u0003בכרת\u0004 — \u0003לא תקדש,\u0004 שאסור לקדש אותה, שנאמר \"ואשה אל אחותה לא תקח\" (ויקרא יח, יח), \u0003חייבי מיתות בית דין\u0004 ובהם אשת אביו \u0003לא כל שכן?\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003אידי ואידי\u0004 \u0005[זה וזה],\u0006 כלומר, גם הפסוק \"לא תקח\", וגם הפסוק \"והיתה לאיש אחר\" עוסקים \u0003באחות אשה, הא\u0004 \u0005[זה]\u0006 (\"לא תקח\") \u0003לכתחילה הא\u0004 \u0005[זה]\u0006 (\"לאיש אחר\") ב\u0003דיעבד,\u0004 שאין קידושין תופסים בה. ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך הוא גם כן]\u0006 כפי שאמרת מתפרש הכתוב.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 אם כן הלכה זו ב\u0003אחות אשה, שאר עריות מנלן\u0004 \u0005[מנין לנו]\u0006 שאין קידושין תופסים בהן? ומשיבים: \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 דבר זה \u0003מאחות אשה\u0004 בדרך הלימוד של בנין אב: \u0003מה אחות אשה מיוחדת\u0004 (שנתייחד לה הכתוב) \u0003שהיא\u0004 איסור \u0003ערוה וחייבין על זדונה\u0004 (אם בא עליה בזדון) \u0003כרת, ועל שגגתה\u0004 (אם בא עליה בשגגה) מביא קרבן \u0003חטאת, ולא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קידושין\u0004 — \u0003אף כל שהיא ערוה, וחייבין על זדונה כרת ועל שגגתה חטאת\u0004 — \u0003לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קידושין.\u0004","ואומרים: \u0003בשלמא כולהו אתיין\u0004 \u0005[נניח\u0006 שכל העריות \u0005כולן באות,\u0006 נלמדות\u0005]\u0006 בדרך זו, \u0003אלא אשת איש ואשת אח\u0004 שהן יוצאות מן הכלל \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך]\u0006 ולומר שאינן בכלל זה. כיצד? \u0003מה לאחות אשה\u0004 — \u0003שכן אין לה היתר במקום מצוה,\u0004 שאף במקום שיש מצות ייבום — בכל זאת אסור לייבם את אחות אשתו, \u0003תאמר באשת אח שיש לה היתר במקום מצוה\u0004 של ייבום.","וכן ב\u0003אשת איש נמי איכא למיפרך\u0004 \u0005[גם כן יש\u0006 מקום \u0005לפרוך]:\u0006 \u0003מה להנך\u0004 \u0005[לאלה],\u0006 אחות אשה ואשת אח, \u0003שכן אין לה\u0004 לערוה \u0003היתר בחיי אוסרן\u0004 על כל פנים, שגם אחות אשה וגם אשת אח אין להן היתר לפחות בחייו של זה שהוא האוסר אותה, כגון אחות אשתו שאין לה היתר כל זמן שאשתו חיה, \u0003תאמר באשת איש שיש לה היתר בחיי אוסרן,\u0004 כלומר, בעלה על ידי גירושין!","\u0003אלא\u0004 יש ללמוד הלכה זו ממקור אחר ש\u0003אמר ר' יונה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת איסור עריות: \u0003\"\u0004כי \u0003כל אשר יעשה מכל התועבת האלה ונכרתו\"\u0004 (ויקרא יח, כט) \u0003הוקשו\u0004 \u0005[הושוו]\u0006 בפסוק זה \u0003כל העריות כולם\u0004 זו לזו, וממילא גם \u0003לאחות אשה; מה אחות אשה לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קידושין\u0004 — \u0003אף כל עריות כולם לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קידושין.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמכאן אתה למד"],["\u0003אפילו נדה נמי\u0004 \u0005[גם כן]\u0006 אם קידש אותה לא יתפסו בה קידושין ויהא הולד ממזר, שהרי גם נדה מנויה בין העריות באותה פרשה, \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003אמר אביי: הכל מודים בבא על הנדה ועל הסוטה,\u0004 אשתו שסטתה תחתיו ונאסרה עליו, \u0003שאין הולד ממזר? אמר חזקיה:\u0004 בענין נדה יש לימוד מיוחד, \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"ותהי נדתה עליו\"\u0004 (ויקרא טו, כד), לומר: \u0003אפילו בשעת נדתה\u0004 — \u0003תהא בה הויה\u0004 (\"תהי\") של קידושין.","ומקשים: \u0003מכדי איכא לאקושה\u0004 \u0005[הרי יש\u0006 מקום, אפשר \u0005להקיש\u0006 אותם\u0005]\u0006 את כל שאר העריות \u0003לנדה, ואיכא לאקושה\u0004 \u0005[ויש\u0006 מקום \u0005להקיש\u0006 אותם\u0005]\u0006 \u0003לאחות אשה, מאי חזית דמקשת להו\u0004 \u0005[מה ראית שאתה מקיש אותן]\u0006 \u0003לאחות אשה? אקשה\u0004 \u0005[הקש\u0006 אותם\u0005]\u0006 \u0003לנדה!\u0004 ומשיבים: כשיש אפשרות להקיש לדבר שמסקנתו ל\u0003קולא\u0004 \u0005[להקל]\u0006 \u0003ו\u0004להקיש לדבר שיש בו \u0003חומרא\u0004 \u0005[להחמיר]\u0006 — \u0003לחומרא מקשינן\u0004 \u0005[להחמיר אנו מקישים].\u0006","\u0003רב אחא בר יעקב אמר\u0004 מקור אחר שאין קידושין תופסים בעריות: \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו \u0003בקל וחומר מיבמה: ומה יבמה\u0004 לפני שקיבלה חליצה מהיבם, \u0003שהיא ב\u0004איסור \u0003לאו\u0004 שאין בו אלא מלקות \u0003לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קידושין, חייבי מיתות וחייבי כריתות לא כל שכן.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שמכאן אתה למד, \u0003שאר חייבי לאוין נמי\u0004 \u0005[גם כן]\u0006 נלמד בבנין אב שאין קידושין תופסים בהם!","\u0003אמר רב פפא: חייבי לאוין בהדיא כתיב בהו\u0004 \u0005[במפורש נאמר בהם]\u0006 \u0003\"כי תהיין לאיש שתי נשים האחת אהובה והאחת שנואה\"\u0004 (דברים כא, טו), והלשון תמוהה, \u0003וכי יש שנואה לפני המקום ואהובה לפני המקום,\u0004 שאמר סתם \"אהובה\" ו\"שנואה\", ולא פירש אהובה או שנואה על בעלה? \u0003אלא: \"אהובה\"\u0004 בלשון כללית זו כוונתו \u0003אהובה בנישואיה,\u0004 שהיו נישואיה כשרים, ו\u0003שנואה\u0004 כוונתו \u0003שנואה בנישואיה\u0004 שהיה איסור של חייבי לאוין בנישואין הללו. \u0003וקאמר רחמנא\u0004 \u0005[ואומרת התורה]:\u0006 \u0003\"כי תהיין\",\u0004 כלומר, — יש בהן הויה של קידושין למרות האיסור.","ושואלים: \u0003ול\u0004דעת \u0003ר' עקיבא\u0004 ש\u0003אמר: אין קידושין תופסין בחייבי לאוין, \"כי תהיין\" במאי מוקים\u0004 \u0005[במה\u0006 הוא \u0005מעמיד]?\u0006 ומשיבים: \u0003באלמנה לכהן גדול, וכ\u0004דברי \u0003ר' סימאי.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' סימאי אומר: מן הכל,\u0004 כלומר, הנולד מכל איסורי לאוין, \u0003היה ר' עקיבא עושה ממזר, חוץ מ\u0004הנולד מנישואי \u0003אלמנה לכהן גדול, שהרי אמרה\u0004 בו \u0003תורה \"\u0004ו\u0003לא יחלל\"\u0004 (ויקרא כא, טו), ללמד: \u0003חילולים\u0004 הוא \u0003עושה,\u0004 שבניו מנישואין אלה נקראים חללים \u0003ואין\u0004 הוא \u0003עושה ממזרות.\u0004","ושואלים: \u0003ול\u0004דעת \u0003ר' ישבב\u0004 ש\u0003אמר: בואו ונצווח על עקיבא בן יוסף שהיה אומר: כל שאין לו ביאה בישראל,\u0004 כלומר, שיש איזשהו איסור על ביאתו ואפילו איסור של אלמנה לכהן גדול, \u0003הולד\u0004 הנולד לו \u0003ממזר. הניחא\u0004 \u0005[זה נוח]\u0006 \u0003לר' ישבב אי לאפוקי\u0004 \u0005[אם להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' סימאי קאתי\u0004 \u0005[בא]\u0006 — \u0003שפיר\u0004 \u0005[יפה],\u0006 כלומר, שהוא מבין שר' עקיבא סבור שגם מן הלאו של אלמנה לכהן גדול הולד הוא ממזר, אבל מחייבי עשה — אין הולד ממזר ויש להעמיד איפה את הפסוק (\"האחת שנואה\") בחייבי עשה.","\u0003אלא אי טעמא דנפשיה קאמר\u0004 \u0005[אם טעם,\u0006 שיטה, \u0005משל עצמו הוא,\u0006 ר' ישבב, \u0005אומר]\u0006 וצריך להבין את דבריו בדרך כללית, \u0003ו\u0004לכן \u0003אפילו חייבי עשה\u0004 בכלל זה, שלשיטתו ר' עקיבא אומר שהולד מהם ממזר, אם כן \u0003במאי מוקים לה\u0004 \u0005[במה\u0006 הוא \u0005מעמיד אותה]\u0006 את ה\"שנואה\" שבכתוב?","ומשיבים: \u0003ב\u0004אשה \u0003בעולה לכהן גדול,\u0004 שאסורה עליו משום שיש מצות עשה על הכהן הגדול לשאת רק בתולה. ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]?\u0006 שאם הוא סבור שכל חייבי עשה הולד מהם ממזר — הרי גם בנישואי בעולה לכהן גדול יש איסור עשה! ומשיבים: \u0003משום דהוי ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003עשה שאין שוה בכל,\u0004 שמצות עשה זו קלה יותר שכן היא חלה רק על הכהן הגדול, ולא על אדם אחר ומצוה שאינה שווה בכל ישראל קלה יותר.","ושואלים: \u0003ורבנן\u0004 \u0005[ו\u0006לדעת \u0005חכמים]\u0006 החולקים על ר' עקיבא \u0003אדמוקי לה\u0004 \u0005[עד שמעמידים אותה]\u0006 את דברי התורה \"כי תהיינה... והאחת שנואה\" \u0003בחייבי לאוין, נוקמא\u0004 \u0005[נעמיד אותה]\u0006 \u0003בחייבי עשה\u0004 שדווקא בהן קידושין חלים!","ואומרים: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003חייבי עשה במאי נינהו\u0004 \u0005[במה הם],\u0006 באיזו מצות עשה מדובר? \u0003אי\u0004 אם תאמר ש\u0003שתיהן,\u0004 שתי הנשים הן גיורות \u0003מצריות,\u0004 אם כן \u0003שתיהן שנואות,\u0004 שהרי יש איסור בנישואיהן, \u0003אי\u0004 \u0005[אם]\u0006 \u0003אחת מצרית ואחת ישראלית\u0004 — אי אפשר לומר זאת כי \u0003\"שתי נשים\" מעם אחד בעינן\u0004 \u0005[צריכים אנו],\u0006 שהרי משווה התורה את שתי הנשים. \u0003אי\u0004 \u0005[אם]\u0006 \u0003בעולה לכהן גדול\u0004 היא השנואה, יש לשאול: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"תהיין לכהן\"?\u0004 הלא נאמר באופן כללי \"תהיינה לאיש\"! ואם כן אין מקום להעמיד את הכתוב הזה בחיובי עשה.","ושואלים: אם כן, \u0003ור' עקיבא\u0004 הלא לשיטתו שאין קידושין תופסין בחייבי לאוין, יש להסביר את הפסוק הזה דווקא בבעולה לכהן גדול או במצרית שהן חייבי עשה! ומשיבים: לדעתו \u0003בעל כורחיך שבקיה לקרא דהוי דחיק ומוקי אנפשיה\u0004 \u0005[הנח למקרא שהוא,\u0006 המקרא, \u0005דוחק ומעמיד את עצמו],\u0006 כלומר שמתוך כל שיטותיו שאין קידושין תופסים במקום איסור, אין לנו דרך אלא להעמיד את המקרא (\"כי תהיינה\") בצורה זו.","שנינו במשנה ש\u0003כל מי שאין לה עליו\u0004 ולא על אחרים קידושין — הולד הולך אחריה. והן שפחה וגויה. ושואלים: \u0003שפחה כנענית מנלן\u0004 \u0005[מניין לנו]\u0006 שאין קידושין תופסים בה? \u0003אמר רב הונא: אמר קרא\u0004 \u0005[הכתוב]\u0006 שאמר אברהם לעבדיו: \u0003\"שבו לכם פה עם החמור\"\u0004 (בראשית כב, ה), לרמז שקרא לעבדיו \u0003עם הדומה לחמור,\u0004 ומכאן אנו למדים שכשם שאין קידושין תופסים בבהמה כך אין קידושין תופסים בשפחה. ואומרים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא ש\u0003לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה,\u0004 בשפחה, \u0003קדושי\u0004 \u0005[קידושין\u0006\u0005],\u0006 ואולם זה"],["\u0003ולדה כמותה מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי עבד עברי הנשוי לשפחה כנענית: \u0003\"האשה וילדיה תהיה לאדניה\"\u0004 (שמות כא, ד), משמע שילדיה של השפחה מן העברי הולכים אחריה והם עבדים.","\u0003גויה מנלן\u0004 \u0005[מניין לנו]\u0006 שאין קידושין תופסים בה? \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ו\u0003לא תתחתן בם\"\u0004 (דברים ז, ג), לומר שאין בהם דין חיתון. ושואלים: \u0003אשכחנא\u0004 \u0005[מצאנו]\u0006 איפוא מכאן ש\u0003לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קידושי\u0004 \u0005[קידושין],\u0006 ואולם דין זה ש\u0003ולדה כמותה מנלן\u0004 \u0005[מניין לנו]?\u0006","\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 באותו ענין \u0003\"\u0004בתך לא תתן לבנו... \u0003כי יסיר את בנך מאחרי\"\u0004 (שם ג–ד), וכיון שהמקרא חושש כי לאחר שתתחתן הבת עם גוי יסיר גוי זה את ילדיו מעבודת ה', משמע כי \u0003בנך,\u0004 כלומר, בן בנך \u0003הבא מישראלית קרוי\u0004 בכתוב \u0003בנך, ואין בנך הבא מן הגויה קרוי בנך, אלא בנה.\u0004","\u0003אמר רבינא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003בן בתך הבא מן הגוי קרוי בנך\u0004 לכל דבר. ושואלים: \u0003נימא קסבר\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005סבור]\u0006 \u0003רבינא\u0004 כי \u0003גוי ועבד הבא על בת ישראל הולד ממזר?\u0004 שאפשר ללמוד מדבריו שכיון שהוא קרוי \"בנך\" הרי הוא ישראל וחל עליו הכלל שבמשנה: כל מי שאין לה עליו קידושין — הולד ממזר.","ודוחים: \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003כשר לא הוי\u0004 \u0005[איננו],\u0006 \u0003ממזר\u0004 גם כן \u0003לא הוי\u0004 \u0005[איננו],\u0006 אלא רק \u0003פסול מיקרי\u0004 \u0005[\u0006הוא \u0005נקרא]\u0006 שכיון שאין קידושין לגוי, אין הנולד לו נכנס בגדר \"אין לה עליו קידושין ויש לאחרים קידושין\". אבל מכל מקום לידתו היתה בעבירה, ולכן הוא פסול.","ושואלים לגופם של דברי ר' יוחנן: \u0003ההוא\u0004 \u0005[אותו]\u0006 כתוב \"לא תתחתן\" \u0003בשבעה גוים\u0004 של עמי כנען \u0003כתיב\u0004 \u0005[נאמר],\u0006 \u0003שאר אומות מנלן\u0004 \u0005[מניין לנו]\u0006 שגם כן אין קידושין תופסים בהם? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בטעמו של איסור החיתון: \u0003\"כי יסיר את בנך\u0004 מאחרי\u0003\",\u0004 ומטעם זה אנו אומרים שיש \u0003לרבות\u0004 את \u0003כל המסירים\u0004 אף מאומות אחרות.","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003ר' שמעון דדריש טעמא דקרא\u0004 \u0005[שדורש\u0006 את \u0005טעם הכתוב],\u0006 ולכן כיון שהטעם הוא משום הסרת הלב, שוב אין להבדיל בין כנענים לאומות אחרות. \u0003אלא לרבנן\u0004 \u0005[לד\u0006 עת \u0005חכמים]\u0006 שאינם דורשים טעמי הכתובים ואין הכתוב עוסק אלא בעמי כנען, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 מה מקור האיסור בשאר האומות?","ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 באשת יפת תואר: \u0003\"ואחר כן תבוא אליה ובעלתה\u0004 והיתה לך לאשה\" (שם כא, יג), \u0003מכלל\u0004 הדברים אתה למד \u0003דמעיקרא\u0004 \u0005[שמתחילה]\u0006 לפני שנעשתה ישראלית \u0003לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קידושין,\u0004 על אף שלקחה כבר לתוך ביתו, ולחלק מן הדעות אף בא עליה.","ועוד שואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 אפוא ש\u0003לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קידושין,\u0004 אך דבר זה ש\u0003ולדה כמותה מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי תהיין לאיש... וילדו לו\",\u0004 (שם טו), לומר: \u0003כל היכא דקרינן ביה\u0004 \u0005[מקום שאנו קוראים בו]\u0006 \u0003\"כי תהיינה\",\u0004 כלומר, שיש לנשים הויית נישואין, \u0003קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 גם \u0003\"וילדו לו\",\u0004 שהילדים נחשבים ומתייחסים אחריו. \u0003וכל היכא דלא קרינן ביה\u0004 \u0005[ובכל מקום שאין אנו קוראים בו]\u0006 \u0003\"כי תהיינה\"\u0004 — גם \u0003לא קרינן ביה\u0004 \u0005[אין אנו קוראים בו]\u0006 \u0003\"וילדו לו\",\u0004 והילדים מתייחסים אחר אמם.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה דורש, בדין \u0003שפחה נמי\u0004 \u0005[גם כן]\u0006 נלמד מכאן שוולדה כמוה ואין צורך בראיה המיוחדת שהבאנו מן הכתוב \"האשה וילדיה\". ומשיבים: \u0003אין, הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן],\u0006 שמכאן אנו למדים גם את ההלכה שוולד השפחה מתייחס אחריה. ושואלים: \u0003אלא\u0004 הכתוב \u0003\"האשה וילדיה תהיה לאדניה\"\u0004 (שמות כא, ד) \u0003למה לי\u0004? שהרי לפי מה שאמרנו אינו מלמדנו דבר לענין יוחסין! ומשיבים: נחוץ הוא \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006"],["\u0003האומר לשפחתו\u0004 הכנענית שהיתה מעוברת: \u0003\"הרי את בת חורין, וולדך\u0004 יישאר \u0003עבד\"\u0004 — \u0003הולד כמותה,\u0004 שכאשר היא משתחררת — גם הוולד משתחרר, \u0003אלו\u0004 \u0003דברי ר' יוסי הגלילי. וחכמים אומרים: דבריו קיימים, משום שנאמר \"האשה וילדיה תהיה לאדניה\"\u0004 (שמות כא, ד).","ותוהים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד],\u0006 כיצד חכמים למדים מכאן שוולד שפחה משוחררת יכול להיות עבד? \u0003אמר רבא:\u0004 ראיה זו מהפסוק \"האשה וילדיה\" לא לדברי חכמים היא אלא \u0003אדר'\u0004 \u0005[על\u0006 דברי \u0005ר']\u0006 \u0003יוסי הגלילי\u0004 האומר שהוולדות הולכים אחר האם, ולכן אם האם משוחררת — גם הוולדות אינם עבדים.","\u0003ר' טרפון אומר: יכולין ממזרין ליטהר,\u0004 שצאצאיהם לא יהיו ממזרים. \u0003כיצד? ממזר שנשא שפחה\u0004 כנענית, הרי \u0003הולד\u0004 הנולד להם — \u0003עבד,\u0004 אם \u0003שיחררו\u0004 — \u0003נמצא\u0004 אותו \u0003הבן בן חורין,\u0004 ואינו ממזר. \u0003ר' אליעזר אומר:\u0004 אין הדבר מועיל, אלא \u0003הרי זה עבד ממזר.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים: \u0003ר' טרפון לכתחילה קאמר\u0004 \u0005[אומר]\u0006 שלדעתו הממזר יכול לכתחילה לשאת שפחה, \u0003או\u0004 רק ב\u0003דיעבד קאמר\u0004 \u0005[אמר],\u0006 שאם נשא שפחה ונולדו לו בנים, שהם אינם ממזרים, אך לכתחילה אסור לו לשאת שפחה כמו לבן ישראל רגיל? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו \u0003אמרו לו לר' טרפון: טיהרת את\u0004 צאצאי הממזרים \u0003הזכרים\u0004 על ידי כך, \u0003ולא טיהרת את\u0004 צאצאי \u0003הנקיבות\u0004 הממזרות שאף לדבריך אין להם תקנה.","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003לכתחילה קאמר\u0004 \u0005[אמר]\u0006 שמותר לממזר לשאת שפחה, \u0003ממזרת נמי תינסיב לעבדא\u0004 \u0005[גם כן תנשא לעבד]\u0006 ואחר כך ישתחרר הוולד ויהיה כשר! ומשיבים: \u0003עבד אין לו חייס\u0004 \u0005[ייחוס],\u0006 ואף אם היא נשאת לעבד — אין הוולד הולך אחריו אלא הולך אחריה והוא ישראל ממזר כמותה. ועל כל פנים אין מכאן ראיה לבעיה שהעלינו.","ומציעים עוד \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003דאושפזיכניה\u0004 \u0005[שמארחו]\u0006 של \u0003ר' שמלאי ממזר הוה\u0004 \u0005[היה],\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 ר' שמלאי: \u0003אי אקדמתך\u0004 \u0005[אם הייתי מקדים]\u0006 ובא אליך לפני שנשאת אשה וילדה לך ילדים — \u0003טהרתינהו לבנך\u0004 \u0005[הייתי מטהר את בנך],\u0006 שהייתי נותן לך עצה כר' טרפון לשאת שפחה. \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שדברי ר' טרפון הם \u0003לכתחילה\u0004 — \u0003שפיר\u0004 \u0005[יפה],\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שרק אם ב\u0003דיעבד\u0004 אמר שכן הוא, \u0003מאי ניהו\u0004 \u0005[מה הוא]\u0006 הדבר שיכול היה לייעץ לו לעשות?","ומשיבים: \u0003דמנסיב ליה\u0004 \u0005[שהיה נותן לו]\u0006 \u0003עצה ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל\u0004 \u0005[לך]\u0006 \u0003גנוב ואיזדבן\u0004 \u0005[והמכר]\u0006 \u0003בעבד עברי\u0004 ואז תהיה מותר בשפחה, והוולד יהיה עבד. ושואלים: \u0003ובשני\u0004 \u0005[ובשנותיו,\u0006 בימיו\u0005]\u0006 של \u0003ר' שמלאי\u0004 דין \u0003עבד עברי מי הוה\u0004 \u0005[האם היה]\u0006 נוהג? \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003אין עבד עברי נוהג אלא בזמן שהיובל נוהג,\u0004 \u0003ור'\u0004 שמלאי חי שנים רבות לאחר שבטל היובל! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003ר' טרפון לכתחילה קאמר\u0004 \u0005[אומר]\u0006 שיכול ממזר לישא שפחה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא. \u0003אמר רב יהודה אמר שמואל: הלכה כר' טרפון.\u0004 שנינו במשנה ש\u0003ר' אליעזר אומר: הרי זה עבד ממזר. אמר ר' אלעזר: מאי טעמיה\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר\u0004 — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי ממזר \"גם דור עשירי לא יבוא \u0003לו\u0004 בקהל ה'\" (דברים כג, ג), שכוונתו שגם במקרה כזה שוולד שפחה מישראל כשר, הוולד כמותה. וכשהוא ממזר \u0003הלך\u0004 \u0005[לך]\u0006 \u0003אחר פסולו,\u0004 שהוולד נחשב כמוהו.","","\u0003ורבנן\u0004 \u0005[וחכמים],\u0006 כלומר, ר' טרפון, מה הם אומרים: הכתוב \u0003ההוא\u0004 מדבר \u0003בישראל שנשא ממזרת. סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 הלא \u0003\"למשפחתם לבית אבתם\"\u0004 (במדבר ד, ב) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ולכן ילך הוולד אחרי אביו ולא אחרי אמו, \u0003אתא\u0004 \u0005[באה]\u0006 המלה \u0003\"לו\" אפקיה\u0004 \u0005[\u0006ו\u0005הוציאה אותו]\u0006 מכלל יחוס האב, שהוא הולך אחרי אמו הפסולה לענין זה. \u0003ור' אליעזר\u0004 מה הוא אומר על כך: \u0003לאו אף על גב\u0004 \u0005[האם לא אף על פי]\u0006 ש\u0003כתב\u0004 המקרא \u0003\"למשפחתם לבית אבתם\"\u0004 בכל זאת \u0003אתא\u0004 \u0005[באה]\u0006 המלה \u0003\"לו\" אפקיה\u0004 \u0005[\u0006ו\u0005הוציאה אותו],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003אף על גב דכתיב\u0004 \u0005[אף על פי שנאמר]\u0006 \u0003\"האשה וילדיה תהיה לאדניה\"\u0004 (שמות כא, ד) ומכאן למדנו שוולד השפחה כמותה, בכל זאת \u0003אתא\u0004 \u0005[באה]\u0006 המלה \u0003\"לו\" אפקיה\u0004 \u0005[\u0006ו\u0005הוציאה אותו].\u0006 \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים כנגד זה: \u0003כל ולד במעי שפחה כנענית כולד במעי בהמה דמי\u0004 \u0005[נחשב],\u0006 ולכן אין מקום לחשוב שהוולדות ילכו אחר האב.","","","\u0003עשרה\u0004 סוגי \u0003יוחסים עלו\u0004 בעליית עזרא \u0003מבבל,\u0004 כלומר, שחלוקים הם זה מזה לכמה דברים. והם: \u0003כהני\u0004 (כהנים), \u0003לויי\u0004 (לויים), \u0003ישראלי\u0004 (ישראלים), \u0003חללי\u0004 (חללים), \u0003גירי\u0004 (גרים), \u0003וחרורי\u0004 (עבדים משוחררים), \u0003ממזירי\u0004 (ממזרים), \u0003נתיני\u0004 (נתינים), מבני הגבעונים שנימולו בימי יהושע, \u0003שתוקי\u0004 (שתוקים), \u0003ואסופי\u0004 (אסופים).","ומפרטים את דיניהם: \u0003כהני לויי וישראלי\u0004 — \u0003מותרין לבא זה בזה,\u0004 שמותר להם לכתחילה להינשא זה עם זה. \u0003לויי\u0004 (אבל לא כהנים) \u0003ישראלי חללי גירי וחרורי\u0004 (גרים ועבדים משוחררים) — \u0003מותרין לבא זה בזה.\u0004","\u0003גירי וחרורי ממזירי ונתיני\u0004 \u0003שתוקי ואסופי\u0004 — \u0003כולם מותרין לבא זה בזה. ואלו הם: שתוקי\u0004 הוא \u0003כל\u0004 אדם \u0003שהוא מכיר את אמו ואינו מכיר את אביו,\u0004 שאינו יודע מיהו אביו, שנולד לפנויה ולא נתברר מי אביו, \u0003אסופי\u0004 — \u0003כל שנאסף מן השוק, ואינו מכיר לא את אביו ולא\u0004 את \u0003אמו\u0004 והרי הם ספק ממזרים. \u0003אבא שאול היה קורא לשתוקי\u0004 שם אחר: \u0003\"בדוקי\".\u0004 על מה ששנינו במשנה ש\u0003עשרה יוחסין עלו מבבל,\u0004 שואלים: \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 בלשון \u0003\"עלו מבבל\"? ניתני\u0004 \u0005[שישנה]\u0006 \u0003הלכו לארץ ישראל!\u0004 ומדוע חשוב היה לומר מהיכן באו? ומשיבים: \u0003מילתא אגב אורחיה קא משמע לן\u0004 \u0005[דבר\u0006 נוסף ב\u0005דרך אגב השמיע לנו]\u0006 בכך, \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"וקמת ועלית אל המקום אשר יבחר ה' אלהיך\"\u0004 (דברים יז, ח) \u0003מלמד שבית המקדש גבוה מכל ארץ ישראל,\u0004 ולכן מדובר על עליה אל המקדש, \u0003וארץ ישראל גבוה מכל הארצות\u0004 ולכן אומרים שאנשים עולים לארץ ישראל.","","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שאמרנו ש\u0003בית המקדש גבוה מכל ארץ ישראל\u0004 — \u0003היינו דכתיב\u0004 \u0005[הוא שנאמר]\u0006"],["\u0003\"דברי ריבת בשעריך וקמת ועלית\u0004 אל המקום אשר יבחר ה' אלקיך בו\u0003\"\u0004 (דברים יז, ח), משמע שבית המקדש גבוה מכל ערי ישראל (\"שעריך\"), שכן נאמר בו \"ועלית\". \u0003אלא\u0004 ש\u0003ארץ ישראל גבוה מכל ארצות מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לכן הנה ימים באים נאם ה'\u0004 ו\u0003לא יאמרו עוד חי ה' אשר העלה את בני ישראל מארץ מצרים. כי אם חי ה' אשר העלה ואשר הביא את זרע בית ישראל מארץ צפונה ומכל הארצות אשר הדחתים שם\"\u0004 (ירמיה כג, ז–ח), ומשמע מלשון \"אשר העלה\" שארץ ישראל גבוה מכל הארצות.","ושואלים: אם להשמיענו דבר זה \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 במשנתנו \u0003\"עלו מבבל\"? נתני\u0004 \u0005[שישנה]\u0006 \u0003\"עלו לארץ ישראל\"!\u0004 ומתוך כך מסבירים כי סגנון זה של הדברים \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' אלעזר.\u0004 ש\u0003אמר ר' אלעזר: לא עלה עזרא מבבל עד שעשאה כסולת נקיה\u0004 מבחינת יוחסין בני ישראל הגרים בה, שהוציא ממנה את כל הפסולים \u0003ועלה\u0004 עימם לארץ ישראל.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בנושא זה \u0003אביי אמר:\u0004 \u0003\"\u0004עשרה יוחסין \u0003עלו\",\u0004 כלומר, עלו \u0003מאיליהם, תנן\u0004 \u0005[שנינו]\u0006 במשנתנו. \u0003ורבא אמר: \"העלום\" תנן\u0004 \u0005[שנינו],\u0006 כלומר, בעל כרחם. ומעירים: \u0003וקמיפלגי\u0004 \u0005[וחלוקים\u0006 הם\u0005]\u0006 \u0003ב\u0004דברי \u0003ר' אלעזר\u0004 ש\u0003אמר ר' אלעזר: לא עלה עזרא מבבל עד שעשאה כסולת נקיה ועלה.\u0004","\u0003אביי\u0004 — \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את דברי \u0003ר' אלעזר,\u0004 שלדעתו הם לא נלקחו משם אלא עלו מרצונם. ו\u0003רבא\u0004 — \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את דברי \u0003ר' אלעזר. איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003דכולי עלמא אית להו\u0004 \u0005[שלדעת הכל יש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003ר' אלעזר,\u0004 \u0003והכא בהא קא מיפלגי\u0004 \u0005[ו\u0006אולם \u0005כאן ב\u0006ענין \u0005זה\u0006 הם \u0005חלוקים];\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 אביי, \u0005סבור]:\u0006 \u0003אפרושי אפרושינהו ומנפשייהו סליקו\u0004 \u0005[\u0006מתחילה \u0005הפריש\u0006 עזרא \u0005אותם,\u0006 את הפסולים, \u0005ו\u0006הם, הפסולים, \u0005מעצמם עלו]\u0006 אחר כך לארץ ישראל, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבא, \u0005סבור]:\u0006 \u0003בעל כרחייהו אסוקינהו\u0004 \u0005[בעל כרחם העלה אותם].\u0006","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 שלשון המשנה הוא \u0003\"עלו\"\u0004 מעצמם ולא נעשתה הפרדה ברורה בין העולים, \u0003היינו\u0004 \u0005[זהו]\u0006 ש\u0003אמר רב יהודה אמר שמואל: כל ארצות עיסה לארץ ישראל,\u0004 כלומר, שהן נחשבות, מבחינת היוחסין, כתערובת מסופקת לגבי אנשי ארץ ישראל, \u0003וארץ ישראל\u0004 נחשבת \u0003עיסה ל\u0004גבי \u0003בבל. אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003\"העלום\",\u0004 הרי \u0003מידע ידעינהו\u0004 \u0005[יודעים]\u0006 היו והכירו את כל הפסולים ולא נתערבו בהם ומדוע ארץ ישראל עיסה לגבי בבל!? ומשיבים: \u0003נהי דידעי לההוא דרא, לדרא אחריני לא ידעי\u0004 \u0005[אם אמנם יודעים\u0006 היו בפסולי \u0005אותו דור,\u0006 אבל \u0005לדור אחר לא ידעו]\u0006 את יחוסו המדוייק של כל אחד.","ועוד שואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003\"עלו\"\u0004 מאליהם, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 על ידי עזרא \u0003\"ואקבצם אל הנהר הבא על אהוה ונחנה שם ימים שלשה ואבינה בעם ובכהנים ומבני לוי לא מצאתי שם\"\u0004 (עזרא ח, טו), שצריך היה לברר בדיוק מי בתוך העם העולה לארץ.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003\"העלום\", הא מיזהר זהירי\u0004 \u0005[הרי זהירים היו]\u0006 ביוחסין, ומדוע היה צורך בכך? ומשיבים: \u0003נהי דאיזהור\u0004 \u0005[אם אמנם שנזהרו]\u0006 \u0003בפסולים\u0004 לבררם לפני שעלו, \u0003בכשירים לא איזדהור\u0004 \u0005[נזהרו]\u0006 ולא ביררו את יחוסו של כל אחד מהם.","בין היוחסין שעלו מבבל נמנו במשנה \u0003כהני לויי וישראלי\u0004 (כהנים לויים וישראלים). ושואלים: \u0003מנלן דסליקו\u0004 \u0005[מניין לנו שעלו]?\u0006 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וישבו הכהנים והלוים ומן העם והמשררים והשוערים והנתינים בעריהם וכל ישראל בעריהם\"\u0004 (שם ב, ע), הרי נזכרים כאן כהנים, לויים, וכל ישראל.","עוד נמנו במשנה בין היוחסין שעלו מבבל \u0003חללי\u0004 (חללים) \u0003גירי\u0004 (גרים) \u0003וחרורי\u0004 (עבדים משוחררים). ומבררים: \u0003חללי מנלן\u0004 \u0005[חללים מניין לנו]\u0006 שעלו? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: גדולה\u0004 חשיבותה של \u0003חזקה,\u0004 לפי \u0003שנאמר: \"ומבני הכהנים בני חביה בני הקוץ בני ברזלי אשר לקח מבנות ברזלי הגלעדי אשה ויקרא על שמם. אלה בקשו כתבם המתיחשים ולא נמצאו ויגאלו מן הכהנה. ויאמר התרשתא להם אשר לא יאכלו מקדש הקדשים עד עמד כהן לאורים ולתמים\"\u0004 (שם, סא–סג), משמע שהיו גם צאצאי כהנים שהיה ספק אם אמנם כשרים הם לכהונה, או שהם חללים.","\u0003ואמר להם\u0004 עזרא: \u0003הרי אתם בחזקתכם,\u0004 כלומר, על אף שלא הביאו לו הוכחה שהם כהנים כשרים הרי הם נשארים בחזקת מה שהיו מקודם. \u0003במה הייתם אוכלים,\u0004 איזה ממתנות כהונה הייתם אוכלים בהיותכם \u0003בגולה\u0004 — רק \u0003בקדשי הגבול,\u0004 כלומר, בתרומה הנאכלת בכל מקום, \u0003אף כאן\u0004 בארץ ישראל \u0003נמי\u0004 \u0005[גם כן]\u0006, תאכלו רק \u0003בקדשי הגבול\u0004 (תרומה), אבל לא תאכלו במה שנאכל לפנים מחומת ירושלים, כלומר, מן הקרבנות. והוא שאמר להם \"אשר לא יאכלו מקדש הקדשים\".","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 ש\u0003מעלים מתרומה ליוחסין,\u0004 שאם ראינו אדם אוכל תרומה סומכים על כך שהוא כהן גם לענין יוחסין, ומדוע אם כן התיר להם לאכול תרומה? הלא \u0003הני דאכול\u0004 \u0005[אלה שאוכלים]\u0006 \u0003בתרומה אתו לאסוקינהו\u0004 \u0005[יבואו להעלותם]\u0006 לכהונה גמורה! ומשיבים: \u0003שאני התם דריע חזקתייהו\u0004 \u0005[שונה שם שהורעה חזקתם],\u0006 שהרי רואים שאינם אוכלים בקדשי קדשים כשאר כל הכהנים, ומתוך כך יודעים שאינם כהנים ודאיים.","ושואלים: ואם כן \u0003ואלא מאי\u0004 \u0005[מהו]\u0006 שאמר \u0003גדולה חזקה,\u0004 הרי בעצם לא נוסף להם דבר על ידי החזקה? ומשיבים: \u0003דמעיקרא אכול\u0004 \u0005[שמתחילה היו אוכלים]\u0006 \u0003בתרומה\u0004 מפירות בבל, שאינה אלא מ\u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003ולבסוף אכול\u0004 \u0005[אכלו]\u0006 \u0003בתרומה דאורייתא\u0004 \u0005[ש\u0006היא \u0005מן התורה]\u0006 שהפרשת תרומה בארץ ישראל היא חיוב מן התורה, ויש לה קדושה גמורה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם השתא נמי בדרבנן\u0004 \u0005[עכשיו\u0006 בארץ ישראל \u0005גם כן ב\u0006תרומה \u0005שמדברי סופרים]\u0006 — \u0003אכול\u0004 \u0005[אכלו],\u0006 כגון מירקות, \u0003בדאורייתא\u0004 \u0005[\u0006ו\u0005ב\u0006תרומה \u0005ש\u0006היא \u0005מן התורה],\u0006 כגון תרומה על התבואה — \u0003לא אכול\u0004 \u0005[אכלו],\u0006 \u0003וכי מסקינן\u0004 \u0005[וכאשר אנחנו מעלים]\u0006 \u0003מתרומה ליוחסין\u0004 — הרי זה מאכילת תרומה \u0003מדאורייתא\u0004 \u0005[שמן התורה],\u0006 אבל מאכילת תרומה \u0003מדרבנן\u0004 \u0005[שמדברי סופרים]\u0006 \u0003לא מסקינן\u0004 \u0005[אין אנו מעלים]\u0006 אותו, ולכן יכולים לאכול בתרומה מכוח החזקה, ואין חוששים שמא יבואו להעלותם ליוחסין.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר חוזרת השאלה, \u0003מאי\u0004 \u0005[מה]\u0006 הכונה במה שאמרו \u0003גדולה חזקה?\u0004 ומשיבים: \u0003דמעיקרא ליכא למיגזר\u0004 \u0005[שמתחילה לא היה\u0006 מקום \u0005לגזור]\u0006 ולאסור עליהם לאכול תרומה שמדברי סופרים \u0003משום תרומה דאורייתא\u0004 \u0005[שמן התורה]\u0006 שמא יבואו לאכלה שאין תרומה כזו בבבל, ולכן לא הקפידו לתת להם תרומה מדברי סופרים, אבל \u0003לבסוף,\u0004 כשהיו בארץ ישראל, \u0003אף על גב דאיכא למיגזר\u0004 \u0005[אף על פי שיש מקום לגזור]\u0006 ולאסור עליהם לאכול תרומה שמדברי סופרים \u0003משום תרומה דאורייתא\u0004 \u0005[שמן התורה]\u0006 שמא יטעו ויאכלו גם ממנה, בכל זאת משום שגדולה חזקה \u0003בדרבנן\u0004 \u0005[ב\u0006תרומה \u0005מדברי סופרים]\u0006 — \u0003אכול\u0004 \u0005[אכלו],\u0006 \u0003בדאורייתא\u0004 \u0005[\u0006ובתרומה \u0005שמדברי תורה]\u0006 — \u0003לא אכול\u0004 \u0005[אכלו].\u0006","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ויאמר התרשתא להם אשר לא יאכלו מקדש הקדשים\"\u0004 (שם סג). ונדייק: \u0003בקדש הקדשים הוא\u0004 ש\u0003לא יאכל, הא כל מידי ניכול\u0004 \u0005[הרי כל דבר\u0006 אחר שאינו קודש קדשים \u0005יאכלו]\u0006 ואף תרומה שמן התורה!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את דבריו: \u0003לא מידי דמיקרי\u0004 \u0005[דבר שנקרא]\u0006 \u0003קדש, ולא מידי דמיקרי\u0004 \u0005[דבר שנקרא]\u0006 \u0003קדשים.\u0004 ומסבירים: \u0003לא מידי דמיקרי\u0004 \u0005[דבר שנקרא]\u0006 \u0003קדש\u0004 הכוונה לתרומה — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בתרומה: \u0003\"וכל זר לא יאכל קדש\"\u0004 (ויקרא כב, י), \u0003ולא מידי דמיקרי\u0004 \u0005[דבר שנקרא]\u0006 \u0003קדשים,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ובת כהן כי תהיה לאיש זר היא בתרומת הקדשים לא תאכל\"\u0004 (שם, יב), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 מה פירוש בתרומת הקדשים — \u0003במורם מן הקדשים\u0004 שהם חזה ושוק של קרבן השלמים"],["\u0003לא תאכל\".\u0004","שנינו במשנה שעלו מבבל \u0003\"גירי וחרורי\"\u0004 \u0005[גרים ומשוחררים],\u0006 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 \u0003אמר רב חסדא,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 על אכילת הפסח בזמן שיבת ציון: \u0003\"\u0004ויאכלו בני ישראל השבים מהגולה \u0003וכל הנבדל מטמאת גויי הארץ אלהם\"\u0004 (עזרא ו, כא), כלומר, הגרים והמשוחררים שנבדלו מעבודה זרה (\"טומאת גויי הארץ\").","על מה ששנינו במשנה \u0003ממזרי\u0004 (ממזרים), שואלים: \u0003מנלן\u0004 \u0005[מניין]\u0006 שהיו ממזרים בין העולים מבבל? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וישמע סנבלט החרני וטביה העבד העמוני\"\u0004 (נחמיה ב, יט), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 על טוביה העמוני במקום אחר: \u0003\"כי רבים ביהודה בעלי שבועה לו כי חתן הוא לשכניה בן ארח ויהוחנן בנו לקח את בת משלם בן ברכיה\"\u0004 (שם ו, יח). ומסבירים: \u0003קסבר\u0004 \u0005[סבור]\u0006 חכם זה כי \u0003גוי ועבד הבא על בת ישראל\u0004 — \u0003הולד ממזר,\u0004 וכיון שטוביה שהיה עמוני נשא אשה ישראלית, וכן בנו — הרי שהיו שם ממזרים.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 שבמקרה זה \u0003הולד ממזר, אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003הולד כשר\u0004 ומתייחס אחרי אמו, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003ותו\u0004 \u0005[ועוד]\u0006 אפשר לשאול: \u0003ממאי דהוו ליה בני\u0004 \u0005[מניין שהיו לו בנים]\u0006 מאשתו זו ליהוחנן? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לא הוו ליה בני\u0004 \u0005[היו לו בנים],\u0006 ואם כן לא היו ממזרים! \u0003ותו: ממאי דהכא הוו להו וסליקו\u0004 \u0005[ועוד, ממה\u0006 אתה יודע \u0005שכאן\u0006 בבבל \u0005היו,\u0006 נולדו, \u0005להם\u0006 בנים \u0005ועלו]\u0006 לארץ ישראל? \u0003דילמא התם הוו\u0004 \u0005[שמא שם\u0006 בארץ ישראל \u0005היו],\u0006 שהיו מן המשפחות שלא גלו לבבל ואי אפשר להכניסם ברשימת היוחסין שעלו מבבל!","\u0003אלא\u0004 הראיה היא \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"ואלה העולים מתל מלח תל חרשא כרוב אדון ואמר, ולא יכלו להגיד בית אבתם וזרעם אם מישראל הם\"\u0004 (שם ז, סא). ומסבירים שיש לדרוש את השמות הללו כך: \u0003\"תל מלח\"\u0004 — \u0003אלו בני אדם שדומים מעשיהם\u0004 בגילוי עריות \u0003למעשה סדום שנהפכה לתל מלח. \"תל חרשא\"\u0004 — רמז הוא ל\u0003זה שקורא \"אבא\"\u0004 למישהו \u0003ואמו משתקתו\u0004 (\"חרשא\" — מחרישתו), שאינו יודע מי אביו.","\u0003\"ולא יכלו להגיד בית אבתם וזרעם אם מישראל הם\"\u0004 — \u0003זה הוא אסופי שנאסף מן השוק\u0004 שאינו יודע כלל אם הוא מזרע ישראל — שאינו יודע מי הוריו. \u0003\"כרוב אדון ואמר\" אמר ר' אבהו,\u0004 כך יש לדרוש: \u0003אמר אדון,\u0004 הקדוש ברוך הוא: \u0003אני אמרתי יהיו ישראל לפני חשובים ככרוב\u0004 (מלאך) \u0003והם שמו עצמם כנמר\u0004 בעזות מצח. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שדרשה אחרת \u0003אמר ר' אבהו\u0004 — \u0003אמר אדון: אף על פי ששמו עצמם כנמר\u0004 — \u0003הן חשובים לפני ככרוב.\u0004 ומכאן שעלו מבבל גם ממזרים.","על אותו פסוק עצמו \u0003אמר רבה בר בר חנה: כל הנושא אשה שאינה הוגנת לו,\u0004 כלומר, שיש בה פסול יוחסין לגביו — \u0003מעלה עליו הכתוב כאילו חרשו לכל העולם כולו, וזרעו מלח, שנאמר\u0004 על פסולי יוחסין שעלו מבבל: \u0003\"ואלה העולים מתל מלח תל חרשא\".\u0004","\u0003אמר רבה בר רב אדא אמר רב: כל הנושא אשה\u0004 פסולה \u0003לשום\u0004 (לשם) \u0003ממון\u0004 ולא מטעמים אחרים — \u0003הויין\u0004 \u0005[יהיו]\u0006 \u0003לו בנים שאינן מהוגנים, שנאמר: \"בה' בגדו כי בנים זרים ילדו\"\u0004 (הושע ה, ז), כלומר, כשנושא אשה שלא לשם שמים (\"בה' בגדו\").","\u0003ושמא תאמר ממון פלט,\u0004 שלפחות הממון שקיבלו בנדוניה נשאר להם אף שיש להם בנים לא מהוגנים — \u0003תלמוד לומר: \"עתה יאכלם חדש את חלקיהם\"\u0004 (שם), כלומר, את רכושם יאכלו בחודש אחד. \u0003ושמא תאמר חלקו ולא חלקה\u0004 של אשתו — \u0003תלמוד לומר \"חלקיהם\"\u0004 בלשון רבים — שלו ושלה. \u0003ושמא תאמר\u0004 שיקרה הדבר \u0003לזמן מרובה\u0004 ובינתיים ייהנה מן הממון — \u0003תלמוד לומר \"חדש\".\u0004 ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות]\u0006 כיצד מובן הדבר מכתוב זה? \u0003אמר רב נחמן בר יצחק: חדש נכנס וחדש יצא ו\u0004כבר \u0003ממונם אבד.\u0004","\u0003ואמר רבה בר רב אדא ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' סלא אמר רב המנונא: כל הנושא אשה שאינה הוגנת לו אליהו כופתו\u0004 (קושר אותו) כדרך שעושים לחייבי מלקות \u0003והקדוש ברוך הוא\u0004 \u0003רוצעו,\u0004 מכה אותו ברצועה. \u0003ותנא\u0004 \u0005[ושנה]\u0006 החכם: \u0003על כולם אליהו כותב והקדוש ברוך הוא חותם\u0004 דברים אלה: \u0003אוי לו לפוסל את זרעו, ולפוגם את משפחתו, ולנושא אשה שאינה הוגנת לו, אליהו כופתו והקדוש ברוך הוא רוצעו.\u0004","ועוד אמרו: \u0003וכל הפוסל\u0004 אחרים בפגם יוחסין — סימן שהוא עצמו \u0003פסול,\u0004 וסימן יש לו: \u0003ואינו מדבר בשבחא\u0004 \u0005[בשבח]\u0006 אנשים אחרים \u0003לעולם, ואמר שמואל:\u0004 אדם שרגיל לכנות אנשים באיזשהו פסול — \u0003במומו\u0004 שלו \u0003פוסל.\u0004","מסופר: \u0003ההוא גברא\u0004 \u0005[אדם אחד]\u0006 \u0003מנהרדעא דעל לבי מטבחיא\u0004 \u0005[שנכנס לבית המטבחיים]\u0006 \u0003בפומבדיתא. אמר להו\u0004 \u0005[להם]:\u0006 \u0003הבו לי בישרא\u0004 \u0005[תנו לי בשר].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003נטר עד דשקיל לשמעיה\u0004 \u0005[חכה עד שיקח שמשו]\u0006 של \u0003רב יהודה בר יחזקאל וניתי\u0004 \u0003ב לך\u0004 \u0005[ו\u0006אז \u0005ניתן לך].\u0006 כעס אותו איש ו\u0003אמר: מאן\u0004 \u0005[מיהו]\u0006 \u0003יהודה בר שויסקאל\u0004 שכינהו בשם גנאי: גרגרן, \u0003דקדים\u0004 \u0005[שקודם]\u0006 \u0003לי, דשקל מן קמאי\u0004 \u0005[ש\u0006יבוא ו\u0005יקח לפני]?!\u0006 \u0003אזלו אמרו ליה\u0004 \u0005[הלכו אמרו לו]\u0006 \u0003לרב יהודה\u0004 מה שאמר אותו האיש. \u0003שמתיה\u0004 \u0005[נידה אותו],\u0006 כדין המבזה תלמיד חכם. \u0003אמרו\u0004 לו שאותו אדם גם \u0003רגיל דקרי אינשי\u0004 \u0005[שקורא,\u0006 מכנה \u0005לאנשים]\u0006 בלשון גנאי \u0003\"עבדי\"\u0004 \u0005[עבדים].\u0006 \u0003אכריז עליה דעבדא הוא\u0004 \u0005[הכריז עליו שעבד הוא]\u0006 ואסור להתחתן בו.","\u0003אזל ההוא\u0004 \u0005[הלך אותו\u0006 האיש\u0005]\u0006 \u0003אזמניה לדינא לקמיה\u0004 \u0005[הזמין אותו,\u0006 את רב יהודה, \u0005לדין לפני]\u0006 \u0003רב נחמן\u0004 בנהרדעא. \u0003אייתי פיתקא דהזמנא\u0004 \u0005[בא פתק\u0006 כתב \u0005ההזמנה]\u0006 לפומבדיתא. \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב יהודה לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא\u0004 להתייעץ עימו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איזיל\u0004 \u0005[אלך]\u0006 \u0003או לא איזיל\u0004 \u0005[אלך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מיזל לא מיבעי לך למיזל\u0004 \u0005[ללכת אין אתה צריך ללכת]\u0006 \u0003משום דגברא רבה את\u0004 \u0005[שאדם גדול אתה]\u0006 ואינך כפוף לבית דינו של רב נחמן, \u0003אלא משום יקרא דבי נשיאה קום זיל\u0004 \u0005[כבוד בית הנשיא\u0006 שרב נחמן היה חתנו \u0005קום\u0006 ו\u0005לך].\u0006","\u0003אתא\u0004 \u0005[בא]\u0006 רב יהודה לנהרדעא \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 את רב נחמן \u0003דקעביד\u0004 \u0005[שעושה]\u0006 \u0003מעקה. אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה לרב נחמן: \u0003לא סבר לה מר\u0004 \u0005[האם אין אדוני סבור]\u0006 \u0003להא\u0004 \u0005[ל\u0006הלכה \u0005זו]\u0006 ש\u0003אמר רב הונא בר אידי אמר שמואל: כיון שנתמנה אדם פרנס על הצבור אסור בעשיית מלאכה בפני שלשה,\u0004 שלא יזלזל בכבודו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003פורתא דגונדריתא\u0004 \u0005[משהו של מעקה]\u0006 \u0003הוא דקא עבידנא\u0004 \u0005[שאני עושה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003מי סניא\u0004 \u0005[האם שנוא,\u0006 מאוס\u0005]\u0006 לשון \u0003\"מעקה\" דכתיב באורייתא\u0004 \u0005[שכתוב בתורה],\u0006 \u0003או\u0004 לשון \u0003\"מחיצה\" דאמור רבנן\u0004 \u0005[שאומרים חכמים]\u0006 ומדוע אתה משתמש בלשון שאינה לא לשון תורה ולא לשון חכמים?","אחר כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003יתיב מר אקרפיטא\u0004 \u0005[יישב אדוני על הספסל].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ומי סני\u0004 \u0005[האם שנוא,\u0006 מאוס\u0005]\u0006 \u0003ספסל דאמור רבנן\u0004 \u0005[שאומרים חכמים],\u0006 \u0003או איצטבא דאמרי אינשי\u0004 \u0005[שאומרים אנשים\u0006 בדיבור רגיל\u0005]?\u0006 מדוע אתה משתמש במילים בלתי רגילות? אחר כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003ליכול מר אתרונגא\u0004 \u0005[יאכל אדוני אתרוג].\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: כל האומר \"אתרונגא\"\u0004 הרי זה \u0003תילתא ברמות רוחא\u0004 \u0005[שליש של גסות הרוח],\u0006 ומדוע? \u0003או\u0004 שיאמר \u0003\"אתרוג\" כדקריוה רבנן\u0004 \u0005[כפי שקוראים אותו חכמים]\u0006 בלשונם, \u0003או \"אתרוגא\" דאמרי אינשי\u0004 \u0005[\u0006כפי \u0005שאומרים אנשים\u0006 בארמית\u0005]\u0006 אבל כשהוא אומר \"אתרונגא\" אין זה אלא משום גסות הרוח. אחר כך \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לישתי מר אנבגא\u0004 \u0005[ישתה אדוני כוס יין].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי סני\u0004 \u0005[האם מאוס]\u0006 \u0003\"איספרגוס\" דקריוה רבנן\u0004 \u0005[שקוראים אותה רבנן]\u0006 \u0003או \"אנפק\" דאמרי אינשי\u0004 \u0005[שאומרים אנשים]?\u0006","אחר כך \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תיתי\u0004 \u0005[תבוא]\u0006 בתי \u0003דונג תשקינן\u0004 \u0005[\u0006ו\u0005תשקה אותנו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: אין משתמשים באשה\u0004 לשירות שיש בו קירבה, כגון זה. אמר לו רב נחמן: \u0003קטנה היא.\u0004 אמר לו: \u0003בפירוש אמר שמואל: אין משתמשים באשה כלל, בין גדולה בין קטנה.\u0004","אחר כך הציע לו רב נחמן: \u0003נשדר ליה מר שלמא\u0004 \u0005[ישלח אדוני\u0006 דרישת \u0005שלום]\u0006 \u0003ל\u0004אשתי \u0003ילתא. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: קול באשה ערוה,\u0004 ואין לשוחח איתה. אמר לו: \u0003אפשר\u0004 לעשות זאת \u0003על ידי שליח. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל:\u0004"],["\u0003אין שואלין בשלום אשה.\u0004 אמר לו רב נחמן: יש דרך אחרת, שתעשה שליחות זו \u0003על ידי בעלה\u0004 ואין לחשוש עוד! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: אין שואלין בשלום אשה כלל. שלחה ליה\u0004 \u0005[לו]\u0006 לרב נחמן \u0003דביתהו\u0004 \u0005[אשתו]\u0006 שהקשיבה לחילופי הדברים: \u0003שרי ליה תגריה דלא נישוויך\u0004 \u0005[התר,\u0006 גמור, \u0005לו\u0006 את \u0005עניינו שלא יעשה אותך]\u0006 \u0003כשאר עם הארץ,\u0004 שהרי כל דבר שאתה אומר הוא סותר אותו, ומראה מקור לדבריו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003מאי שיאטיה דמר הכא\u0004 \u0005[מה\u0006 טעם \u0005ביקורו של אדוני כאן]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003טסקא דהזמנותא שדר מר אבתראי\u0004 \u0005[טופס הזמנה שלח אדוני אחרי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בהתנצלות: \u0003השתא שותא דמר לא גמירנא\u0004 \u0005[עכשיו\u0006 הרי מתברר שאפילו את \u0005שיחת אדוני לא למדתי],\u0006 שאף בדברי שיחה ששוחחנו אתה מוכיח לי שאיני יודע כמוך, \u0003טסקא דהזמנותא משדרנא למר\u0004 \u0005[טופס הזמנה אשלח לאדוני]?!\u0006 \u0003אפיק דיסקא דהזמנותא מבי חדיה ואחזי ליה\u0004 \u0005[הוציא\u0006 רב יהודה \u0005את טופס ההזמנה מבית חזהו,\u0006 מתוך חיקו, \u0005והראה לו],\u0006 ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא גברא והא דסקא\u0004 \u0005[הרי האיש והרי הטופס].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003הואיל ואתא מר להכא לישתעי מיליה\u0004 \u0005[ובא אדוני לכאן יאמר את דבריו\u0006 באותו ענין\u0005]\u0006 \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא לימרו\u0004 \u0005[יאמרו]\u0006 אנשים \u0003מחנפי רבנן אהדדי\u0004 \u0005[מחניפים חכמים זה לזה]\u0006 ואינם ממצים זה עם זה את הדין.","פתח רב נחמן בדיון, ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא שמתיה מר לההוא גברא\u0004 \u0005[מה טעם החרים אדוני את האיש ההוא]?\u0006 השיב לו: \u0003ציער שליחא דרבנן\u0004 \u0005[שליח של חכמים]\u0006 והיה צריך לעונשו משום שהוא כמבזה תלמיד חכם. אמר לו: אם כן, \u0003ונגדיה מר\u0004 \u0005[וילקנו אדוני],\u0006 שהרי \u0003רב מנגיד על מאן דמצער שלוחא דרבנן\u0004 \u0005[היה מלקה מי שציער שליח חכמים].\u0006 אמר לו רב יהודה: \u0003דעדיף מיניה עבדי ליה\u0004 \u0005[\u0006דבר \u0005שעדיף,\u0006 חמור, \u0005ממנו עשיתי לו\u0006 כקנס\u0005],\u0006 שלדעתו נידוי חמור ממלקות.","שאל עוד רב נחמן: \u0003מאי טעמא אכריז מר עליה דעבדא\u0004 \u0005[מה טעם הכריז אדוני עליו שעבד]\u0006 \u0003הוא? אמר ליה\u0004 \u0005[לו]:\u0006 שהוא \u0003רגיל דקרי אינשי \"עבדי\"\u0004 \u0005[לקרוא\u0006 ל\u0005אנשים עבדים]\u0006 \u0003ותני\u0004 \u0005[ושנה\u0006 החכם\u0005]:\u0006 \u0003כל הפוסל\u0004 — \u0003פסול, ואינו מדבר בשבחא\u0004 \u0005[בשבח]\u0006 \u0003לעולם. ו\u0004כן \u0003אמר שמואל:\u0004 כל הפוסל אחרים — \u0003במומו\u0004 שלו הוא \u0003פוסל.\u0004 אמר לו רב נחמן: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר שמואל\u0004 דבר זה שבמומו פוסל רק בכדי \u0003למיחש ליה\u0004 \u0005[לחשוש לו]\u0006 שהוא פסול, ואולם \u0003לאכרוזי עליה\u0004 \u0005[להכריז עליו]\u0006 בפועל, בפסק הלכה, \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004 וכי אפשר לסמוך על כך?","ומסופר: \u0003אדהכי והכי אתא ההוא בר דיניה מנהרדעי\u0004 \u0005[בין כך וכך בא אותו\u0006 אדם שהיה \u0005בעל דינו מנהרדעא].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא בר דיניה\u0004 \u0005[אותו בעל הדין]\u0006 \u0003לרב יהודה: לדידי קרית לי \"עבדא\"\u0004 \u0005[לי אתה קורא \"עבד\"],\u0006 \u0003דאתינא\u0004 \u0005[שאני בא]\u0006 \u0003מבית חשמונאי מלכא\u0004 \u0005[המלך]?!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: כל דאמר\u0004 \u0005[שאומר]\u0006 \u0003מדבית חשמונאי קאתינא\u0004 \u0005[אני בא]\u0006 — \u0003עבדא\u0004 \u0005[עבד]\u0006 \u0003הוא.\u0004 כי כאשר יבואר, לא נשארו מצאצאיהם אלא עבדים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003לא סבר לה מר\u0004 \u0005[האם אין אדוני סבור]\u0006 \u0003להא\u0004 \u0005[ל\u0006הלכה \u0005זו]\u0006 ש\u0003אמר ר' אבא אמר רב הונא אמר רב: כל תלמיד חכם שמורה הלכה ובא\u0004 באיזה ענין, \u0003אם קודם מעשה\u0004 שהוא עצמו נוגע בו \u0003אמרה\u0004 — \u0003שומעין לו\u0004 באותה הלכה, \u0003ואם לאו\u0004 \u0005[לא],\u0006 שאמר את ההלכה אחר המעשה שאירע — \u0003אין שומעין לו,\u0004 שהרי הוא נוגע בדבר. ואם כן אי אפשר לסמוך על עדותך, שהרי אמרת את ההלכה הזו שאינה ידועה אלא רק לאחר מעשה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה לרב נחמן: \u0003הא איכא\u0004 \u0005[הרי ישנו]\u0006 \u0003רב מתנה דקאי כוותי\u0004 \u0005[שעומד בשיטתי],\u0006 שגם הוא יודע שמועה זו של שמואל.","מסופר: \u0003רב מתנה לא חזייה\u0004 \u0005[ראה אותה],\u0006 את העיר \u0003נהרדעא\u0004 במשך \u0003תליסר שני\u0004 \u0005[שלוש עשרה שנה],\u0006 שלא הזדמן לו לבוא לשם. \u0003ההוא יומא אתא\u0004 \u0005[אותו יום\u0006 בדיוק \u0005בא].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003דכיר מר\u0004 \u0005[\u0006האם \u0005זוכר אדוני]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אמר שמואל כי קאי חדא כרעא אגודא וחדא כרעא במברא\u0004 \u0005[כאשר היה עומד\u0006 ב\u0005רגל אחת על החוף ורגל אחת במעבורת]?\u0006 נזכר רב מתנה ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: כל דאמר\u0004 \u0005[שאומר]\u0006 \u0003מדבית חשמונאי מלכא קאתינא\u0004 \u0005[מבית מלכי חשמונאי אני בא]\u0006 — \u0003עבדא\u0004 \u0005[עבד]\u0006 \u0003הוא,\u0004 משום ש\u0003לא אישתיור מינייהו\u0004 \u0005[נשאר מהם],\u0006 מבית חשמונאי \u0003אלא ההיא רביתא\u0004 \u0005[נערה אחת]\u0006 \u0003דסלקא לאיגרא ורמיא קלא\u0004 \u0005[שעלתה על הגג והרימה קולה]\u0006 \u0003ואמרה:\u0004 מכאן והלאה \u0003כל דאמר\u0004 \u0005[שאומר]\u0006 \u0003מבית חשמונאי אנא\u0004 \u0005[אני]\u0006 — \u0003עבדא\u0004 \u0005[עבד]\u0006 \u0003הוא,\u0004 כי כל שנשאר הוא מצאצאי הורדוס שהיה עבד אדומי.","\u0003נפלה\u0004 הנערה \u0003מאיגרא ומיתה\u0004 \u0005[מן הגג ומתה]\u0006 ולא נשאר מבית חשמונאי אחד שאיננו עבד. כיון שהיה אישור לשמועה זו בשם שמואל, ואותו האיש העיד על עצמו שמבית חשמונאי הוא, \u0003אכרוז עליה\u0004 \u0005[הכריזו עליו]\u0006 גם בנהרדעא \u0003דעבדא\u0004 \u0005[שעבד]\u0006 \u0003הוא.\u0004","ומספ רים: \u0003ההוא יומא אקרען\u0004 \u0005[אותו יום נקרעו]\u0006 \u0003כמה כתובתא\u0004 \u0005[כתובות]\u0006 \u0003בנהרדעא,\u0004 שביטלו כמה אנשים קשרי נישואין, משום שנודע שאותה משפחה היא משפחת עבדים. מסופר: \u0003כי קא נפיק\u0004 \u0005[כאשר יצא]\u0006 רב יהודה, \u0003נפקי אבתריה למירגמיה\u0004 \u0005[יצאו אחריו\u0006 אנשים שנפגעו בדבר ורצו \u0005לרגום אותו],\u0006 שגרם להודיע ברבים שהם פסולים. \u0003אמר להו\u0004 \u0005[להם]\u0006 לאנשי העיר: \u0003אי שתיקו\u0004 \u0005[אם אתם שותקים]\u0006 — \u0003שתיקו\u0004 \u0005[שתקו]\u0006 והניחו לי, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תשתקו — \u0003מגלינא עלייכו הא\u0004 \u0005[אגלה עליכם\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר שמואל: תרתי זרעייתא איכא\u0004 \u0005[שתי משפחות יש]\u0006 \u0003בנהרדעא, חדא מיקריא \"דבי יונה\" וחדא מיקריא \"דבי עורבתי\"\u0004 \u0005[אחת נקראת\u0006 בפי אנשים \u0005\"של בית היונה\" ואחת נקראת \"של בית העורב\"],\u0006 \u0003וסימניך\u0004 \u0005[וסימנך]\u0006 לענין יוחסין: \u0003טמא\u0004 (עורב) — \u0003טמא\u0004 (פסול), \u0003טהור\u0004 (יונה) — \u0003טהור\u0004 (כשר). כיון ששמעו זאת \u0003שדיוה לההוא ריגמא מידייהו\u0004 \u0005[השליכו\u0006 את כל האבנים \u0005הללו\u0006 שבאו \u0005לרגום אותו\u0006 בהם \u0005מידיהם].\u0006 ומסופר שהיו כל כך הרבה אבנים עד \u0003וקם אטמא\u0004 \u0005[נעשה סכר]\u0006 \u0003בנהר מלכא\u0004 מרוב האבנים.","אגב כך מספרים: היה \u0003מכריז רב יהודה בפומבדיתא: אדא ויונתן,\u0004 שהיו אנשים ידועים אז — \u0003עבדי\u0004 \u0005[עבדים]\u0006 הם\u0003,\u0004 \u0003יהודה בר פפא\u0004 — \u0003ממזירא\u0004 \u0005[ממזר]\u0006 הוא, \u0003בטי בר טוביה ברמות רוחא\u0004 \u0005[בגבהות רוחו]\u0006 \u0003לא שקיל גיטא דחירותא\u0004 \u0005[נטל,\u0006 קיבל, \u0005גט\u0006 שטר \u0005שחרור]\u0006 ולפיכך הוא עבד, שעדיין לא נשתחרר. היה \u0003מכריז רבא ב\u0004עירו \u0003מחוזא: בלאי, דנאי, טלאי, מלאי, זגאי,\u0004 כל המשפחות הללו — \u0003כולם לפסול. אמר רב יהודה\u0004 גם כן: \u0003גובאי\u0004 (בני המקום גובא) — הם בעצם \u0003גבעונאי\u0004 (גבעונים) שנשתבש שמם, וכן אנשים שנקראים \u0003דורנוניתא\u0004 — כוונת השם היא \u0003דראי נתינאי\u0004 \u0005[כפר הנתינים]\u0006 ולכן אנשי המקום הם פסולים מלבוא בקהל. \u0003אמר רב יוסף: האי\u0004 \u0005[זה]\u0006 המקום \u0003בי כובי\u0004 שליד \u0003פומבדיתא,\u0004 האנשים הגרים שם \u0003כולם דעבדי\u0004 \u0005[\u0006צאצאים \u0005של עבדים].\u0006","\u0003אמר רב יהודה אמר שמואל: ארבע מאות עבדים, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 \u0003ארבעת אלפים עבדים היו לו ל\u0004כהן \u0003פשחור בן אימר\u0004 שהיה בימי ירמיהו, \u0003וכולם\u0004 מחמת גדולתם \u0003נטמעו בכהונה\u0004 ונחשבים לכהנים. \u0003וכל כהן שיש בו עזות פנים\u0004 דע לך ש\u0003אינו אלא מהם. אמר אביי: כולהו יתבן בשורא\u0004 \u0005[כולם יושבים בשורת\u0006 הכבוד\u0005]\u0006 שבעיר \u0003נהרדעא.\u0004 ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דעת \u0003ר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר: אם ראית כהן בעזות מצח\u0004 — \u0003אל תהרהר אחריו\u0004 שמא הוא פסול, \u0003שנאמר: \"ועמך כמריבי כהן\"\u0004 (הושע ד, ד), משמע שעוד בזמנים ההם ידעו שהכהנים הם בעלי מריבה.","\u0003אמר ר' אבין בר רב אדא אמר רב: כל הנושא אשה שאינה הוגנת לו, כשהקדוש ברוך הוא משרה שכינתו\u0004 על ישראל \u0003מעיד על כל השבטים\u0004 שהם עמו, \u0003ואין מעיד עליו, שנאמר: \"שבטי יה עדות לישראל\"\u0004 (תהלים קכב, ד), \u0003אימתי הוי\u0004 \u0005[מתי הוא]\u0006 \u0003עדות לישראל\u0004 — \u0003בזמן שהשבטים שבטי יה,\u0004 ולא כשהם פסולים.","\u0003אמר ר' חמא בר' חנינא: כשהקדוש ברוך הוא משרה שכינתו\u0004 — \u0003אין משרה אלא על משפחות מיוחסות שבישראל, שנאמר \"בעת ההיא נאם ה' אהיה לאלהים לכל משפחות ישראל\"\u0004 (ירמיה ל, כה), \u0003\"לכל ישראל\" לא נאמר, אלא \"לכל משפחות\",\u0004 כלומר, דווקא המיוחסים, השייכים למשפחות ידועות מישראל.","נאמר בסוף הפסוק \u0003\"והמה יהיו לי לעם\". אמר רבה בר רב הונא: זו מעלה יתירה יש בין ישראל לגרים. דאילו בישראל כתיב בהו\u0004 \u0005[כתוב בהם]\u0006 \u0003\"והייתי להם לאלהים והמה יהיו לי לעם\"\u0004 (יחזקאל לז, כז), \u0003ואילו בגרים כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"מי הוא זה ערב את לבו לגשת אלי נאם ה'. והייתם לי לעם ואנכי אהיה לכם לאלהים\"\u0004 (ירמיה ל, כא–כב), משמע שאין מקרבים אותם מן השמים (\"ואנכי אהיה להם לאלהים\") עד שיתקרבו הם (והייתם לי לעם).","\u0003אמר ר' חלבו: קשים גרים לישראל כספחת,\u0004 וראיה לדבר ממה \u0003שנאמר: \"ונלוה הגר עליהם ונספחו על בית יעקב\"\u0004 (ישעיה יד, א); \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"ונספחו\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בדיני נגעים \"ו \u0003לשאת ולספחת\"\u0004 (ויקרא יד, נו), הרי ששימוש לשון זה מלמד שתוספת הגרים אינה טובה לישראל.","\u0003אמר ר' חמא בר חנינא: כשהקדוש ברוך הוא\u0004"],["\u0003מטהר שבטים,\u0004 כלומר, מברר את יחוסם — את \u0003שבטו של לוי מטהר תחילה, שנאמר: \"וישב מצרף ומטהר כסף וטהר את בני לוי וזקק אתם כזהב וככסף והיו לה' מגישי מנחה בצדקה\"\u0004 (מלאכי ג, ג).","\u0003אמר ר' יהושע בן לוי: כסף מטהר ממזרים,\u0004 שגורם שממזרים עשירים נטמעים בישראל מתוך שאחרים מתחתנים בהם למרות פגם יחוסם, ולעתיד לבא אין הקדוש ברוך הוא מוציאם מכלל ישראל, \u0003שנאמר: \"וישב מצרף ומטהר כסף\",\u0004 שהכסף מטהר אותם. \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 אם כן המשך הפסוק \u0003\"מגישי מנחה בצדקה\"?\u0004 — \u0003אמר ר' יצחק: צדקה\u0004 היא ש\u0003עשה הקדוש ברוך הוא עם ישראל ש\u0004קבע כלל: \u0003משפחה שנטמעה\u0004 — \u0003נטמעה,\u0004 שאף על פי שהיה בה פסול — אין מוציאים אותה מכלל אותו שבט שנטמעה בו.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו קודם, \u0003אמר רב יהודה אמר שמואל: כל\u0004 ה\u0003ארצות\u0004 הן \u0003עיסה\u0004 (תערובת וספק) מבחינת יוחסין בהשוואה \u0003לארץ ישראל, וארץ ישראל עיסה\u0004 היא \u0003לבבל.\u0004 מסופר: \u0003בימי רבי בקשו לעשות בבל עיסה לארץ ישראל\u0004 שתיחשב ארץ ישראל מעולה יותר בייחוסה ושיבדקו בארץ ישראל בייחוסן של משפחות מבבל. \u0003אמר להן\u0004 למציעים: \u0003קוצים אתם משימים לי בין עיני?\u0004 רוצים אתם להעליב אותי? שהרי רבי היה מבני בניו של הלל שהיה בבלי. \u0003רצונכם, יטפל\u0004 (יתחבר, ישב) \u0003עמכם ר' חנינא בר חמא\u0004 והוא יסביר לכם.","\u0003נטפל עמהם ר' חנינא בר חמא, אמ\u0004 \u0003ר להם: כך מקובלני\u0004 (מקובל אני במסורת) \u0003מר' ישמעאל בר' יוסי שאמר משום\u0004 (בשם) \u0003אביו: כל ארצות עיסה לארץ ישראל וארץ ישראל עיסה לבבל.\u0004","ובאותו ענין מסופר עוד: \u0003בימי ר' פנחס בקשו לעשות בבל עיסה לארץ ישראל. אמר להם לעבדיו: כשאני אומר שני דברים בבית המדרש טלוני בעריסה\u0004 (מעין אלונקה) \u0003ורוצו,\u0004 כדי שלא יבואו לעורר מחלוקת עלי בדברים שאומר. \u0003כי עייל\u0004 \u0005[כאשר נכנס]\u0006 לבית המדרש \u0003אמר להם\u0004 לבני הישיבה: \u0003אין שחיטה לעוף מן התורה,\u0004 שמדין תורה אין חובת שחיטה בעופות.","\u0003אדיתבי וקמעייני\u0004 \u0005[עד שישבו ועיינו]\u0006 \u0003בה,\u0004 בהלכה חדשה זו, \u0003אמר להו\u0004 \u0005[להם]\u0006 הלכה אחרת: \u0003כל ארצות עיסה לארץ ישראל, וארץ ישראל עיסה לבבל. נטלוהו\u0004 עבדיו \u0003בעריסה ורצו. רצו אחריו\u0004 בני הישיבה \u0003ולא הגיעוהו\u0004 (השיגוהו). מכל מקום \u0003ישבו ובדקו\u0004 במשפחות כדי לברר אם באמת יש בארץ ישראל פגמי יוחסין \u0003עד שהגיעו ל\u0004בדוק במשפחות ש\u0003סכנה\u0004 היתה לערער על יחוסן, מחמת תקיפותן, \u0003ופירשו\u0004 מן הדבר.","\u0003אמר ר' יוחנן\u0004 בלשון שבועה: \u0003היכלא\u0004 \u0005[היכל]\u0006 (בבית המקדש), \u0003בידינו היא,\u0004 וידוע הוא איזו היא המשפחה הפסולה, \u0003אבל מה אעשה שהרי גדולי הדור נטמעו בה,\u0004 ולכן אינו מגלה את שמה. ומעירים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' יצחק,\u0004 ש\u0003אמר ר' יצחק: משפחה שנטמעה\u0004 — \u0003נטמעה\u0004 ושוב אינה יוצאת מכלל כשרות.","\u0003אמר אביי: אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 מעין זה, שמשפחה שנטמעה — נטמעה. ששנינו: \u0003משפחת בית הצריפה היתה בעבר הירדן וריחקה\u0004 אדם אחד שכינויו \u0003בן ציון, בזרוע\u0004 (בכוח), למרות שלא היה בה פגם יוחסין. \u0003עוד אחרת היתה וקירבה בן ציון בזרוע.\u0004 ומוסיפה הברייתא: \u0003כגון אלו,\u0004 שהן משפחות ידועות — \u0003אליהו בא לטמא\u0004 \u0003ולטהר, לרחק ולקרב\u0004 משפחות. ומעירים: \u0003כגון אלו דידעין\u0004 \u0005[שאנו יודעים]\u0006 מי הן, \u0003אבל משפחה שנטמעה\u0004 ואין יודעים עוד מה היה פגמה — \u0003נטמעה\u0004 כבר, ואפילו אליהו לא יגלה אותה.","\u0003תאנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003עוד\u0004 משפחה \u0003אחרת היתה, ולא רצו חכמים לגלותה\u0004 לכל. \u0003אבל חכמים מוסרים אותו\u0004 את שם המשפחה הזה \u0003לבניהם ולתלמידיהן פעם אחת בשבוע\u0004 (שבע שנים), \u0003ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 \u0003פעמים בשבוע,\u0004 כדי שלא יתחתנו בהם. \u0003אמר רב נחמן בר יצחק: מסתברא כמאן דאמר\u0004 \u0005[\u0006\u0005מסתבר כ\u0006דעת \u0005מי שאומר]\u0006 \u0003פעם אחת בשבוע. כדתניא\u0004 \u0005[כמו ששנויה\u0006 בברייתא\u0005]:\u0006 מי שאומר \u0003\"הריני נזיר אם לא אגלה משפחות\u0004 פסולות שיש בישראל \u0003\"\u0004— \u0003יהיה נזיר, ולא יגלה משפחות\u0004 ומכאן למדים שיש לצמצם גילוי זה ככל האפשר.","מתוך שהוזכר דין זה שיש דברים שמוסרים חכמים בצינעה ולעתים רחוקות, מביאים הלכה דומה. \u0003אמר רבה בר בר חנה, אמר ר' יוחנן:\u0004 דרך הגייתו הנכונה של \u0003שם\u0004 ה' \u0003בן ארבע אותיות חכמים מוסרין אותו לתלמידיהן פעם אחת בשבוע, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003פעמים בשבוע. אמר רב נחמן בר יצחק: מסתברא כמאן דאמר\u0004 \u0005[מסתבר כ\u0006דעת \u0005מי שאומר]\u0006 \u0003פעם אחת בשבוע, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"זה שמי לעלם\"\u0004 (שמות ג, טו), \u0003\"לעלם\" כתיב\u0004 \u0005[כתוב]\u0006 לרמז שהשם צריך להיות נעלם. מסופר: \u0003רבא סבר למידרשיה בפירקא\u0004 \u0005[חשב לדרוש\u0006 ולבאר את דרך קריאת השם \u0005בדרשה\u0006 שדרש בציבור\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא סבא\u0004 \u0005[זקן אחד]:\u0006 \u0003\"לעלם\" כתיב\u0004 \u0005[כתוב],\u0006 ללמד שצריך להעלים אותו.","\u0003ר' אבינא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 מצד אחר \u0003\"זה שמי\",\u0004 משמע שהשם הכתוב הוא שמו של ה', \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"\u0004ו\u0003זה זכרי\"\u0004 (שם), שאין זה שמו ממש אלא דרך לזכרו. ויש לפרש כך, \u0003אמר הקדוש ברוך הוא: לא כ\u0004דרך \u0003שאני נכתב אני נקרא, נכתב אני ביו\"ד ה\"י\u0004 (וא\"ו ה\"י) \u0003ונקרא באל\"ף דל\"ת\u0004 (שם אדנות).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בראשונה, שם\u0004 הקדוש ברוך הוא \u0003בן שתים עשרה אותיות היו מוסרין אותו לכל אדם, משרבו הפריצים\u0004 שהיו משתמשים בו שלא בכבוד הראוי — \u0003היו מוסרים אותו\u0004 רק \u0003לצנועים שבכהונה, והצנועים שבכהונה\u0004 היו אומרים את השם הזה בזמן ברכת כהנים, אבל היו \u0003מבליעים אותו בנעימת אחיהם הכהנים\u0004 כאשר היו שרים, שלא יוודע לרבים. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003אמר ר' טרפון\u0004 שהוא עצמו היה כהן: \u0003פעם אחת עליתי אחר אחי אמי לדוכן, והטיתי אזני אצל כהן גדול ושמעתי שהבליע שם בנעימת אחיו הכהנים.\u0004","\u0003אמר רב יהודה אמר רב: שם בן ארבעים ושתים אותיות אין מוסרין אותו אלא למי שצנוע ועניו, ועומד\u0004 לפחות \u0003בחצי ימיו, ו\u0004דווקא למי ש\u0003אינו כועס, ואינו משתכר, ואינו מעמיד\u0004 (מתעקש) \u0003על מדותיו,\u0004 שמוכן לוותר, שאם לא כן יש לחשוש שמא מתוך כעס או שיכרות ישתמש בשם ויגלה אותו. \u0003וכל היודעו\u0004 את השם הזה, \u0003והזהיר בו והמשמרו בטהרה\u0004 — \u0003אהוב למעלה, ונחמד למטה, ואימתו מוטלת על הבריות, ונוחל שני עולמים העולם הזה והעולם הבא.\u0004","ושוב חוזרים לענין היוחסין. \u0003אמר שמואל משמיה דסבא\u0004 \u0005[משמו של זקן]\u0006 אחד: \u0003בבל בחזקת כשרה עומדת.\u0004 כלומר, משפחה מבבל חזקה שכשרה היא \u0003עד שיודע לך במה נפסלה.\u0004 משפחה שב\u0003שאר ארצות\u0004 — \u0003בחזקת פסול הן עומדות, עד שיודע לך במה נכשרה.\u0004 וב\u0003ארץ ישראל\u0004 מי ש\u0003מוחזק לפסול\u0004 — \u0003פסול, מוחזק לכשר\u0004 — \u0003כשר.\u0004","על דין אחרון זה תוהים: \u0003הא גופא קשיא\u0004 \u0005[הרי זו עצמה קשה]:\u0006 \u0003אמרת\u0004 מצד אחר שמי ש\u0003מוחזק לפסול\u0004 — \u0003פסול,\u0004 ונדייק מכאן: \u0003הא סתמא\u0004 \u0005[הרי\u0006 ב\u0005סתם]\u0006 שאין לו חזקה מבוררת — \u0003כשר\u0004 הוא. \u0003והדר תני\u0004 \u0005[וחזר\u0006 ו\u0005שנה]:\u0006 \u0003מוחזק לכשר\u0004 — \u0003כשר.\u0004 ונדייק: \u0003הא סתמא\u0004 \u0005[הרי\u0006 ב\u0005סתם]\u0006 — \u0003פסול! אמר רב הונא בר תחליפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006"],["כאן — \u0003להשיאו אשה\u0004 מי שאין לו חזקה צריך בדיקה, \u0003כאן\u0004 — \u0003להוציא אשה מידו\u0004 מפני חשש לפסול יוחסין, שבמקרה זה אם אין עליו חזקת פסול — אין מוציאים אותה ממנו.","\u0003אמר רב יוסף: כל שסיחתו בבבל,\u0004 כלומר, שהוא מדבר בלשונם, במבטאם, של אנשי בבל \u0003משיאין לו אשה\u0004 בלי בדיקה, בחזקת שהוא בבלי והמשפחות הבבליות מיוחסות הן. ומעירים: \u0003והאידנא דאיכא רמאי\u0004 \u0005[ובזמן הזה שיש רמאים]\u0006 שמשנים את דרך דיבורם כדי שיחשבו שהם מבבל ומיוחסים הם, \u0003חיישינן\u0004 \u0005[חוששים אנו\u0006 גם לאלה\u0005].\u0006","מסופר: החכם \u0003זעירי\u0004 שהיה בבלי \u0003הוה קא מישתמיט מיניה\u0004 \u0005[היה משתמט ממנו]\u0006 מ\u0003ר' יוחנן\u0004 כדי לא לפגוש אותו, \u0003דהוה אמר ליה\u0004 \u0005[שהיה אומר לו]\u0006 ר' יוחנן לזעירי: \u0003נסיב ברתי\u0004 \u0005[שא\u0006 את \u0005בתי].\u0006 \u0003יומא חד הוו קאזלי באורחא\u0004 \u0005[יום אחד הלכו בדרך],\u0006 \u0003מטו לעורקמא דמיא\u0004 \u0005[הגיעו לשלולית מים],\u0006 \u0003ארכביה\u0004 \u0005[הרכיבו]\u0006 את \u0003ר' יוחנן אכתפיה וקא מעבר ליה\u0004 \u0005[על כתפו והעבירו],\u0006 שהיה מכבדו כל כך ומשמשו בגופו. אמר \u0003ליה\u0004 \u0005[לו]\u0006 אז ר' יוחנן: \u0003אורייתן\u0004 \u0005[תורתינו]\u0006 \u0003כשרה\u0004 ונחשבת בעיניך עד כדי כך, \u0003בנתין לא כשרן\u0004 \u0005[\u0006ו\u0005בנותינו אינן כשירות]?\u0006 \u0003מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 שאתה חושש לשאת את בתי —","\u0003אילימא מדתנן\u0004 \u0005[אם תאמר ממה ששנינו]:\u0006 \u0003עשרה יוחסין עלו מבבל כהני לויי\u0004 (כהנים ולויים) וכו' ואתה חושש גם לממזרים שיש ביניהם, \u0003אטו כהני לויי וישראלי כולהו סליקו\u0004 \u0005[וכי הכהנים הלויים והישראלים כולם עלו]?\u0006 אלא \u0003כי היכי דאישתיור מהני אישתיור נמי מהני\u0004 \u0005[כמו שנשתיירו מאלה,\u0006 מהכהנים והלויים הכשרים בבבל, \u0005נשתיירו גם כן מאלה,\u0006 מהפסולים\u0005]\u0006 ואם כן עצם העובדה שאתה מבבל אינה אומרת שכשר אתה יותר. ומעירים: \u0003אישתמיטתיה\u0004 \u0005[נשמט ממנו,\u0006 שכח\u0005]\u0006 ר' יוחנן, \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' אלעזר: לא עלה עזרא מבבל עד שעשאה כסולת נקייה ועלה\u0004 לארץ ישראל, ואלה שנשארו שם מיוחסים הם.","מסופר: \u0003עולא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לפומבדיתא לבי\u0004 \u0005[לביתו]\u0006 של \u0003רב יהודה, חזייה\u0004 \u0005[ראה אותו]\u0006 את \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה דגדל ולא נסיב\u0004 \u0005[שהוא מבוגר ואינו נשוי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא לרב יהודה: \u0003מאי טעמא לא קא מנסיב ליה מר איתתא לבריה\u0004 \u0005[מה טעם אין אדוני משיא אשה לבנו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי ידענא מהיכא אנסיב\u0004 \u0005[האם יודע אני מהיכן\u0006 אוכל \u0005להשיאו\u0006 אשה\u0005]?\u0006 שאני חושש לפגם יוחסין. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אטו אנן מי ידעינן מהיכא קאתינן\u0004 \u0005[וכי יודעים אנו\u0006 עצמנו \u0005מהיכן אנו באים]\u0006 ואם אין בנו פסול? \u0003דילמא מהנך דכתיב\u0004 \u0005[שמא\u0006 אנו \u0005מאלה שנאמר]\u0006 בהם \u0003\"נשים בציון ענו בתלת בערי יהודה\"\u0004 (איכה ה, יא), ואנו מבני הנשים שנבעלו על ידי הגוים.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאינך חושש לבני הנשים הללו שאתה סבור ש\u0003גוי ועבד הבא על בת ישראל הולד כשר, ודילמא\u0004 \u0005[ושמא]\u0006 מוצאנו \u0003מהנך דכתיב בהו\u0004 \u0005[מאלה שנאמר בהם]\u0006 \u0003\"השכבים על מטות שן וסרחים על ערשותם\"\u0004 (עמוס ו, ד). \u0003ואמר ר' יוסי בר' חנינא:\u0004 מה עניינם — \u0003אלו בני אדם המשתינים מים בפני מטותיהם ערומים.\u0004","\u0003ו\u0004היה \u0003מגדף\u0004 (מזלזל) \u0003בה ר' אבהו\u0004 באימרה זו, שהיה אומר: \u0003אי הכי היינו דכתיב\u0004 \u0005[אם כך\u0006 שזהו חטאם, \u0005זה שנאמר]\u0006 \u0003\"לכן עתה יגלו בראש גולים\"\u0004 (שם, ז), \u0003משום\u0004 ש\u0003משתינים מים בפני מטותיהם ערומים \"יגלו בראש גולים\"?!\u0004 אף שהדבר אינו נאה, אבל אינו חטא חמור כל כך.","\u0003אלא אמר ר' אבהו: אלו בני אדם שאוכלין ושותין זה עם זה, ומדביקין מטותיהם זו בזו, ומחליפין נשותיהם זה לזה, ומסריחים ערסותם\u0004 (מטותיהם) \u0003בשכבת זרע שאינה שלהם.\u0004 ואם כן יש בתוך ישראל בניהם של אלה, שהם ממזרים גמורים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 לעולא: אם כן \u0003היכי נעביד\u0004 \u0005[איך נעשה],\u0006 כיצד בכל זאת אפשר לברר מה היא משפחה כשירה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל בתר שתיקותא\u0004 \u0005[לך אחר השתיקה],\u0006 \u0003כי האי דבדקי בני מערבא\u0004 \u0005[כמו שבודקים בני ארץ ישראל]:\u0006 \u0003כי מינצו בי תרי בהדי הדדי\u0004 \u0005[כאשר מתקוטטים שנים זה עם זה]\u0006 \u0003חזו הי מנייהו דקדים ושתיק\u0004 \u0005[רואים איזה מהם שמקדים ושותק]\u0006 — \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003האי\u0004 \u0005[זה\u0006 ששותק קודם\u0005]\u0006 \u0003מיוחס טפי\u0004 \u0005[יותר].\u0006","\u0003אמר רב: שתיקותיה\u0004 \u0005[שתיקתה]\u0006 של \u0003בבל היינו יחוסא\u0004 \u0005[הוא ייחוסה],\u0006 כלומר, גם בבבל אפשר בדרך זו לדעת מהו ייחוסו של אדם. ומקשים: \u0003איני\u0004 \u0005[האם כן הוא]?\u0006 \u0003והא איקלע\u0004 \u0005[והרי הזדמן]\u0006 \u0003רב לבי בר שפי חלא\u0004 \u0005[לביתו\u0006 של \u0005בן מסנן היין]\u0006 \u0003ובדק בהו\u0004 \u0005[אותם],\u0006 \u0003מאי לאו ביחסותא\u0004 \u0005[האם לא בייחוסם]\u0006 בדק? ומשיבים: \u0003לא, בשתיקותא\u0004 \u0005[בשתיקתם]\u0006 בדק. \u0003הכי קאמר להו\u0004 \u0005[כך אמר להם]:\u0006 \u0003בדוקו אי שתקי אי לא שתקי\u0004 \u0005[בידקו אם\u0006 הם \u0005שותקים או לא שותקים].\u0006","\u0003אמר רב יהודה אמר רב: אם ראית שני בני אדם שמתגרים זה בזה\u0004 — \u0003שמץ פסול יש באחד מהן,\u0004 כלומר, צד של פסול יש באחד מהם מצד ייחוסו, \u0003ו\u0004משום כך \u0003אין מניחין אותו\u0004 מן השמים \u0003לידבק אחד בחבירו\u0004 בחיתון ולכן הם באים לידי קטטה בענין אחר. \u0003אמר ר' יהושע בן לוי: אם ראית שתי משפחות המתגרות זו בזו\u0004 — \u0003שמץ פסול יש באחת מהן, ואין מניחין אותה\u0004 מן השמים \u0003לידבק בחברתה.\u0004","\u0003אמר רב פפא סבא\u0004 \u0005[הזקן]\u0006 (להבדיל מרב פפא סתם) \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: בבל\u0004 מבחינת יוחסין — \u0003בריאה,\u0004 מיוחסת ונקיה מפסולים. \u0003מישון\u0004 — \u0003מיתה,\u0004 שכולם פסולים בה. \u0003מדי\u0004 — \u0003חולה,\u0004 שרובם כשרים וחלקם פסולים. \u0003עילם\u0004 — \u0003גוססת,\u0004 שרובם פסולים. ומסבירים: \u0003ומה בין חולין לגוססין?\u0004 — \u0003רוב חולין\u0004 הם \u0003לחיים, רוב גוססים\u0004 הם \u0003למיתה.\u0004","ושואלים: \u0003עד היכן היא\u0004 רוחבה של \u0003בבל\u0004 לענין יוחסין? \u0003רב אמר: עד נהר עזק\u0004 הנשפך לפרת, \u0003ושמואל אמר: עד נהר יואני\u0004 הנשפך לפרת. ושואלים: \u0003לעיל בדיגלת\u0004 \u0005[למעלה\u0006 בצפון \u0005ב\u0006נהר \u0005חידקל]\u0006 \u0003עד היכא\u0004 \u0005[היכן]\u0006 גבול בבל? \u0003רב אמר: עד\u0004 המקומות \u0003בגדא ואוונא. ושמואל אמר: עד מושכני.\u0004 ושואלים: \u0003ו\u0004לשיטתו האם \u0003לא מושכני בכלל\u0004 בבל? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חייא בר אבא אמר שמואל: מושכני הרי היא כגולה,\u0004 כלומר, כפומבדיתא שהיא עיקר בבל \u0003ל\u0004ענין \u0003יוחסין! אלא\u0004 הכוונה היא: \u0003עד מושכני, ומושכני בכלל.\u0004","ושואלים: \u0003לתחתית בדיגלת\u0004 \u0005[למטה,\u0006 בדרום, \u0005ב\u0006נהר \u0005חידקל]\u0006 \u0003עד היכא\u0004 \u0005[היכן]\u0006 גבול בבל? \u0003אמר רב שמואל: עד\u0004 העיר \u0003אפמייא תתאה\u0004 \u0005[התחתונה].\u0006 ומעירים: \u0003תרתי\u0004 \u0005[שתי]\u0006 ערים בשם \u0003אפמייא הויין\u0004 \u0005[הן]:\u0006 \u0003חדא עיליתא וחדא תתייתא\u0004 \u0005[אחת עליונה ואחת תחתונה],\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003כשירה וחדא\u0004 \u0005[ואחת]\u0006 \u0003פסולה, ובין חדא לחדא\u0004 \u0005[ובין אחת לאחת]\u0006 מרחק \u0003פרסה, וקא קפדי אהדדי ואפילו נורא לא מושלי אהדדי\u0004 \u0005[ומקפידים אלה על אלה\u0006 ומתרחקים זה מזה \u0005ואפילו אש אינם משאילים זה לזה]\u0006 כדי שלא יבואו לידי קירבה. \u0003וסימניך דפסולתא הא דמישתעיא מישנית\u0004 \u0005[וסימנה של\u0006 הפסולה הוא \u0005זו שמדברת\u0006 בניב של \u0005מישן],\u0006 שכבר אמרנו שמישן היא מתה לענין יוחסין.","ושואלים: \u0003לעיל\u0004 \u0005[למעלה]\u0006 \u0003בפרת עד היכא\u0004 \u0005[היכן]\u0006 גבול בבל? \u0003רב אמר: עד אקרא\u0004 \u0005[מבצר]\u0006 של המקום \u0003תולבקני. ושמואל אמר: עד גישרא דבי פרת\u0004 \u0005[הגשר שעל הפרת].\u0006 \u0003ור' יוחנן אמר: עד מעברת\u0004 \u0005[המעבורת]\u0006 שבמקום \u0003גיזמא.\u0004 ומספרים: \u0003לייט\u0004 \u0005[קילל]\u0006 \u0003אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב יוסף אדרב\u0004 \u0005[\u0006על הנוהג כדברי \u0005רב].\u0006","ותוהים: \u0003אדרב לייט, אדשמואל לא לייט\u0004 \u0005[על דברי רב קילל, על דברי שמואל לא קילל]?\u0006 והרי הגשר שעל הפרת הוא למעלה, צפונה יותר מאשר אקרא דתולבקני! \u0003אלא לייט\u0004 \u0005[קילל]\u0006 על המורה כדברי \u0003רב, וכל שכן\u0004 על המורה כדברי \u0003שמואל. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם אדרב לייט, אדשמואל לא לייט\u0004 \u0005[על\u0006 דברי \u0005רב קילל, על\u0006 דברי \u0005שמואל לא קילל],\u0006 \u0003וגישרא דבי פרת, לתתאיה הוה קאי\u0004 \u0005[והגשר שעל הפרת, למטה\u0006 יותר \u0005היה עומד],\u0006 שבזמנם היה הגשר דרומה לאקרא דתולבקני וודאי הוא בתחום בבל."],["\u0003והאידנא הוא דליוה פרסאי\u0004 \u0005[ועכשיו הוא\u0006 ש\u0005העלוהו הפרסים]\u0006 והעמידו גשר צפונה יותר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: להא גיסא\u0004 \u0005[לצד זה]\u0006 של \u0003פרת עד היכא\u0004 \u0005[היכן],\u0006 כלומר, לצד מערב של הפרת עד היכן גבול בבל? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי דעתיך\u0004 \u0005[דעתך],\u0006 משום מה אתה שואל? — \u0003משום\u0004 העיר \u0003בירם,\u0004 הלא \u0003מייחסי\u0004 \u0005[מיוחסי]\u0006 העיר \u0003פומבדיתא מבירם נסבי\u0004 \u0005[\u0006הם \u0005נושאים]\u0006 להם נשים, הרי שאנשי בירם בחזקת כשרים.","\u0003אמר רב פפא: כמחלוקת\u0004 זו בין רב ושמואל \u0003ל\u0004ענין \u0003יוחסין\u0004 של בבל, \u0003כך מחלוקת לענין גיטין,\u0004 האם מקומות אלה נחשבים כמדינת הים ששליח הגט הבא משם צריך לומר \"בפני נכתב ובפני נחתם\". \u0003ורב יוסף אמר: מחלוקת\u0004 זו היא \u0003ליוחסין, אבל לגיטין דברי הכל\u0004 דינה של בבל הוא \u0003עד ארבא תניינא דגישרא\u0004 \u0005[האגם השני של הגשר].\u0006","\u0003אמר רמי בר אבא:\u0004 מחוז \u0003חביל ימא\u0004 — \u0003תכילתא\u0004 \u0005[תכלתה,\u0006 פארה\u0005]\u0006 של \u0003בבל\u0004 מבחינת יוחסין. המקומות \u0003שוניא וגוביא\u0004 הם \u0003תכילתא\u0004 \u0005[תכלתו,\u0006 יופיו\u0005]\u0006 של \u0003חביל ימא. רבינא אמר: אף\u0004 המקום \u0003ציצורא\u0004 בכלל אלה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003חנן בן פנחס אומר: חביל ימא תכילתא\u0004 \u0005[תכלת]\u0006 של \u0003בבל, שוניא וגוביא וציצורא\u0004 — \u0003תכילתא\u0004 \u0005[תכלת]\u0006 של \u0003חביל ימא. אמר רב פפא: והאידנא\u0004 \u0005[ועכשיו,\u0006 בימינו\u0005]\u0006 — \u0003איערבי בהו כותאי\u0004 \u0005[התערבו בהם כותיים\u0006 (שומרונים)\u0005].\u0006 ומעירים: \u0003ולא היא,\u0004 אין הדבר נכון, אלא \u0003איתתא\u0004 \u0005[אשה]\u0006 \u0003הוא דבעא מינייהו\u0004 \u0005[שביקש\u0006 כותי אחד \u0005מהם]\u0006 \u0003ולא יהבו ליה\u0004 \u0005[נתנו לו]\u0006 ומשום כך יצא קול שהכותים התערבו באנשי מקום זה. ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 האיזור הזה שקראו לו \u0003חביל ימא? אמר רב פפא: זו\u0004 איזור הסמוך ל\u0003פרת\u0004 שליד","\u0003בורסי. ההוא גברא\u0004 \u0005[אדם אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לחכמים: \u0003אנא\u0004 \u0005[אני]\u0006 \u0003מן\u0004 המקום הנקרא \u0003שוט מישוט. עמד ר' יצחק נפחא על רגליו ואמר: שוט מישוט בין הנהרות עומדת.\u0004 ושואלים: \u0003וכי\u0004 (ואם) \u0003בין הנהרות עומדת, מאי הוי\u0004 \u0005[מה היה]\u0006 מה חשוב הדבר להלכה? \u0003אמר אביי, אמר ר' חמא בר עוקבא, אמר ר' יוסי בר' חנינא:\u0004 ארץ \u0003בין הנהרות הרי היא כגולה\u0004 (פומבדיתא) \u0003ליוחסין.\u0004 ושואלים: \u0003והיכא קיימא\u0004 \u0005[והיכן מצוי]\u0006 הוא תחום בין הנהרות לענין זה? \u0003אמר ר' יוחנן: מ\u0004המקום \u0003איהי דקירא ולעיל\u0004 \u0005[ולמעלה]\u0006 לצפון. ושואלים, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן: עד מעברתא\u0004 \u0005[המעבורת]\u0006 שבמקום \u0003גיזמא\u0004 ולא יותר! \u0003אמר אביי: רצועה נפקא\u0004 \u0005[יוצאת]\u0006 מהאיזור המיוחד עד מעבר לאיהי דקירא.","\u0003אמר רב איקא בר אבין אמר רב חננאל אמר רב: חלזון ניהוונד הרי היא כגולה ל\u0004ענין \u0003יוחסין. אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי: לא תציתו ליה\u0004 \u0005[אל תקשיבו לו],\u0006 אל תקבלו את דבריו לענין זה, \u0003יבמה היא\u0004 ש\u0003נפלה ליה התם\u0004 \u0005[לפניו משם]\u0006 ממקום זה, והוא רוצה לשאת אותה, ולכן הוא אומר שהם מיוחסים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אטו דידי\u0004 \u0005[וכי\u0006 הלכה זו \u0005שלי]\u0006 \u0003היא?\u0004 הלא של \u0003רב חננאל היא! אזיל שיילוה\u0004 \u0005[הלכו שאלוהו]\u0006 \u0003לרב חננאל, אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב:\u0004 \u0003חלזון ניהוונד הרי היא כגולה ל\u0004ענין \u0003יוחסין.\u0004","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 שמועה זו על מה שאמר \u0003ר' אבא בר כהנא.\u0004 ש\u0003אמר ר' אבא בר כהנא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"וינחם בחלח ובחבור נהר גוזן וערי מדי\"\u0004 (מלכים ב יח, יא) \u0003חלח\u0004 — \u0003זו חלזון, חבור\u0004 — \u0003זו הדייב, נהר גוזן\u0004 — \u0003זו גינזק, ערי מדי\u0004 — \u0003זו חמדן וחברותיה, ואמרי\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 \u0003לה: זו נהוונד וחברותיה.\u0004 ועשרת השבטים נתערבו בגויים, ולכן אין ייחוסם של הישראלים שם ברור.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הן \u0003חברותיה\u0004 של נהוונד? \u0003אמר שמואל: כרך מושכי חוסקי ורומקי. אמר ר' יוחנן: וכולם לפסול,\u0004 לכולם יש אותו פסול יוחסין. \u0003קסלקא דעתא\u0004 \u0005[עלה על הדעת]\u0006 לומר ש\u0003מושכי היינו\u0004 \u0005[זו היא]\u0006 \u0003מושכני.\u0004 ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חייא בר אבין אמר שמואל: מושכני הרי היא כגולה,\u0004 כפומבדיתא, \u0003ל\u0004ענין \u0003יוחסין! אלא\u0004 צריך לומר ש\u0003מושכי\u0004 מקום \u0003לחוד, ומושכני\u0004 מקום \u0003לחוד.\u0004","אגב הזכרת מקומות אלה, הביאו מה שפירשו על הכתוב \u0003\"ותלת עלעין בפמה בין שנה\"\u0004 \u0005[ושלוש צלעות בפיה בין שיניה]\u0006 (דניאל ז, ה). \u0003אמר ר' יוחנן: זו חלזון, הדייב ונציבין, שפעמים בולעתן\u0004 (מושלת בהם) מלכות פרס \u0003ופעמים פולטתן.\u0004 שעברו מקומות אלו מידי הפרסיים לידי הרומיים ושבו אליהם כמה פעמים.","ועל אותה חיה שנאמר שם \u0003\"וארו חיוה אחרי תנינה דמיה לדב\"\u0004 (שם ה) \u0005[והנה חיה אחרת שניה דומה לדוב],\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: אלו פרסיים שאוכלין ושותין\u0004 הרבה \u0003כדוב, ומסורבלין\u0004 (שמנים) \u0003כדוב, ומגדלין שער כדוב, ואין להם מנוחה כדוב,\u0004 שהוא כל הזמן נודד ממקום למקום. \u0003ר' אמי כי הוה חזי פרסא דרכיב\u0004 \u0005[כשהיה רואה פרסי רוכב],\u0006 \u0003אמר: היינו דובא ניידא\u0004 \u0005[זהו דוב נודד].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי ללוי: הראני פרסיים,\u0004 כלומר, תן לי תיאור קצר כיצד נראים הפרסיים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דומים לחיילות של בית דוד. הראני חברין\u0004 (כהני הפרסים). אמר לו: \u0003דומין למלאכי חבלה. הראני ישמעאלים.\u0004 אמר לו: \u0003דומין לשעירים\u0004 (שדים) \u0003של בית הכסא. הראני תלמידי חכמים שבבבל.\u0004 אמר לו: \u0003דומים למלאכי השרת.\u0004","\u0003כי הוה ניחא נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רבי, אמר\u0004 בדרך נבואה: מקום ששמו \u0003הומניא איכא\u0004 \u0005[יש]\u0006 \u0003בבבל\u0004 — \u0003כולה עמונאי\u0004 (מבני עמון) \u0003היא.\u0004 מקום ששמו \u0003מסגריא איכא\u0004 \u0005[יש]\u0006 \u0003בבבל\u0004 — \u0003כולה דממזירא\u0004 \u0005[של ממזרים]\u0006 \u0003היא.\u0004 מקום ששמו \u0003בירקא איכא\u0004 \u0005[יש]\u0006 \u0003בבבל\u0004 — \u0003שני אחים יש\u0004 שם \u0003שמחליפים נשותיהם זה לזה,\u0004 וממילא בניהם ממזרים. מקום ששמו \u0003בירתא דסטיא איכא\u0004 \u0005[יש]\u0006 \u0003בבבל\u0004 — \u0003היום סרו\u0004 (\"סטיא\") \u0003מאחרי המקום.\u0004 ומה היה הדבר — \u0003דאקפי פירא בכוורי בשבתא ואזיל וצדו בהו בשבתא\u0004 \u0005[שהקיפו מקום שהיו בו דגים בשבת והלכו וצדו בהם\u0006 את הדגים \u0005בשבת],\u0006 \u0003ושמתינהו\u0004 \u0005[ונידה אותם]\u0006 \u0003ר' אחי בר' יאשיה, ואישתמוד\u0004 \u0005[והשתמדו]\u0006 כולם. מקום שנקרא \u0003אקרא דאגמא איכא\u0004 \u0005[יש]\u0006 \u0003בבבל\u0004 — \u0003אדא בר אהבה יש בה,\u0004"],["\u0003היום יושב בחיקו של אברהם\u0004 אבינו, שהיום הוא נימול. \u0003היום נולד רב יהודה בבבל.\u0004","ומעירים: ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כשמת ר' עקיבא נולד רבי. כשמת רבי נולד רב יהודה. כשמת רב יהודה נולד רבא. כשמת רבא נולד רב אשי. ללמדך שאין צדיק נפטר מן העולם עד שנברא צדיק כמותו, שנאמר: \"וזרח השמש ובא השמש\"\u0004 (קהלת א, ה). וכך היה גם בדורות ראשונים: \u0003עד שלא כבתה שמשו של עלי זרחה\u0004 כבר \u0003שמשו של שמואל הרמתי, שנאמר: \"ונר אלהים טרם יכבה ושמואל שכב\" וגו'\u0004 (שמואל א ג, ג), ששרתה נבואה עליו בימי עלי.","ואגב שהזכרנו את העיר הומניא כעיר של עמונים, מביאים על הכתוב \u0003\"צוה ה' ליעקב סביביו צריו\"\u0004 (איכה א, יז), כלומר, שגם בגלות סובבים את ישראל אויביהם. \u0003רב יהודה אמר: כגון\u0004 העיר \u0003הומניא\u0004 שהיא עיר של עמונים הסמוכה \u0003ל\u0004ישוב היהודי של \u0003פום נהרא.\u0004","נאמר: \u0003\"ויהי כהנבאי ופלטיהו בן בניה מת ואפל על פני ואזעק קול גדול ואמר אהה אדני אלהים'\"\u0004 (יחזקאל יא, יג) \u0003רב ושמואל\u0004 נחלקו בפירוש מקרא זה: \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר,\u0004 פירש את הדבר, \u0003לטובה, וחד אמר: לרעה.\u0004 כיצד? \u0003מאן דאמר\u0004 \u0005[מי שאומר,\u0006 שמפרש אותה\u0005]\u0006 \u0003לטובה\u0004 — \u0003כי הא דאיסתנדרא\u0004 \u0005[כמו\u0006 סיפור \u0005זה שמושל]\u0006 מחוז \u0003מישן חתניה\u0004 \u0005[חתנו]\u0006 של \u0003נבוכדנצר הוה\u0004 \u0005[היה].\u0006 \u0003שלח ליה\u0004 \u0005[לו]\u0006 לנבוכדנצר: \u0003מכולי האי שבייה דאייתית\u0004 \u0005[מכל אותם השבויים שהבאתי]\u0006 \u0003לך\u0004 ממלחמותיך \u0003לא שדרת לן דקאי לקמן\u0004 \u0005[שלחת לנו\u0006 מישהו \u0005שיעמוד לפנינו].\u0006","\u0003בעי לשדורי ליה\u0004 \u0005[רצה לשלוח לו\u0006 שבויים\u0005]\u0006 \u0003מישראל\u0004 שיהיו משרתיו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003פלטיהו בן בניהו\u0004 לנבוכדנצר: \u0003אנן דחשבינן ניקו מקמך הכא\u0004 \u0005[אנו, שאנו חשובים, נעמוד\u0006 ונשרת \u0005לפניך כאן],\u0006 \u0003ועבדין ניזלו להתם\u0004 \u0005[ועבדינו ילכו לשם]\u0006 לחתנך. וכך עשה נבוכדנצר. \u0003ו\u0004עליו \u0003אמר\u0004 ה\u0003נביא\u0004 יחזקאל: \u0003מי שעשה טובה\u0004 זו \u0003בישראל\u0004 שמנע מהם גלות זו, \u0003ימות בחצי ימיו?\u0004","\u0003מאן דאמר\u0004 \u0005[מי שאומר,\u0006 מפרש, את הפסוק\u0005]\u0006 \u0003לרעה, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"\u0004ותשא אותי רוח \u0003ותבא אתי אל שער בית ה' הקדמוני הפונה קדימה והנה בפתח השער עשרים וחמשה איש ואראה בתוכם את יאזניה בן עזר ואת פלטיהו בן בניהו שרי העם\"\u0004 (שם א), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויבא אתי אל חצר בית ה' הפנימית והנה פתח היכל ה' בין האולם ובין המזבח כעשרים וחמשה איש אחוריהם אל היכל ה' ופניהם קדמה\"\u0004 (שם ח, טז).","\u0003ממשמע שנאמר \"ופניהם קדמה\" איני יודע שאחוריהם כלפי מערב?\u0004 שהרי באותו צד נמצא היכל ה'. אלא \u0003מה תלמוד לומר \"אחריהם אל היכל ה'\"\u0004 — לרמוז דבר נוסף, \u0003מלמד שהיו מפריעין\u0004 (פורעים, מגלים את) \u0003עצמם\u0004 באחוריהם \u0003ומתריזין עצמם\u0004 (מטילים צואה) \u0003כלפי מעלה\u0004 דווקא בכיוון של היכל ה'. \u0003וקאמר\u0004 \u0005[ואמר]\u0006 \u0003נביא: מי שעשה הרעה הזאת בישראל ימות על מיטתו\u0004 בשלום?!","ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר,\u0006 תסויים השמועה\u0005]\u0006 ש\u0003שמואל\u0004 הוא ש\u0003אמר לרעה.\u0004 ש\u0003אמר ר' חייא בר אבין אמר שמואל: מושכני הרי היא כגולה ל\u0004ענין \u0003יוחסים.\u0004 ואף \u0003מישון לא חשו\u0004 \u0005[חששו]\u0006 \u0003לה לא משום עבדות ולא משום ממזרות, אלא כהנים שהיו בה לא הקפידו על הגרושות,\u0004 ואם יש לחשוש לכשרותם של אנשי מישון, הריהו משום פסול חללים, ולא פסול אחר. ואילו לשיטה שנאמרו הדברים לטובה, בני מישון בני עבדים הם.","ודוחים: \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003שמואל\u0004 הוא ש\u0003אמר לטובה, ו\u0004אין זו סתירה, שכן \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: המפקיר עבדו\u0004 — \u0003יצא\u0004 העבד \u0003לחירות, ואינו צריך\u0004 אפילו \u0003גט\u0004 (שטר) \u0003שחרור,\u0004 והביא שמואל ראיה לדבריו ממה \u0003שנאמר: \"\u0004ו\u0003כל עבד איש מקנת כסף\"\u0004 (שמות יב, מד), והלשון \"עבד איש\" לכאורה קשה, וכי דווקא \u0003עבד\u0004 שהוא \u0003איש\u0004 ממין זכר \u0003ולא עבד אשה? אלא\u0004 הכוונה היא: \u0003עבד שיש לו רשות\u0004 ושלטון \u0003לרבו עליו\u0004 (עבד של איש) — \u0003קרוי עבד\u0004 שהוא בפועל עבדו של איש מסויים, \u0003עבד שאין לרבו רשות עליו,\u0004 כגון שהפקירו — \u0003אין\u0004 הוא \u0003קרוי עבד\u0004 אלא בן חורין.","\u0003אמר רב יהודה אמר שמואל:\u0004 משנתנו \u0003זו\u0004 לגבי יוחסין שממנה דייקנו כי אנשי בבל דווקא טהורים בייחוסם, אלו \u0003דברי ר' מאיר, אבל חכמים אומרים: כל ארצות בחזקת כשרות הם עומדות.\u0004","ומעירים: \u0003אמימר שרא ליה\u0004 \u0005[התיר לו]\u0006 \u0003לרב הונא בר נתן למינסב איתתא מחוזייתא\u0004 \u0005[לשאת אשה ממחוזא]\u0006 שהיתה מחוץ לגבולות בבל ליוחסין. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי\u0004 לאמימר: \u0003מאי דעתיך\u0004 \u0005[מהי דעתך]\u0006 שהתרת לו — מתוך ש\u0003אמר רב יהודה אמר שמואל: זו דברי ר' מאיר, אבל חכמים אומרים: כל ארצות בחזקת כשרות הן עומדות\u0004 והלכה כחכמים, \u0003והא בי\u0004 \u0005[והרי\u0006 \u0003בית\u0004 מדרשו\u0005]\u0006 של \u0003רב כהנא לא מתני הכי\u0004 \u0005[היו שונים כך]\u0006 \u0003ובי\u0004 \u0005[ובית\u0006 מדרשו\u0005]\u0006 של \u0003רב פפא לא\u0004 \u0003מתני הכי\u0004 \u0005[שנו כך],\u0006 \u0003ובי\u0004 \u0005[ובית\u0006 מדרשו\u0005]\u0006 של \u0003רב זביד לא מתני הכי\u0004 \u0005[שנו כך]!\u0006 ומעירים: \u0003אפילו הכי\u0004 \u0005[כך],\u0006 למרות ששמע כל דעות אלה, \u0003לא קיבלה\u0004 אמימר \u0003מיניה\u0004 \u0005[ממנו],\u0006 ומדוע — \u0003משום דשמיע ליה\u0004 \u0005[ששמע\u0006 את ההלכה \u0005הזו]\u0006 \u0003מרב זביד\u0004 שמ \u0003נהרדעא\u0004 ועליו סמך ביותר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ממזירי ונתיני\u0004 (ממזרים ונתינים) יהיו \u0003טהורים לעתיד לבא,\u0004 אלו \u0003דברי ר' יוסי. ר' מאיר אומר: אין טהורים. אמר לו ר' יוסי: והלא כבר נאמר \"וזרקתי עליכם מים טהורים וטהרתם\u0004 מכל טומאותיכם ומכל גלוליכם אטהר אתכם\u0003\"\u0004 (יחזקאל לו, כה)! \u0003אמר לו ר' מאיר: כשהוא אומר \"מכל טמאותיכם ומכל גלוליכם\"\u0004 (שם) הרי יש בכך הדגשה: מאלה \u0003ולא מן הממזרות. אמר לו ר' יוסי:\u0004 בסוף הכתוב \u0003כשהוא אומר \"אטהר אתכם\"\u0004 — \u0003הוי אומר אף מן הממזרות.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' מאיר\u0004 שממזרים עדיין יישארו מרוחקים \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בנבואה לעתיד לבוא: \u0003\"וישב ממזר באשדוד\"\u0004 (זכריה ט, ו), כלומר, יהיה להם מקום נפרד משלהם, \u0003אלא לר' יוסי מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וישב ממזר באשדוד\"?\u0004 ומשיבים: \u0003כדמתרגם\u0004 \u0005[כמו שהיה מתרגם]\u0006 \u0003רב יוסף: יתבון\u0004 \u0005[ישבו]\u0006 \u0003בית ישראל לרוחצן בארעהון דהוו דמו בה לנוכראין\u0004 \u0005[בשלווה בארצם שהיו דומים בה כנכרים],\u0006 שמפרש ממזר כמו \"מעם זר\".","\u0003אמר רב יהודה, אמר שמואל: הלכה כר' יוסי. אמר רב יוסף: אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003אמר רב יהודה אמר שמואל הלכה כר' יוסי, הוה אתי\u0004 \u0005[היה בא]\u0006 \u0003אליהו מפיק מינן צוורני צוורני קולרין\u0004 \u0005[היה מוציא מאתנו קבוצות קבוצות\u0006 של \u0005אסורים],\u0006 כלומר, שהיה מגלה כמה ממזרים יש בישראל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גר נושא ממזרת\u0004 לכתחילה, אלו \u0003דברי ר' יוסי. ר' יהודה אומר: גר לא ישא ממזרת. אחד גר אחד עבד משוחרר וחלל\u0004 כולם \u0003מותרים בכהנת.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי?\u0004 ועונים: \u0003חמשה קהלי כתיבי\u0004 \u0005[חמש\u0006 פעמים נאמר \u0005\"קהל\"]\u0006 לגבי פסולים שונים שנאסר עליהם לבוא בקהל ה'."],["\u0003חד\u0004 \u0005[אחד]\u0006 נאמר \u0003לכהנים\u0004 שאסור לפסולים לבוא בקהלם, \u0003וחד\u0004 \u0005[ואחד]\u0006 — \u0003ללוים, וחד\u0004 \u0005[ואחד]\u0006 — \u0003לישראלים, וחד\u0004 \u0005[ואחד]\u0006 — \u0003למישרי\u0004 \u0005[להתיר]\u0006 \u0003ממזר בשתוקי,\u0004 שרק בקהל ה' אסור לו לבוא אבל הוא מותר במי שאינו נמנה בודאות עם הקהל, \u0003וחד\u0004 \u0005[ואחד]\u0006 — \u0003למישרי\u0004 \u0005[להתיר]\u0006 \u0003שתוקי בישראל,\u0004 לפי שלא נאסר לבוא בקהל אלא מי שהוא ודאי ממזר. ואילו \u0003קהל גרים לא איקרי\u0004 \u0005[נקרא]\u0006 \u0003קהל\u0004 כלל, ולכן מותר בפסולי חיתון. \u0003ור' יהודה\u0004 סבור: \u0003כהנים ולוים מחד \"קהל\" נפקי\u0004 \u0005[מ\"קהל\" אחד\u0006 הם \u0005יוצאים,\u0006 נלמדים\u0005]\u0006 משום שהם שייכים לשבט אחד. \u0003אייתר ליה\u0004 \u0005[נשאר לו]\u0006 \"קהל\" אחד \u0003לקהל גרים\u0004 שגם בו אסור ממזר לבוא.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ר' יהודה סובר כמו ר' יוסי, כי לויים וכהנים \u0003תרי קהלי נינהו\u0004 \u0005[שני קהלים הם],\u0006 שהרי יש לכהנים דינים מיוחדים לענין נישואין, אלא שלדעת ר' יהודה \u0003ממזר בשתוקי, ושתוקי בישראל מחד \"קהל\" נפקא\u0004 \u0005[מ\"קהל\" אחד יוצא,\u0006 נלמד\u0005]\u0006 וזאת למדים ממה שנאמר \u0003\"לא יבא ממזר בקהל ה'\"\u0004 (דברים כג, ג), לדייק ולומר לנו:","\u0003ממזר ודאי הוא\u0004 ש\u0003לא יבא, הא\u0004 \u0005[הרי]\u0006 \u0003ממזר ספק\u0004 (כגון שתוקי, שיש בו רק חשש ממזרות) — \u0003יבא,\u0004 וכן \u0003בקהל ודאי הוא\u0004 ש\u0003לא יבא\u0004 הממזר, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בקהל ספק\u0004 של שתוקים — \u0003יבא,\u0004 ואם כן יש מכתוב זה היתר בשניהם. ומכל מקום לדעת ר' יהודה נותר \"קהל\" אחד לאסור גם את הגר בממזרת.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הני נמי\u0004 \u0005[אלה,\u0006 ממזר ודאי וממזר ספק, \u0005גם כן]\u0006 \u0003תרי קהלי נינהו\u0004 \u0005[שני קהלים הם]\u0006 וצריכים לכל אחד לימוד לעצמו, \u0003וטעמיה\u0004 \u0005[וטעמו]\u0006 של \u0003ר' יהודה מהכא\u0004 \u0005[מכאן],\u0006 ממה שנאמר: \u0003\"הקהל חקה אחת לכם ולגר הגר\"\u0004 (במדבר טו, טו), משמע שלענין \"קהל\" אף הגרים נחשבים כישראל. \u0003ול\u0004דעת \u0003ר' יוסי:\u0004 כיון שנאמר \u0003\"חקה אחת\"\u0004 באמצע — \u0003הפסיק הענין,\u0004 לומר שאין הגרים נחשבים כקהל ה'.","על מה ששנו בברייתא ש\u0003אחד גר, ואחד עבד משוחרר ו\u0004כן \u0003חלל\u0004 — \u0003מותרין בכהנת,\u0004 מעירים: \u0003מסייעא ליה\u0004 \u0005[מסייע לו]\u0006 דבר זה \u0003ל\u0004שיטת \u0003רב.\u0004 ש\u0003אמר רב יהודה אמר רב: לא הוזהרו כשירות\u0004 כגון כהנות \u0003להנשא לפסולים\u0004 לכהונה (חללים), שאין האיסור אלא על כהנים זכרים.","\u0003דרש ר' זירא במחוזא: גר מותר בממזרת. רגמוהו כולי עלמא באתרוגייהו\u0004 \u0005[כל העם באתרוגיהם]\u0006 שהיו שם גרים רבים שנעלבו מדבריו, שנראה מהם שהגרים אינם נחשבים כקהל ה'. \u0003אמר רבא: מי איכא דדריש מילתא כי האי בדוכתא דשכיחי גיורי\u0004 \u0005[האם יש\u0006 אדם \u0005שידרוש דבר כזה במקום שמצויים\u0006 בו \u0005גרים]\u0006 וכיצד לא נזהר בדבריו? \u0003דרש רבא\u0004 עצמו \u0003במחוזא\u0004 כדי לתקן את הדבר: \u0003גר מותר בכהנת. טענוהו בשיראי\u0004 \u0005[נשאו אותו על משי]\u0006 משום שהעלה את כבודם של הגרים. \u0003הדר דרש להו\u0004 \u0005[חזר\u0006 ו\u0005דרש להם]\u0006 בפעם אחרת: \u0003גר מותר בממזרת. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אפסידתא לקמייתא\u0004 \u0005[הפסדת את\u0006 הכבוד של הפעם \u0005הראשונה].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דטבא לכו עבדי לכו\u0004 \u0005[\u0006מה \u0005שטוב לכם עשיתי לכם].\u0006 שכן \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 הגר — \u0003מהכא נסיב\u0004 \u0005[מכאן\u0006 הוא \u0005נושא],\u0006 מן המיוחסות \u0003ואי בעי\u0004 \u0005[ואם\u0006 \u0003רוצה]\u0004 — \u0003מהכא נסיב\u0004 \u0005[מכאן\u0006 הוא \u0005נושא],\u0006 מן הפסולות.","ומסכמים: \u0003והילכתא\u0004 \u0005[והלכה]\u0006 היא: \u0003גר מותר בכהנת ומותר בממזרת.\u0004 ומסבירים: \u0003מותר בכהנת\u0004 — כי \u0003לא הוזהרו כשירות להנשא לפסולים, ומותר בממזרת\u0004 — \u0003כ\u0004שיטת \u0003ר' יוסי\u0004 שאין קהל גרים קרוי קהל.","שנינו במשנה: \u0003אלו הן שתוקי\u0004 — \u0003כל שמכיר\u0004 את אמו ואינו מכיר את אביו. \u0003אמר רבא: דבר תורה שתוקי כשר\u0004 לבוא בקהל. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003רוב כשרים אצלה,\u0004 כלומר, רוב אנשים לגבי אשה פנויה הם כשרים \u0003ומיעוט\u0004 בלבד הם \u0003פסולין אצלה,\u0004 שיכול להיות הולד מהם ממזר.","\u0003ו\u0004אם כן, \u0003אי אזלי אינהו לגבה\u0004 \u0005[אם הלכו הם אליה],\u0006 שהבועל הלך אצלה, אם כן לפי הכלל הנוגע לספק איסור העומד לפנינו: \u0003כל דפריש\u0004 \u0005[הפורש]\u0006 ממקומו הקבוע — תולים אנו כי \u0003מרובא פריש\u0004 \u0005[מן הרוב\u0006 הוא \u0005פורש],\u0006 ואם כן יש לומר שזה שבא עליה היה מן הרוב הכשרים. אלא \u0003מאי אמרת\u0004 \u0005[מה אתה אומר]\u0006 — \u0003דילמא אזלה איהי לגבייהו\u0004 \u0005[שמא הלכה היא אליהם]\u0006 ושם נבעלה ואז \u0003הוה ליה\u0004 \u0005[הריהי]\u0006 ספק איסור הנמצא במקומו ה\u0003קבוע, ו\u0004כלל הוא בידינו: \u0003כל קבוע כמחצה על מחצה דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 ואין הולכים בו אחר הרוב.","מכל מקום אין בכך כדי לפסול את בנה השתוקי הואיל \u0003והתורה אמרה \"לא יבא ממזר\u0004 בקהל ה'\u0003\"\u0004 (דברים כג, ג), ולמדנו: \u0003ממזר ודאי הוא\u0004 ש\u0003לא יבא, הא\u0004 \u0005[הרי]\u0006 \u0003ממזר ספק\u0004 — \u0003יבא.\u0004 וכן \u0003בקהל ודאי הוא\u0004 ש\u0003לא יבא, הא\u0004 \u0005[הרי]\u0006 \u0003בקהל ספק יבא.\u0004","\u0003ומה טעם אמרו\u0004 בכל זאת שה\u0003שתוקי פסול\u0004 — לא מפני פסול ממזרות שבו, אלא \u0003גזירה,\u0004 מאחר שאין אביו ידוע, \u0003שמא\u0004 יזדמן ש\u0003ישא אחותו מאביו.\u0004 ושואלים: \u0003אלא מעתה,\u0004 אם זה החשש, \u0003שתוקי\u0004 אפילו \u0003שתוקית לא ישא, שמא ישא אחותו מאביו!\u0004","ואומרים: \u0003כל כי הני מזנו ואזלי\u0004 \u0005[וכי עד כדי כך\u0006 אנשים \u0005מזנים והולכים]\u0006 שנייחס לאותו אב את כל השתוקים שבעיר? הרי לפי דרך זו נצטרך לגזור שגם \u0003בת שתוקית\u0004 שנולדה מנישואין כשרים \u0003לא ישא\u0004 אותה שתוקי, \u0003שמא ישא אחותו מאביו!\u0004 שהרי ייתכן שהאיש שנשא שתוקית זו הוא אביו! \u0003אלא\u0004 יש לומר כי \u0003לא שכיחא\u0004 \u0005[אינו מצוי]\u0006 שיזדמן לו לשאת דווקא את אחותו, אם כן \u0003הכי נמי לא שכיחא\u0004 \u0005[כך גם כן אינו מצוי]\u0006 שתזדמן לו אחותו! ואם כן מה טעם אסרו את השתוקי?","ועונים כי איסור השתוקי אינו מפני חשש הלכתי, אלא \u0003מעלה עשו ביוחסין,\u0004 שלא יבואו בישראל אנשים שאין יודעים מאיזו משפחה הם.","\u0003ו\u0004עוד באותו ענין \u0003אמר רבא, דבר תורה: אסופי,\u0004 ילד שנאסף מן השוק ואין ידועים הוריו — \u0003כשר. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003אשת איש\u0004 שהרתה מזנות — \u0003בבעלה\u0004 היא \u0003תולה,\u0004 והכל חושבים שהילד הוא של בעלה. וכיון שאין הדבר נודע אין לה טעם להשליכו בשוק, ואם נמצא בשוק ודאי כשר הוא. ואלא \u0003מאי איכא\u0004 \u0005[מה יש],\u0006 באיזה אופן יכול להיות ממזר שאמו רוצה להפטר ממנו — רק \u0003מיעוט\u0004 של \u0003ארוסות\u0004 שזנו שאינן יכולות לתלות את הולד בארוס או \u0003מיעוט\u0004 של נשים \u0003שהלך בעליהם למדינת הים\u0004 שאינן יכולות לתלות שהילד הוא ממנו — גם למיעוט זה אין לחשוש,","\u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 מקרים רבים של \u0003פנויה\u0004 שהתעברה ואינה רוצה בילד אף שאינו ממזר, \u0003ואיכא נמי\u0004 \u0005[ויש גם כן]\u0006 ילדים כשרים שמשליכים אותם הוריהם \u0003מחמת רעבון,\u0004 ואם כן \u0003הוה\u0004 \u0005[הרי]\u0006 החשש שהילד הוא ממזר הוא לכל היותר \u0003פלגא ופלגא\u0004 \u0005[מחצה על מחצה].\u0006 \u0003והתורה אמרה \"לא יבא ממזר בקהל ה'\",\u0004 ואמרנו: \u0003ממזר ודאי הוא\u0004 ש\u0003לא יבא, הא\u0004 \u0005[הרי]\u0006 \u0003ממזר ספק יבא. בקהל ודאי הוא\u0004 ש\u0003לא יבא, הא\u0004 \u0005[הרי]\u0006 \u0003בקהל ספק יבא.\u0004","\u0003ומה טעם אמרו אסופי פסול\u0004 — \u0003שמא ישא אחותו מאביו.\u0004 ותוהים: \u0003אלא\u0004 לפי שיטה זו \u0003מעתה אסופי\u0004 גם \u0003אסופית לא ישא, שמא\u0004 יזדמן ש\u0003ישא אחותו בין מאביו בין מאמו!\u0004 ודוחים: \u0003כל הני שדי ואזלי\u0004 \u0005[\u0006וכי את \u0005כל אלה משליכים והולכים]?!\u0006 שהורים ישליכו גם את הבן וגם את הבת? אם כן: אפילו \u0003בת אסופי לא ישא, שמא ישא אחותו! אלא\u0004 צריך לומר ש\u0003לא שכיח\u0004 הדבר ומשום כך לא גזרו בזה, ואם כן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003לא שכיח\u0004 שיפגע באחותו דווקא.","\u0003אלא\u0004 יש לומר כמו שאמרנו בשתוקי, שאין הדבר מפני חשש איסור אלא משום ש\u0003מעלה עשו ביוחסים.\u0004","\u0003אמר רבא בר רב הונא:\u0004 ילד עזוב ש\u0003מצאו\u0004 שהוא \u0003מהול\u0004 —"],["\u0003אין בו משום אסופי,\u0004 שאם לא היה ילד כשר לא היו דואגים למולו. וכן אם \u0003משלטי הדמיה\u0004 \u0005[איבריו מתוקנים],\u0006 שנראה שטיפלו בו אחר לידתו — \u0003אין בו משום אסופי.\u0004 וכן אם היה \u0003שייף משחא ומלא כוחלא\u0004 \u0005[משוח בשמן או\u0006 עיניו \u0005משוחות בכחול],\u0006 או \u0003רמי חומרי\u0004 \u0005[ענוד טבעות],\u0006 או \u0003תלי פיתקא, ותלי קמיעא\u0004 \u0005[תלוי\u0006 עליו \u0005פתק או תלוי\u0006 עליו \u0005קמיע]\u0006 — \u0003אין בו משום אסופי.\u0004","אם היה ילד שנמצא \u0003תלי בדיקלי\u0004 \u0005[תלוי בדקל],\u0006 \u0003אי מטיא ליה\u0004 \u0005[אם\u0006 היה במקום כזה ש\u0005מגיעה אליו]\u0006 \u0003חיה\u0004 — \u0003יש בו משום אסופי, אם לאו\u0004 \u0005[לא],\u0006 שהוא מונח בדקל במקום שחיה אינה יכולה להגיע אליו — \u0003אין בו משום אסופי,\u0004 שנראה שדאגו לו והניחוהו במקום המשתמר.","וכן אם מונח הילד ב\u0003זרדתא סמיכא למתא\u0004 \u0005[חורשה\u0006 ה\u0005סמוכה לעיר]\u0006 שהוא מקום שאין מצויים בו אנשים — \u0003יש בו משום אסופי, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין בו משום אסופי.\u0004 אם היה הילד ב\u0003בי כנישתא סמיכתא למתא ושכיחי ביה\u0004 \u0005[בית הכנסת\u0006 ה\u0005סמוך לעיר ומצויים בו]\u0006 \u0003רבים\u0004 — \u0003אין בו משום אסופי,\u0004 אלא שרצו לתת את הילד לאחרים, \u0003ואם לאו\u0004 \u0005[לא],\u0006 שאיננו סמוך לעיר או שאין אנשים מצויים שם — \u0003יש בו משום אסופי.\u0004","\u0003אמר אמימר: האי פירא דסופלי\u0004 \u0005[בור זה ששמים בו גרעיני תמרים]\u0006 למאכל בהמות, אם נמצא בו ילד — \u0003יש בו משום אסופי,\u0004 אבל אם נמצא ב\u0003חריפתא דנהרא\u0004 \u0005[אמצע הנהר]\u0006 ששם יש זרימת מים מהירה ואניות עוברות שם — \u0003אין בו משום אסופי.\u0004 אם מונח ב\u0003פשרי\u0004 \u0005[מקום צדדי\u0006 בנהר\u0005]\u0006 — \u0003יש בו משום אסופי.\u0004 ילד שנמצא ב\u0003צידי רשות הרבים\u0004 שאין רבים דורסים שם — \u0003אין בו משום אסופי.\u0004 נמצא ב\u0003רשות הרבים\u0004 עצמה במקום שהיה עלול להדרס — \u0003יש בו משום אסופי.\u0004","\u0003אמר רבא: ובשני\u0004 (ובשנות) \u0003רעבון אין בו משום אסופי.\u0004 ושואלים: \u0003הא\u0004 \u0005[זו]\u0006 שאמר \u0003רבא אהייא\u0004 \u0005[על איזו]\u0006 פרט בהלכה זו נאמרה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שעל \u0003רשות הרבים\u0004 — וכי \u0003איידי\u0004 \u0005[מתוך]\u0006 שהן \u0003שני רעבון קטלא ליה\u0004 \u0005[הורגת\u0006 היא \u0005אותו]\u0006 הייתכן שהאם מניחה אותו במקום שעלול להדרס?! \u0003ואלא\u0004 תאמר שדברי רבא מוסבים על \u0003צידי\u0004 \u0005[על צידי]\u0006 \u0003רשות הרבים\u0004 — אולם במקרה זה \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003שני רעבון? אפילו בלא שני רעבון,\u0004 אם מונח במקום כזה, הרי זה מונח על דעת שהוא מקום שמור, שסבור שימצאו אותו!","\u0003אלא\u0004 יש לומר \u0003כי אתמר\u0004 \u0005[כאשר נאמרה]\u0006 הלכתו של \u0003רבא\u0004 — \u0003אהא דאמר\u0004 \u0005[\u0006היא \u0005על מה שאמר]\u0006 \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003ר' אבא, אמר ר' יהודה בר זבדי, אמר רב: כל זמן ש\u0004הילד העזוב עדיין \u0003בשוק\u0004 — \u0003אביו ואמו נאמנים עליו,\u0004 שיכולים להעיד שילד זה הוא שלהם, אבל אם \u0003נאסף\u0004 כבר \u0003מן השוק\u0004 — \u0003אין נאמנים עליו.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר רבא: הואיל ויצא עליו\u0004 כבר \u0003שם אסופי\u0004 אינם נאמנים לבטל ממנו שם זה. \u0003ו\u0004על כך \u0003אמר רבא: ובשני רעבון, אף על פי שנאסף מן השוק\u0004 הרי \u0003אביו ואמו נאמנים עליו,\u0004 שבשנים כאלה מצוי הדבר יותר ומסתבר שאומרים ההורים אמת.","\u0003אמר רב חסדא: שלשה נאמנים לאלתר\u0004 \u0005[מיד],\u0006 כלומר, דווקא כאשר מעידים מיד על הדבר, אף שאינם נאמנים כרגיל להיות עדים, \u0003אלו הן: אסופי, חיה\u0004 (מיילדת) \u0003ופוטרת חברותיה\u0004 מחשש טומאה. כיצד?","\u0003אסופי\u0004 — \u0003הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 שהוריו יכולים להעיד עליו שהוא בנם לפני שנאסף.","\u0003חיה\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חיה נאמנת לומר\u0004 ילד \u0003זה יצא ראשון ו\u0004ילד \u0003זה יצא\u0004 \u0003שני,\u0004 לענין בכורה ולכל הדינים הנובעים מכך. \u0003במה דברים אמורים\u0004 — \u0003שלא יצתה\u0004 (יצאה) מאותו חדר \u0003וחזרה, אבל\u0004 אם כבר \u0003יצתה וחזרה\u0004 — \u0003אינה נאמנת\u0004 שאולי נתחלפו בינתיים. \u0003ר' אליעזר אומר:\u0004 אם \u0003הוחזקה על עומדה\u0004 (במקומה) — \u0003נאמנת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה נאמנת.\u0004 ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ההבדל\u0006 ביניהם\u0005]\u0006 למעשה? ומשיבים: \u0003איכא בינייהו דאהדר אפה\u0004 \u0005[יש ביניהם\u0006 הבדל כ\u0005שהחזירה\u0006 המיילדת \u0005פניה]\u0006 לצד אחר לאחר הלידה, שלדעת ר' אליעזר שוב אינה נאמנת.","\u0003פוטרת חברותיה מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 — \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שלש נשים שהיו ישנות במטה אחת ונמצא דם תחת אחת מהן\u0004 — \u0003כולן טמאות\u0004 טומאת נידה, שאין אנו יודעים מאיזו מהן יצא הדם. ואם \u0003בדקה אחת מהן\u0004 לאחר מכן \u0003ונמצאת טמאה,\u0004 כלומר, שהיא עדיין נידה — \u0003היא טמאה, וכולן טהורות.\u0004 ועל כך \u0003אמר רב חסדא:\u0004 והוא \u0003שבדקה עצמה כשיעור ווסת,\u0004 כלומר, בסמוך לאותו מאורע, אבל אם היה זה אף זמן מועט לאחר מכן — אין זו הוכחה שממנה שתת הדם מתחילה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם ילדו מספר נשים כמה ילדים בזמן אחד, \u0003נאמנת חיה\u0004 (מיילדת) \u0003לומר: זה כהן וזה לוי, זה נתין וזה ממזר,\u0004 שאומרת למי מן הנשים נולד כל אחד מן הילדים. \u0003במה דברים אמורים\u0004 — \u0003שלא קרא עליה שם ערער,\u0004 כלומר, שלא היה ערעור על הוולד הזה שאמרו שהוא פסול, \u0003אבל קרא עליה ערער\u0004 — \u0003אינה נאמנת.\u0004","ומבררים: \u0003ערער דמאי\u0004 \u0005[על מה]\u0006 כיצד היה ערעור זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ערער חד\u0004 \u0005[\u0006עד \u0005אחד]\u0006 שבא והעיד ההיפך, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: אין ערער פחות משנים! אלא\u0004 יש לומר כי מדובר ב\u0003ערער תרי\u0004 \u0005[\u0006של \u0005שניים],\u0006 אבל כנגד אחד — היא נאמנת.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי אף ב\u0003ערער חד\u0004 \u0005[אחד]\u0006 אינה נאמנת. \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003אמר ר' יוחנן אין ערער פחות משנים\u0004 — \u0003הני מילי היכא דאיתא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום שיש]\u0006 \u0003חזקה\u0004 של \u0003כשרות,\u0004 ולכן רק שניים יכולים לבטל אותה, \u0003אבל היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003חזקה\u0004 של \u0003כשרות\u0004 — \u0003חד נמי מהימן\u0004 \u0005[\u0006עד \u0005אחד גם כן נאמן].\u0006","וכן \u0003נאמן בעל מקח\u0004 (המוכר), כאשר טוענים שני אנשים וכל אחד אומר שהוא הקונה, \u0003לומר: לזה מכרתי, ולזה אין מכרתי. במה דברים אמורים\u0004 — \u0003בזמן שמקחו\u0004 (החפץ שהתכוון למכור) עדיין \u0003בידו\u0004 של המוכר, \u0003אבל אין מקחו בידו\u0004 — \u0003אינו נאמן,\u0004 והריהו ככל עד אחד."]]};
